# ===== QUARK-FIX v1 =====
# 夸克线路探活 + 过滤：修复"网盘放不了"
#   原问题1: _filter_quark_lines 里 `if False: continue` 是空壳，探活函数根本没被调用
#   原问题2: from/url 两条列表长度不一致时只取到前 N 条，后面的线路被静默砍掉
#   原问题3: _agg_client_local() 在设备端基本起不来，探活直接 return True 放行死链
# 现在: 探活走"模块级 QuarkDrive(优先带cookie)"直连，结果缓存 TTL 秒内复用，
#       任何异常都退化为"保留该线路"（宁可多一条也不可误删），且不阻断详情接口。

_QUARK_PROBE_TTL = 180.0          # 探活结果缓存秒数
_QUARK_PROBE = {}                 # 线路地址 -> (到期时间, 是否可播)
_QUARK_PROBE_ON = True            # 总开关：False 则完全不做探活，原样保留所有线路
_QUARK_DROP_DEAD = True           # True=剔除探活失败的线路；False=只标记不剔除

_QUARK_FAIL = {}                  # (pwd_id,fid) -> 到期时间：短期内取不到直链的，别再反复重列
_QUARK_DRIVE = None
_QUARK_DRIVE_TRIED = False


def _quark_drive():
    """懒加载一个模块级夸克客户端：有 cookie 用 cookie（会员稳），没有就匿名。
    只在第一次调用时构造，失败就永久放弃，避免每条线路都重试拖慢详情。"""
    global _QUARK_DRIVE, _QUARK_DRIVE_TRIED
    if _QUARK_DRIVE_TRIED:
        return _QUARK_DRIVE
    _QUARK_DRIVE_TRIED = True
    try:
        ck = ""
        try:
            ck = _dump(_local_quark_cookie()).strip()
        except Exception:
            ck = ""
        _QUARK_DRIVE = QuarkDrive(ck)
    except Exception:
        _QUARK_DRIVE = None
    return _QUARK_DRIVE


def _quark_split(line_url):
    """把一条线路的选集串拆出 (pwd_id, fid, fid_token, 是否夸克线)。
    兼容裸 Q~ 与 agg:Q~ 两种包装；非夸克线返回 (None,None,None,False)。"""
    try:
        first = str(line_url or "").split("#")[0]
        if "$" in first:
            first = first.split("$", 1)[1]
        if first.startswith("agg:") and "|" in first:
            first = first.split("|", 1)[1]
        if not first.startswith("Q~") or "+" not in first:
            return None, None, None, False
        rest = first[2:].split("#")[0]
        head, p2, ft = rest.rsplit("+", 2)
        p1 = head.split("__", 1)[-1] if "__" in head else head
        # 原逻辑：pwd_id 是短的口令，fid 是长的文件 id
        if len(p1) <= 20 and len(p2) > 20:
            pwd, fid = p1, p2
        elif len(p2) <= 20 and len(p1) > 20:
            pwd, fid = p2, p1
        else:
            pwd, fid = p2, p1
        return pwd, fid, ft, True
    except Exception:
        return None, None, None, False


def _quark_line_anon_ok(u):
    """这条夸克线现在能不能真的拿到直链且可拉流。结果缓存 _QUARK_PROBE_TTL 秒。
    拿不到客户端 / 任何异常 => 返回 True（保留），绝不误删好线路。"""
    if not _QUARK_PROBE_ON:
        return True
    try:
        key = str(u or "")
        hit = _QUARK_PROBE.get(key)
        if hit and hit[0] > time.time():
            return hit[1]
        pwd, fid, ft, is_q = _quark_split(key)
        if not is_q:
            return True
        ob = _quark_drive()
        if ob is None:
            return True
        dl, h, sz = ob._quark_fresh_link(pwd, fid, ft)
        ok = bool(dl) and _stream_ok(dl, h, timeout=5)
        _QUARK_PROBE[key] = (time.time() + _QUARK_PROBE_TTL, ok)
        return ok
    except Exception:
        return True


def _filter_quark_lines(vod):
    """剔除匿名取不到直链的夸克线；非夸克线一律原样保留。
    修复点：from/url 按索引对齐，长度不齐时不再静默截断。"""
    if not _QUARK_PROBE_ON:
        return
    try:
        fs = [_dump(x) for x in _dump(vod.get("vod_play_from")).split("$$$")]
        us = [_dump(x) for x in _dump(vod.get("vod_play_url")).split("$$$")]
        if not fs and not us:
            return
        # 以较长的为准对齐，缺失侧补空串，避免线路被砍
        n = max(len(fs), len(us))
        fs = (fs + [""] * n)[:n]
        us = (us + [""] * n)[:n]
        kf, ku = [], []
        for i in range(n):
            f, u = fs[i], us[i]
            if not f and not u:
                continue
            if f and _quark_split(u)[3]:          # 是夸克线才探
                if _QUARK_DROP_DEAD and not _quark_line_anon_ok(u):
                    continue
            kf.append(f)
            ku.append(u)
        if not kf and fs:                          # 全被剔除时保底：留原样，别让详情页空了
            return
        vod["vod_play_from"] = "$$$".join(kf)
        vod["vod_play_url"] = "$$$".join(ku)
    except Exception:
        pass


