def _db_ns(tags, sort="S", start=0, limit=20):
    """豆瓣影视库筛选接口：tags 可组合（电影/电视剧,类型,地区,年代,平台）。"""
    key = "ns:%s:%s:%s" % (sort, tags, start)
    cached = _db_cache.get(key)
    if cached and cached[0] > time.time():
        return cached[1]
    params = {"sort": sort, "range": "0,10", "tags": tags, "start": start}
    items = []
    for attempt in range(3):
        data = _db_json(NS_API, params, 12)
        rows = (data or {}).get("data") if isinstance(data, dict) else data
        if rows:
            items = rows
            break
        time.sleep(0.5 * (attempt + 1))
    items = items[:limit]
    if items:
        _db_cache[key] = (time.time() + DB_TTL, items)
        while len(_db_cache) > 60:
            _db_cache.pop(next(iter(_db_cache)), None)
    return items


def _db_abstract(sid):
    """轻量条目摘要（含 release_year / region / types），用来给列表补年份。"""
    sid = _dump(sid)
    if not sid:
        return {}
    key = "abs:%s" % sid
    cached = _db_cache.get(key)
    if cached and cached[0] > time.time():
        return cached[1]
    data = _db_json("https://movie.douban.com/j/subject_abstract",
                    {"subject_id": sid}, 8) or {}
    subject = data.get("subject") if isinstance(data, dict) else None
    subject = subject if isinstance(subject, dict) else {}
    _db_cache[key] = (time.time() + DB_TTL, subject)
    return subject


def _fill_years(rows, limit=20):
    """列表里缺年份的条目，用轻量摘要并发补齐（最多补一页的量）。"""
    todo = [r for r in rows
            if not _dump(r.get("vod_year")) or not _dump(r.get("vod_area"))][:limit]
    if not todo:
        return rows
    # 先支持 self.net 的同步实现，再退化到线程池
    abstract_of = _fill_years.abstract_of

    def _one(row):
        sid = _dump(row.get("vod_id")).partition(":")[2]
        subject = abstract_of(sid)
        if subject:
            row["vod_year"] = _dump(subject.get("release_year")) or row.get("vod_year") or ""
            if not row.get("vod_area"):
                row["vod_area"] = _dump(subject.get("region"))
            types = subject.get("types") or []
            if _dump(row.get("type_name")) in ("", "剧情"):
                names = [_dump(x) for x in types if _dump(x)]
                if names:
                    row["type_name"] = " / ".join(names)
        return row

    try:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=4) as pool:
            list(pool.map(_one, todo))
    except Exception:
        for row in todo:
            try:
                _one(row)
            except Exception:
                pass
    return rows


_fill_years.abstract_of = _db_abstract


def _db_chart(type_id, start, limit):
    data = _db_json(DB_CHART, {"type": type_id or "11", "interval_id": "100:90",
                               "action": "", "start": start, "limit": limit})
    return data if isinstance(data, list) else []


def _img_of(value):
    """豆瓣各榜单的图片字段结构不统一：有时是字符串，有时是 dict(url/large/normal)，有时是数组。"""
    if isinstance(value, str):
        value = _dump(value)
        return value if value.startswith("http") else ""
    if isinstance(value, dict):
        for key in ("url", "large", "normal", "small", "image", "src", "img"):
            found = _img_of(value.get(key))
            if found:
                return found
        return ""
    if isinstance(value, (list, tuple)):
        for entry in value:
            found = _img_of(entry)
            if found:
                return found
    return ""


def _poster(item):
    for key in ("cover_url", "pic", "cover", "img", "image", "photos",
                "tile_cover", "bg_image", "cover_img"):
        found = _img_of(item.get(key))
        if found:
            return found
    return ""


def _rating(item):
    rating = item.get("rating")
    if isinstance(rating, dict):
        value = rating.get("value")
        if value:
            return _dump(value)
    for key in ("rate", "score"):
        if item.get(key):
            return _dump(item.get(key))
    return ""


def _year_of(item):
    year = _dump(item.get("year"))
    if re.fullmatch(r"\d{4}", year):
        return year
    for key in ("card_subtitle", "info", "title", "sub_title"):
        found = re.search(r"(19|20)\d{2}", _dump(item.get(key)))
        if found:
            return found.group(0)
    return ""


def _row(item, kind=""):
    """把豆瓣条目整理成壳要的列表项。"""
    sid = _dump(item.get("id"))
    if not sid:
        url = _dump(item.get("url") or item.get("uri"))
        found = re.search(r"subject/(\d+)", url)
        sid = found.group(1) if found else ""
    if not sid:
        return None
    item_type = _dump(item.get("type") or item.get("category"))
    if item_type not in ("movie", "tv"):
        item_type = "tv" if re.search(r"/tv/", _dump(item.get("url"))) else (kind or "movie")
    remarks = _rating(item)
    if remarks:
        remarks = "豆瓣 %s" % remarks
    subtitle = _dump(item.get("card_subtitle"))
    parts = [x.strip() for x in subtitle.split("/") if x.strip()]
    info = _dump(item.get("episodes_info")) or (parts[0] if parts else "")
    if info and info != remarks:
        remarks = ("%s · %s" % (remarks, info)) if remarks else info
    area = " / ".join(_dump(x) for x in
                      (item.get("countries") or item.get("regions") or []) if _dump(x))
    if not area and parts:
        # 有的接口字幕是「年份 / 地区 / 类型…」，有的直接是「地区 / 类型…」
        if re.fullmatch(r"(19|20)\d{2}", parts[0]) and len(parts) > 1:
            area = parts[1]
        else:
            area = parts[0]
    return {
        "vod_id": "%s:%s" % (item_type, sid),
        "vod_name": _dump(item.get("title")),
        "vod_pic": _poster(item),
        "vod_remarks": remarks,
        "vod_year": _year_of(item),
        "vod_area": area,
        "type_name": " / ".join(_dump(x) for x in
                                (item.get("genres") or item.get("types") or []) if _dump(x)),
    }


def _rows(items, kind=""):
    rows = []
    for item in items or []:
        if isinstance(item, dict):
            row = _row(item, kind)
            if row and row.get("vod_name"):
                rows.append(row)
    return rows

_DUR_CACHE = {}


def _media_dur(url):
    """m3u8 总时长（秒）；不是 m3u8 或取不到就返回 0。芒果的 4K 档对部分集只给预告片，
    几十秒的假 4K 就是靠这个时长认出来。"""
    url = _dump(url)
    if not url or not _media_format(url) == "hls":
        return 0
    hit = _DUR_CACHE.get(url)
    if hit and hit[0] > time.time():
        return hit[1]
    try:
        txt = _http_text(url, {"User-Agent": MG_CDN_UA}, 15)
    except Exception:
        return 0
    total, got = 0.0, 0
    for m in re.finditer(r"#EXTINF:\s*([0-9.]+)", txt or ""):
        try:
            total += float(m.group(1))
            got += 1
        except Exception:
            pass
    total = total if got else 0
    _DUR_CACHE[url] = (time.time() + 1800, total)
    return total


def _line_label(x):
    """按实际地址判断当前是哪条线路，播放提示里直接显示名字。"""
    low = _dump(x).lower()
    if "cmecloud" in low:
        return "移动云"
    if "tjtele" in low or "189.cn" in low or "mini189" in low:
        return "天翼云"
    if "hydownload" in low or "pan.wo.cn" in low:
        return "联通云"
    if "byteimg" in low or "eiuytyu" in low:
        return "云帧享"
    if "meilinvps" in low:
        return "华谊"
    if "apdcdn" in low or "tc.qq.com" in low or "vlive" in low:
        return "腾讯"
    if low.startswith("agg:"):
        return "华谊"
    if low.startswith("yzx|"):
        return "云帧享"
    return ""


def _tag_from(name):
    """线路弹窗里标快慢，已标过的不重复。"""
    fn = _dump(name)
    if any(k in fn for k in ("·快", "·中", "·慢")):
        return fn
    if "移动云" in fn or "联通云" in fn or "天翼云" in fn:
        return fn + "·快"
    if "华谊" in fn:
        return fn + "·中"
    if "云帧享" in fn:
        return fn + "·慢"
    return fn


def _media_format(url: str) -> str:
    if re.search(r"\.m3u8?(?:[?#]|$)|mpegurl", url, re.I):
        return "hls"
    if re.search(r"\.mpd(?:[?#]|$)", url, re.I):
        return "mpd"
    return "mp4"


def _range_total(url, timeout=8):
    """用 Range 请求读 Content-Range 里的总字节数，用来估算单个分片大小。"""
    try:
        request = __import__("urllib.request").request
        req = request.Request(url, headers={"User-Agent": "", "Range": "bytes=0-1"})
        with request.urlopen(req, timeout=timeout) as resp:
            span = resp.headers.get("Content-Range") or ""
            resp.read(2)
        total = span.rsplit("/", 1)[-1]
        return int(total) if total.isdigit() else 0
    except Exception:
        return 0


def _quality_from_text(text: str, base: str = "") -> str:
    """从 m3u8 正文判定清晰度：主播放列表看分辨率／带宽，媒体列表按码率估算。"""
    if not text or "#EXTM3U" not in text:
        return ""
    if "#EXT-X-STREAM-INF" in text:
        heights = [int(x) for x in re.findall(r"RESOLUTION=\d+x(\d+)", text)]
        bandwidth = [int(x) for x in re.findall(r"BANDWIDTH=(\d+)", text)]
        if heights:
            height = max(heights)
            if height >= 2160:
                return "4K"
            if height >= 1440:
                return "2K"
            if height >= 1080:
                return "1080P"
            if height >= 720:
                return "720P"
            if height >= 480:
                return "480P"
            return "标清"
        if bandwidth:
            mbps = max(bandwidth) / 1e6
            for label, threshold in QUALITY_MBPS:
                if mbps >= threshold:
                    return label
    durations = sum(float(x) for x in re.findall(r"#EXTINF:([\d.]+)", text))
    sizes = [int(x) for x in re.findall(r"contentlength=(\d+)", text)]
    if durations > 0 and sizes:
        mbps = sum(sizes) / durations * 8 / 1e6
        for label, threshold in QUALITY_MBPS:
            if mbps >= threshold:
                return label
    # 媒体列表没有 contentlength（第三方 CDN 常见）：抽前几个分片量实际体积
    if base:
        segs = [line.strip() for line in text.splitlines()
                if line.strip() and not line.startswith("#")]
        seg_durs = [float(x) for x in re.findall(r"#EXTINF:([\d.]+)", text)]
        total, dur = 0, 0.0
        for index, seg in enumerate(segs[:2]):
            absolute = urljoin(base, seg)
            size = _range_total(absolute)
            if size and index < len(seg_durs):
                total += size
                dur += seg_durs[index]
        if total and dur:
            mbps = total / dur * 8 / 1e6
            for label, threshold in QUALITY_MBPS:
                if mbps >= threshold:
                    return label
    return ""


def _m3u8_quality(url: str, timeout=10) -> str:
    """按 m3u8 实际内容判定清晰度。第三方 CDN 常校验 Referer，两种头都试一次。"""
    if not re.search(r"m3u8|\.m3u\b|/hls/", str(url), re.I):
        return ""
    for headers in ({"User-Agent": UA}, {"User-Agent": UA, "Referer": REFERER}, {"User-Agent": ""}):
        try:
            text = _http_text(url, headers, timeout)
        except Exception:
            continue
        label = _quality_from_text(text, url)
        if label:
            return label
    return ""


