def _t3_boot():
    if _T3_ENV.get("T3Source"):
        return
    exec(compile(_T3_CODE, "t3", "exec"), _T3_ENV)
    _T3_ENV["src"] = _T3_ENV["T3Source"]("gg", 12.0)
    try:
        _T3_ENV["src_jz"] = _T3_ENV["T3Source"]("jz", 12.0)
    except Exception:
        pass

T3_CACHE = {}


def _t3_score(a, b):
    x = re.sub(r"[第\s·:：\-—_]|季|篇|剧场版|国语|粤语|普通话|版", "", _dump(a))
    y = re.sub(r"[第\s·:：\-—_]|季|篇|剧场版|国语|粤语|普通话|版", "", _dump(b))
    if not x or not y:
        return 0
    if x == y:
        return 100
    if x in y or y in x:
        return 85
    return 0


def t3_bfzy(name):
    """按片名取暴风资源（T3 后端 bfzym3u8）的分集直链 m3u8。"""
    key = _dump(name)
    if not key:
        return []
    hit = T3_CACHE.get(key)
    if hit and hit[0] > time.time():
        return hit[1]
    eps = []
    try:
        _t3_boot()
        src = _T3_ENV["src"]
        got = src.search(key)
        items = got.get("list") if isinstance(got, dict) else got
        best, score = None, 0
        for it in items or []:
            sc = _t3_score(key, it.get("vod_name"))
            if sc > score:
                best, score = it, sc
        if best and score >= 60:
            info = src.detail(best.get("vod_id"))
            for line in (info or {}).get("lines") or []:
                if _dump(line.get("code")) == "bfzym3u8" or "暴风" in _dump(line.get("name")):
                    for ep in line.get("eps") or []:
                        t, _, u = _dump(ep).partition("$")
                        if u.startswith("http"):
                            eps.append((t or "正片", u))
                    break
    except Exception:
        eps = []
    T3_CACHE[key] = (time.time() + (3600 if eps else 600), eps)
    while len(T3_CACHE) > 128:
        T3_CACHE.pop(next(iter(T3_CACHE)), None)
    return eps

GL_PREFIX = "gl:"
GL_CACHE = {}


def _gulu_line(name):
    """豆瓣条目挂一条「咕噜视频」4K 线：按片名搜咕噜，取 4K 线路全部分集。"""
    key = _dump(name)
    if not key:
        return ""
    hit = GL_CACHE.get(key)
    if hit and hit[0] > time.time():
        return hit[1]
    out = ""
    try:
        _t3_boot()
        src = _T3_ENV["src"]
        items = src.search(key) or []
        best, score = None, 0
        for it in items:
            sc = _t3_score(key, _dump(it.get("vod_name")))
            if sc > score:
                best, score = it, sc
        if best and score >= 80:
            info = src.detail(best.get("vod_id")) or {}
            lines = info.get("lines") or []
            pick = None
            for ln in lines:
                code = _dump(ln.get("code"))
                nm = _dump(ln.get("name"))
                if code in ("newxfyun", "xfyun") or ("咕噜" in nm and "4K" in nm):
                    pick = ln
                    break
            if pick is None:
                for ln in lines:
                    if "4K" in _dump(ln.get("name")):
                        pick = ln
                        break
            if pick:
                pid = _dump(pick.get("parser_id"))
                eps = []
                for ep in pick.get("eps") or []:
                    label, _, play = _dump(ep).partition("$")
                    if not play:
                        continue
                    if play.startswith("http"):
                        eps.append("%s$%s" % (label or "正片", play))
                    else:
                        token = base64.urlsafe_b64encode(play.encode("utf-8")).decode("ascii").rstrip("=")
                        eps.append("%s$%s%s:%s" % (label or "正片", GL_PREFIX, pid, token))
                if eps:
                    out = "#".join(eps)
    except Exception:
        out = ""
    GL_CACHE[key] = (time.time() + (6 * 3600 if out else 600), out)
    while len(GL_CACHE) > 60:
        GL_CACHE.pop(next(iter(GL_CACHE)), None)
    return out


XF_PREFIX = "xf:"
XF_CACHE = {}
_XF_ENV = {}


def _xf_boot():
    """内嵌稀饭聚合：只借它的小鸡/四源4K 两家源，补齐豆瓣缺的 4K 来源。"""
    if _XF_ENV.get("ok"):
        return _XF_ENV
    blob = (
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    ""
    )
    import zlib as _zlib
    src = _zlib.decompress(base64.b64decode(blob)).decode("utf-8")
    exec(compile(src, "xf_embed", "exec"), _XF_ENV)
    _XF_ENV["_xj"] = _XF_ENV["XiaojiSpider"]()
    _XF_ENV["_sk"] = _XF_ENV["SK4KSpider"]()
    _XF_ENV["ok"] = True
    return _XF_ENV


def _xf_pick(ob, name):
    items = ob.searchContent(name, False, "1").get("list") or []
    best, score = None, -1
    for it in items:
        sc = _t3_score(name, _dump(it.get("vod_name")))
        if sc > score:
            best, score = it, sc
    if not best or score < 85:
        return [], []
    data = ob.detailContent([best.get("vod_id")])["list"][0]
    froms = _dump(data.get("vod_play_from")).split("$$$")
    urls = _dump(data.get("vod_play_url")).split("$$$")
    return froms, urls


def _xf_eps(url, label, flag=None):
    out = []
    for ep in _dump(url).split("#"):
        lab, _p, tok = ep.partition("$")
        if not tok:
            continue
        payload = base64.urlsafe_b64encode(_dump(json.dumps(
            {"l": label, "f": flag or label.split("·")[0], "id": tok}, ensure_ascii=False)).encode("utf-8")).decode("ascii").rstrip("=")
        out.append("%s$%s%s" % (lab or "正片", XF_PREFIX, payload))
    return "#".join(out)


def _xf_4k_lines(name):
    """返回 [(线路名, 分集url)]：小鸡一条 + 四源4K 天堂/布布/苹果各一条，华谊重复不挂。"""
    key = _dump(name)
    if not key:
        return []
    hit = XF_CACHE.get(key)
    if hit and hit[0] > time.time():
        return hit[1]
    out = []
    box = {}

    def pull(tag):
        try:
            env = _xf_boot()
            ob = env["_xj" if tag == "xj" else "_sk"]
            box[tag] = _xf_pick(ob, key)
        except Exception:
            box[tag] = ([], [])

    th1 = threading.Thread(target=pull, args=("xj",))
    th2 = threading.Thread(target=pull, args=("sk",))
    th1.start(); th2.start()
    th1.join(3.4); th2.join(3.4)

    # 小鸡线路播放器只回 JD- 令牌，播放器放不出来，整条不挂。

    # 四源4K：天堂/布布/苹果 各保留一条集数最多的；华谊与豆瓣已有华谊重复，跳过
    fs, us = box.get("sk") or ([], [])
    groups = {}
    for f, u in zip(fs, us):
        f = _dump(f)
        if "4K" not in f:
            continue
        grp = f.split("·")[0]
        if grp == "华谊":
            continue
        n = len([x for x in _dump(u).split("#") if x])
        if n > groups.get(grp, ("", 0, ""))[1]:
            groups[grp] = (f, n, u)
    # 四源4K 算一个来源，只挂它最好的一条（天堂/苹果/布布 是同一家的子线，不重复挂）
    # 只挂「天堂」：布布/苹果回的是网页地址（/play/xxx），播放器放不出来。
    best_grp, best_n = None, 0
    for grp in ("天堂",):
        if grp in groups and groups[grp][1] > best_n:
            best_grp, best_n = grp, groups[grp][1]
    if best_grp:
        f, n, u = groups[best_grp]
        out.append(("四源4K·%s·快" % f, _xf_eps(u, "四源4K·" + f, f)))

    XF_CACHE[key] = (time.time() + (6 * 3600 if out else 600), out)
    while len(XF_CACHE) > 60:
        XF_CACHE.pop(next(iter(XF_CACHE)), None)
    return out


XF_ALL_CACHE = {}


def _xf_all_4k(name):
    """返回四源/天堂家所有 4K 线 [(标签, 分集令牌, 集数)]，按集数区分季。
    云线路要按同季集数选，不能再一律借集数最多的那条（会把第一季接到第四季）。"""
    key = _dump(name)
    if not key:
        return []
    hit = XF_ALL_CACHE.get(key)
    if hit and hit[0] > time.time():
        return hit[1]
    out = []
    try:
        env = _xf_boot()
        fs, us = _xf_pick(env["_sk"], key)
        for f, u in zip(fs, us):
            label = _dump(f)
            if "4k" not in label.lower():
                continue
            # 布布/苹果的 /play/ 网页和头条/西瓜的网页地址播放器放不出来
            if "布布" in label or "高清4k" in label:
                continue
            n = len([x for x in _dump(u).split("#") if x])
            if not n:
                continue
            out.append((label, _xf_eps(u, "四源4K·" + label, label), n))
    except Exception:
        out = []
    XF_ALL_CACHE[key] = (time.time() + (6 * 3600 if out else 600), out)
    while len(XF_ALL_CACHE) > 40:
        XF_ALL_CACHE.pop(next(iter(XF_ALL_CACHE)), None)
    return out


def _xf_score(label):
    _l = _dump(label)
    if "天堂" in _l and "真蓝光" in _l:
        return 6
    if "天堂" in _l:
        return 5
    if "苹果" in _l and "真蓝光" in _l:
        return 4
    if "华谊" in _l:
        return 3
    return 2



