def _sj_headers(full):
    ts = str(int(time.time() * 1000))
    nonce = "%032x" % random.getrandbits(128)
    msg = "GET\n%s\n%s\n%s" % (full, ts, nonce)
    sig = hmac.new(SJ_SIGN_KEY.encode("utf-8"), msg.encode("utf-8"),
                       hashlib.sha256).hexdigest()
    return {
        "accept": "application/json, text/plain, */*",
        "accept-language": "zh-CN,zh;q=0.9",
        "user-agent": SJ_UA,
        "referer": SJ_HOST + "/",
        "origin": SJ_HOST,
        "x-ai-movie-client-name": SJ_CLIENT,
        "x-ai-movie-client-version": SJ_CLIENT_VER,
        "x-ai-movie-build-version": SJ_BUILD,
        "x-ai-movie-protocol-version": SJ_PROTO,
        "x-ai-movie-timestamp": ts,
        "x-ai-movie-nonce": nonce,
        "x-ai-movie-signature": sig,
    }


def _sj_api(path, params=None, timeout=3):
    qs = "&".join("%s=%s" % (quote(str(k), safe=""), quote(str(v), safe=""))
                  for k, v in (params or {}).items() if v not in (None, ""))
    full = path + (("?" + qs) if qs else "")
    try:
        txt = _http_text(SJ_HOST + full, _sj_headers(full), timeout)
        return json.loads(txt)
    except Exception:
        return None


def _sj_norm_title(text):
    t = re.sub(r"[^0-9a-zA-Z\u4e00-\u9fff]", "", _dump(text)).lower()
    cn = {"一": "1", "二": "2", "三": "3", "四": "4", "五": "5",
          "六": "6", "七": "7", "八": "8", "九": "9", "十": "10"}
    t = re.sub(r"第([一二三四五六七八九十]+)季",
               lambda m: "第" + cn.get(m.group(1), m.group(1)) + "季", t)
    return t


