def _http_bytes(url, data=None, headers=None, timeout=15):
    """二进制请求：宿主走 self.net（buffer=1 取字节），本机走 urllib。"""
    if _NET is not None:
        options = {"timeout": _millis(timeout), "callTimeout": _millis(timeout), "buffer": 1}
        if headers:
            options["headers"] = dict(headers)
        if data is not None:
            options["method"] = "POST"
            options["body"] = list(data) if isinstance(data, (bytes, bytearray)) else data
        response = _NET.req(url, options)
        if isinstance(response, dict) and response.get("error") is not None:
            raise RuntimeError(str(response.get("error")))
        content = response.get("content") if isinstance(response, dict) else b""
        if isinstance(content, (bytes, bytearray)):
            return bytes(content)
        if isinstance(content, (list, tuple)):
            return bytes(content)
        return str(content or "").encode("utf-8")
    request = __import__("urllib.request").request
    h = {"User-Agent": UA}
    h.update(headers or {})
    req = request.Request(url, data=data, headers=h,
                          method="POST" if data is not None else "GET")
    with request.urlopen(req, timeout=timeout) as resp:
        return resp.read()


def _http_json_post(url, data=None, headers=None, timeout=15):
    text = _http_bytes(url, data, headers, timeout).decode("utf-8", "replace")
    i, j = text.find("{"), text.find("[")
    if i < 0 and j < 0:
        return None
    text = text[j:] if (i < 0 or (j >= 0 and j < i)) else text[i:]
    try:
        return json.loads(text)
    except Exception:
        return None


def _agg_b64_url(seg):
    text = str(seg or "").replace("-", "+").replace("_", "/")
    text += "=" * (-len(text) % 4)
    return base64.b64decode(text)


def _agg_token(info):
    payload = json.dumps(info, ensure_ascii=False, separators=(",", ":"))
    return AGG_TOKEN + base64.urlsafe_b64encode(payload.encode("utf-8")).decode("ascii").rstrip("=")


def _agg_from_token(token):
    body = str(token or "")
    if body.startswith(AGG_TOKEN):
        body = body[len(AGG_TOKEN):]
    body += "=" * (-len(body) % 4)
    try:
        info = json.loads(base64.urlsafe_b64decode(body.encode("ascii")).decode("utf-8"))
    except Exception:
        return None
    return info if isinstance(info, dict) else None


