# ---- 红果官方高清：纯 Python AES（照「红果短剧.py」的实现） ---
import binascii as _hg_binascii
import struct as _hg_struct


class _PureAES128:
    """纯 Python AES-128，供无 pycryptodome/cryptography 的壳使用。"""

    _S = (
        99,124,119,123,242,107,111,197,48,1,103,43,254,215,171,118,202,130,201,125,250,89,71,240,
        173,212,162,175,156,164,114,192,183,253,147,38,54,63,247,204,52,165,229,241,113,216,49,21,
        4,199,35,195,24,150,5,154,7,18,128,226,235,39,178,117,9,131,44,26,27,110,90,160,82,59,214,
        179,41,227,47,132,83,209,0,237,32,252,177,91,106,203,190,57,74,76,88,207,208,239,170,251,67,
        77,51,133,69,249,2,127,80,60,159,168,81,163,64,143,146,157,56,245,188,182,218,33,16,255,243,
        210,205,12,19,236,95,151,68,23,196,167,126,61,100,93,25,115,96,129,79,220,34,42,144,136,70,
        238,184,20,222,94,11,219,224,50,58,10,73,6,36,92,194,211,172,98,145,149,228,121,231,200,55,
        109,141,213,78,169,108,86,244,234,101,122,174,8,186,120,37,46,28,166,180,198,232,221,116,31,
        75,189,139,138,112,62,181,102,72,3,246,14,97,53,87,185,134,193,29,158,225,248,152,17,105,
        217,142,148,155,30,135,233,206,85,40,223,140,161,137,13,191,230,66,104,65,153,45,15,176,84,
        187,22
    )
    _RCON = (0x00,0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1B,0x36)

    def __init__(self, key: bytes):
        if len(key) != 16:
            raise ValueError("AES-128 only")
        self._rk = self._expand(key)

    def _expand(self, key: bytes):
        s = self._S
        w = list(key)
        for i in range(4, 44):
            t0, t1, t2, t3 = w[-4], w[-3], w[-2], w[-1]
            if i % 4 == 0:
                t0, t1, t2, t3 = s[t1], s[t2], s[t3], s[t0]
                t0 ^= self._RCON[i // 4]
            base = (i - 4) * 4
            w.extend((w[base] ^ t0, w[base + 1] ^ t1, w[base + 2] ^ t2, w[base + 3] ^ t3))
        return w

    @staticmethod
    def _xtime(a: int) -> int:
        return ((a << 1) ^ 0x1B) & 0xFF if (a & 0x80) else ((a << 1) & 0xFF)

    def encrypt_block(self, block: bytes) -> bytes:
        s = list(block)
        rk = self._rk
        for i in range(16):
            s[i] ^= rk[i]
        for rnd in range(1, 10):
            s = [self._S[b] for b in s]
            s = [s[0], s[5], s[10], s[15], s[4], s[9], s[14], s[3],
                 s[8], s[13], s[2], s[7], s[12], s[1], s[6], s[11]]
            for c in range(4):
                i = c * 4
                a, b, c0, d = s[i], s[i + 1], s[i + 2], s[i + 3]
                t = a ^ b ^ c0 ^ d
                u = a
                a ^= t ^ self._xtime(a ^ b)
                b ^= t ^ self._xtime(b ^ c0)
                c0 ^= t ^ self._xtime(c0 ^ d)
                d ^= t ^ self._xtime(d ^ u)
                s[i], s[i + 1], s[i + 2], s[i + 3] = a, b, c0, d
            off = rnd * 16
            for i in range(16):
                s[i] ^= rk[off + i]
        s = [self._S[b] for b in s]
        s = [s[0], s[5], s[10], s[15], s[4], s[9], s[14], s[3],
             s[8], s[13], s[2], s[7], s[12], s[1], s[6], s[11]]
        for i in range(16):
            s[i] ^= rk[160 + i]
        return bytes(s)

    def decrypt_block(self, block: bytes) -> bytes:
        def mul(a, b):
            p = 0
            for _ in range(8):
                if b & 1:
                    p ^= a
                hi = a & 0x80
                a = (a << 1) & 0xFF
                if hi:
                    a ^= 0x1B
                b >>= 1
            return p

        s = list(block)
        rk = self._rk
        for i in range(16):
            s[i] ^= rk[160 + i]
        for rnd in range(9, 0, -1):
            s = [s[0], s[13], s[10], s[7], s[4], s[1], s[14], s[11],
                 s[8], s[5], s[2], s[15], s[12], s[9], s[6], s[3]]
            s = [self._SI[b] for b in s]
            off = rnd * 16
            for i in range(16):
                s[i] ^= rk[off + i]
            for c in range(4):
                i = c * 4
                a, b, c0, d = s[i], s[i + 1], s[i + 2], s[i + 3]
                s[i] = mul(a, 0x0E) ^ mul(b, 0x0B) ^ mul(c0, 0x0D) ^ mul(d, 0x09)
                s[i + 1] = mul(a, 0x09) ^ mul(b, 0x0E) ^ mul(c0, 0x0B) ^ mul(d, 0x0D)
                s[i + 2] = mul(a, 0x0D) ^ mul(b, 0x09) ^ mul(c0, 0x0E) ^ mul(d, 0x0B)
                s[i + 3] = mul(a, 0x0B) ^ mul(b, 0x0D) ^ mul(c0, 0x09) ^ mul(d, 0x0E)
        s = [s[0], s[13], s[10], s[7], s[4], s[1], s[14], s[11],
             s[8], s[5], s[2], s[15], s[12], s[9], s[6], s[3]]
        s = [self._SI[b] for b in s]
        for i in range(16):
            s[i] ^= rk[i]
        return bytes(s)



_PureAES128._SI = tuple({v: i for i, v in enumerate(_PureAES128._S)}[i] for i in range(256))


def _pure_ctr_decrypt(key: bytes, counter: bytes, data: bytes) -> bytes:
    if not data:
        return b""
    if len(counter) < 16:
        counter = counter.ljust(16, b"\0")
    else:
        counter = counter[:16]
    aes = _PureAES128(key)
    ctr = int.from_bytes(counter, "big")
    out = bytearray()
    for offset in range(0, len(data), 16):
        ks = aes.encrypt_block(ctr.to_bytes(16, "big"))
        ctr = (ctr + 1) & ((1 << 128) - 1)
        chunk = data[offset:offset + 16]
        out.extend(c ^ k for c, k in zip(chunk, ks))
    return bytes(out)



def _pure_cbc_decrypt(key: bytes, iv: bytes, data: bytes) -> bytes:
    if not data:
        return b""
    if len(data) % 16:
        data = data[: len(data) - (len(data) % 16)]
    aes = _PureAES128(key)
    prev = (iv[:16] if len(iv) >= 16 else iv).ljust(16, b"\0")
    out = bytearray()
    for i in range(0, len(data), 16):
        block = data[i:i + 16]
        dec = aes.decrypt_block(block)
        out.extend(d ^ p for d, p in zip(dec, prev))
        prev = block
    return bytes(out)



def _aes_ctr_decrypt(key, counter, data):
    return _pure_ctr_decrypt(key, counter, data)


def _aes_cbc_decrypt(key, iv, data):
    return _pure_cbc_decrypt(key, iv, data)


def _toplevel_boxes(buf: bytes) -> list[tuple[int, int, bytes]]:
    boxes: list[tuple[int, int, bytes]] = []
    cursor = 0
    while cursor + 8 <= len(buf):
        size = struct.unpack(">I", buf[cursor : cursor + 4])[0]
        fourcc = bytes(buf[cursor + 4 : cursor + 8])
        if size == 1:
            if cursor + 16 > len(buf):
                break
            size = struct.unpack(">Q", buf[cursor + 8 : cursor + 16])[0]
        if size < 8:
            break
        boxes.append((cursor, size, fourcc))
        cursor += size
    return boxes


try:
    import requests
except Exception:            # 运行环境没有 requests 时，用 urllib 兜底
    class _RequestsShim(object):
        RequestException = Exception
        Response = object          # 仅用于类型注解

        class exceptions(object):
            class RequestException(Exception):
                pass

            class SSLError(Exception):
                pass

            class Timeout(Exception):
                pass

            class ConnectionError(Exception):
                pass

        class _Resp(object):
            def __init__(self, raw):
                self.raw = raw
                self.status_code = raw.getcode()
                self.headers = dict(raw.headers)
                self.content = raw.read()
                self.text = self.content.decode("utf-8", "ignore")

            def json(self):
                return json.loads(self.text)

            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False

            def iter_content(self, chunk_size=8192):
                for i in range(0, len(self.content), max(1, chunk_size)):
                    yield self.content[i:i + chunk_size]

            def raise_for_status(self):
                if self.status_code >= 400:
                    raise _RequestsShim.exceptions.RequestException(
                        "HTTP %s" % self.status_code)
                return None

        class Session(object):
            """极简会话：只提供 get/post，够脚本里那些只用一次的上游请求用。"""

            def __init__(self, *a, **kw):
                self.headers = {}

            def __enter__(self):
                return self

            def __exit__(self, *a):
                return False

            def get(self, url, headers=None, timeout=60, **kw):
                merged = dict(self.headers)
                merged.update(headers or {})
                return _RequestsShim.get(url, headers=merged, timeout=timeout, **kw)

            def post(self, url, data=None, headers=None, timeout=60, **kw):
                merged = dict(self.headers)
                merged.update(headers or {})
                return _RequestsShim.post(url, data=data, headers=merged, timeout=timeout, **kw)

            def close(self):
                return None

        @staticmethod
        def get(url, headers=None, timeout=60, **kw):
            req = urllib.request.Request(url, headers=headers or {})
            with urllib.request.urlopen(req, timeout=timeout) as raw:
                return _RequestsShim._Resp(raw)

        @staticmethod
        def post(url, data=None, headers=None, timeout=60, **kw):
            req = urllib.request.Request(url, data=data, headers=headers or {},
                                         method="POST")
            with urllib.request.urlopen(req, timeout=timeout) as raw:
                return _RequestsShim._Resp(raw)

    requests = _RequestsShim()


# 红果高清分片取流需要的头与重试参数（原先这些名字整个文件里都没有，
# _range_get 一调用就是 NameError，高清线路必然取不到媒体）
MEDIA_HEADERS = {"User-Agent": "okhttp/3.12.1",
                 "Referer": "https://novel.snssdk.com/"}
_RANGE_FETCH_ATTEMPTS = 3
_RANGE_FETCH_BACKOFF_SECONDS = 0.8
_STREAM_HEAD_PROBE = 512 * 1024


def _range_get(url: str, start: int, end: int) -> tuple[bytes, int]:
    headers = dict(MEDIA_HEADERS)
    headers["Range"] = "bytes=%d-%d" % (start, end)
    expected = end - start + 1
    last_error: Exception | None = None
    for attempt in range(_RANGE_FETCH_ATTEMPTS):
        if attempt:
            time.sleep(_RANGE_FETCH_BACKOFF_SECONDS * attempt)
        try:
            response = requests.get(url, headers=headers, timeout=60)
        except requests.RequestException as error:
            last_error = error
            continue
        if response.status_code not in (200, 206):
            last_error = _HgErr(
                "媒体分片请求失败 %s" % response.status_code
            )
            continue
        body = response.content
        # 上游偶发返回短包；短于请求长度时重试，避免播放器收到截断数据。
        if not body or (response.status_code == 206 and len(body) < expected):
            last_error = _HgErr(
                "媒体分片长度不足 %d/%d" % (len(body), expected)
            )
            continue
        total = 0
        content_range = response.headers.get("Content-Range") or ""
        if "/" in content_range:
            tail = content_range.rsplit("/", 1)[1].strip()
            if tail.isdigit():
                total = int(tail)
        if not total:
            length = response.headers.get("Content-Length") or ""
            total = int(length) if length.isdigit() else 0
        return body, total
    raise last_error or _HgErr("媒体分片请求失败")


def _fetch_moov(url: str) -> tuple[int, int, bytes]:
    probe, total = _range_get(url, 0, _STREAM_HEAD_PROBE - 1)
    if not total:
        raise _HgErr("媒体总长度未知")
    moov_start = 0
    moov_size = 0
    for offset, size, fourcc in _toplevel_boxes(probe):
        if fourcc == b"moov":
            moov_start = offset
            moov_size = size
            break
    if not moov_size:
        raise _HgErr("未找到 moov 顶层盒")
    if moov_start + moov_size > total:
        raise _HgErr("moov 越界")
    if moov_start + moov_size <= len(probe):
        return total, moov_start, bytes(probe[moov_start : moov_start + moov_size])
    moov, _ = _range_get(url, moov_start, moov_start + moov_size - 1)
    if len(moov) != moov_size:
        raise _HgErr("moov 分片长度不符")
    return total, moov_start, moov


# 解码器配置盒 -> 真实 sample entry 四字符码。
# CENC 的 sinf/frma 缺失或无效时，这是判断真实编码最可靠的依据：
# 一律兜底 avc1 会把 HEVC(hvc1) 错标成 H.264，播放器按错编码解视轨，
# 表现为「有声音没画面 / 视轨缺失」——这正是低清晰度线路只有超清能看的原因。
_CONFIG_BOX_TO_FORMAT = (
    (b"hvcC", b"hvc1"),
    (b"hev1C", b"hev1"),
    (b"av1C", b"av01"),
    (b"vpcC", b"vp09"),
    (b"avcC", b"avc1"),
    (b"dvvC", b"dvh1"),
    (b"dvhC", b"dvh1"),
)
_AUDIO_CONFIG_BOX_TO_FORMAT = (
    (b"esds", b"mp4a"),
    (b"opusC", b"Opus"),
    (b"ac-3", b"ac-3"),
    (b"ec-3", b"ec-3"),
)


def _format_from_config_box(blob: bytes, kind: bytes) -> bytes:
    """按 sample entry 内的解码器配置盒推断真实编码，找不到返回空串。"""
    probes = _AUDIO_CONFIG_BOX_TO_FORMAT + _CONFIG_BOX_TO_FORMAT if kind == b"enca" \
        else _CONFIG_BOX_TO_FORMAT + _AUDIO_CONFIG_BOX_TO_FORMAT
    hit_pos, hit_fmt = -1, b""
    for fourcc, fmt in probes:
        pos = blob.find(fourcc)
        # 取最靠前的配置盒：sample entry 内通常只含一个，靠前者更可能是本轨的配置
        if pos >= 0 and (hit_pos < 0 or pos < hit_pos):
            hit_pos, hit_fmt = pos, fmt
    return hit_fmt


def _original_format_near(data: bytearray, entry_pos: int, default: bytes, kind: bytes = b"encv") -> bytes:
    """从 sample entry 后的 sinf/frma 读取原始四字符码（avc1/hvc1/mp4a 等）。
    frma 缺失/无效时回退到配置盒探测，而不是一律兜底 avc1。"""
    blob = bytes(data[entry_pos : min(len(data), entry_pos + 800)])
    idx = 0
    while True:
        pos = blob.find(b"frma", idx)
        if pos < 0:
            break
        if pos + 8 <= len(blob):
            fmt = bytes(blob[pos + 4 : pos + 8])
            if fmt not in (b"", b"\x00\x00\x00\x00", b"encv", b"enca") and all(32 <= c < 127 for c in fmt):
                return fmt
        idx = pos + 4
    probed = _format_from_config_box(blob, kind)
    return probed or default


def _restore_cenc_codecs(data: bytearray) -> None:
    """把 encv/enca 还原为真实编码（frma 优先，其次按 avcC/hvcC 等配置盒判定）。
    避免一律改成 avc1/hvc1 导致非对应编码的视轨解不出画面。"""
    pos = 0
    while True:
        pos = data.find(b"encv", pos)
        if pos < 0:
            break
        data[pos : pos + 4] = _original_format_near(data, pos, b"avc1", b"encv")
        pos += 4
    pos = 0
    while True:
        pos = data.find(b"enca", pos)
        if pos < 0:
            break
        data[pos : pos + 4] = _original_format_near(data, pos, b"mp4a", b"enca")
        pos += 4


def _moov_has_video_track(moov: bytes) -> bool:
    """moov 中是否存在 hdlr='vide' 的轨。用于校验某清晰度是否真的带视轨。"""
    view = memoryview(moov)
    search = 0
    found_trak = False
    while True:
        trak, trak_size = _find_box(view, b"trak", search)
        if trak < 0:
            break
        found_trak = True
        search = trak + max(trak_size, 8)
        hdlr = _box_body(view, b"hdlr", trak + 8)
        if hdlr is not None and len(hdlr) >= 12:
            if bytes(hdlr[8:12]) == b"vide":
                return True
    # 解析不出任何 trak 时不轻易判死刑，交由后续解密流程定夺
    return not found_trak


def _rewrite_moov(moov: bytes) -> bytes:
    result = bytearray(moov)
    _restore_cenc_codecs(result)
    _replace_sinf(result)
    return bytes(result)


def _sample_table(moov: bytes, moov_start: int) -> list[tuple[int, int, bytes]]:
    view = memoryview(moov)
    samples: list[tuple[int, int, bytes]] = []
    track_search = 0
    while True:
        track, track_size = _find_box(view, b"trak", track_search)
        if track < 0:
            break
        track_search = track + max(track_size, 8)
        parsed = _parse_track(view, track)
        if parsed is None:
            continue
        sizes, offsets, chunk_counts, aux_sizes, aux_offset, sample_count = parsed
        aux_length = sum(max(size, 8) for size in aux_sizes)
        aux_local = aux_offset - moov_start
        if aux_local < 0 or aux_local + aux_length > len(moov):
            raise _HgErr("CENC 辅助信息不在 moov 内，无法流式解密")
        aux = moov[aux_local : aux_local + aux_length]
        sample_index = 0
        aux_index = 0
        for chunk_index, chunk_offset in enumerate(offsets):
            current = chunk_offset
            for _ in range(chunk_counts[chunk_index]):
                if sample_index >= sample_count or sample_index >= len(sizes):
                    break
                if sample_index >= len(aux_sizes):
                    raise _HgErr("CENC 辅助信息数量不足")
                entry_size = max(aux_sizes[sample_index], 8)
                initial_vector = bytes(
                    aux[aux_index : aux_index + min(entry_size, 8)]
                ).ljust(8, b"\0") + b"\0" * 8
                samples.append((current, sizes[sample_index], initial_vector))
                current += sizes[sample_index]
                aux_index += entry_size
                sample_index += 1
    if not samples:
        raise _HgErr("moov 中没有可解密的 CENC 样本")
    samples.sort()
    return samples



class _HgErr(Exception):
    pass


def _b64(value):
    text = _dump(value).replace(" ", "")
    text += "=" * (-len(text) % 4)
    try:
        return base64.b64decode(text)
    except Exception:
        return b""
def derive_content_key(spade_b64: str) -> bytes:
    raw = _b64(spade_b64)
    if len(raw) < 3:
        raise _HgErr("spade_a 太短")
    v8 = len(raw) - (raw[0] ^ raw[1] ^ raw[2]) + 47
    if v8 <= 0 or 1 + v8 > len(raw):
        v8 = len(raw) - 1
    if v8 < 33:
        raise _HgErr("spade_a 长度异常")
    value = bytearray(raw[1 : 1 + v8])
    va, vb = 85, 246
    for index in range(v8):
        previous = va if index & 1 else vb
        if index & 1:
            va = value[index]
        else:
            vb = value[index]
        value[index] = (-21 - bin(index).count("1") + (previous ^ value[index])) & 0xFF
    try:
        return binascii.unhexlify(bytes(value[1:33]).decode("ascii"))
    except (ValueError, binascii.Error) as exc:
        raise _HgErr("spade_a 密钥材料无效") from exc

def _find_box(data: memoryview, fourcc: bytes, start: int) -> tuple[int, int]:
    for index in range(max(4, start), len(data) - 4):
        if data[index : index + 4] != fourcc:
            continue
        size = struct.unpack(">I", data[index - 4 : index])[0]
        if size == 1 and index + 12 <= len(data):
            size = struct.unpack(">Q", data[index + 4 : index + 12])[0]
        if 8 <= size <= 5_000_000 and index - 4 + size <= len(data):
            return index - 4, size
    return -1, 0

def _box_body(data: memoryview, fourcc: bytes, start: int) -> memoryview | None:
    offset, size = _find_box(data, fourcc, start)
    return data[offset + 8 : offset + size] if offset >= 0 else None

def _parse_track(
    moov: memoryview,
    track_offset: int,
) -> tuple[list[int], list[int], list[int], list[int], int, int] | None:
    if track_offset < 0:
        return None
    stbl_offset, _ = _find_box(moov, b"stbl", track_offset + 8)
    if stbl_offset < 0:
        return None
    stsz = _box_body(moov, b"stsz", stbl_offset)
    stco = _box_body(moov, b"stco", stbl_offset)
    co64 = _box_body(moov, b"co64", stbl_offset)
    stsc = _box_body(moov, b"stsc", stbl_offset)
    saiz = _box_body(moov, b"saiz", stbl_offset)
    saio = _box_body(moov, b"saio", stbl_offset)
    if any(value is None for value in (stsz, stsc, saiz, saio)) or (
        stco is None and co64 is None
    ):
        return None
    assert stsz is not None and stsc is not None
    assert saiz is not None and saio is not None
    default_size = struct.unpack(">I", stsz[4:8])[0]
    sample_count = struct.unpack(">I", stsz[8:12])[0]
    sizes = (
        [default_size] * sample_count
        if default_size
        else [
            struct.unpack(">I", stsz[12 + index * 4 : 16 + index * 4])[0]
            for index in range(sample_count)
        ]
    )
    chunk_table = stco if stco is not None else co64
    assert chunk_table is not None
    chunk_count = struct.unpack(">I", chunk_table[4:8])[0]
    chunk_width = 4 if stco is not None else 8
    offsets = [
        int.from_bytes(
            chunk_table[
                8 + index * chunk_width : 8 + (index + 1) * chunk_width
            ],
            "big",
        )
        for index in range(chunk_count)
    ]
    entry_count = struct.unpack(">I", stsc[4:8])[0]
    entries = [
        (
            struct.unpack(">I", stsc[8 + index * 12 : 12 + index * 12])[0],
            struct.unpack(">I", stsc[12 + index * 12 : 16 + index * 12])[0],
        )
        for index in range(entry_count)
    ]
    chunk_samples = [0] * chunk_count
    for index, (first_chunk, samples_per_chunk) in enumerate(entries):
        end = entries[index + 1][0] - 1 if index + 1 < len(entries) else chunk_count
        for chunk in range(first_chunk - 1, min(end, chunk_count)):
            chunk_samples[chunk] = samples_per_chunk
    saiz_flags = int.from_bytes(saiz[1:4], "big")
    saiz_cursor = 12 if saiz_flags & 1 else 4
    if len(saiz) < saiz_cursor + 5:
        return None
    default_aux_size = saiz[saiz_cursor]
    aux_count = struct.unpack(">I", saiz[saiz_cursor + 1 : saiz_cursor + 5])[0]
    aux_sizes = (
        [default_aux_size] * aux_count
        if default_aux_size
        else [
            int(saiz[saiz_cursor + 5 + index])
            for index in range(aux_count)
            if saiz_cursor + 5 + index < len(saiz)
        ]
    )
    if len(aux_sizes) != aux_count:
        return None
    saio_flags = int.from_bytes(saio[1:4], "big")
    saio_cursor = 12 if saio_flags & 1 else 4
    offset_width = 8 if saio[0] == 1 else 4
    if len(saio) < saio_cursor + 4 + offset_width:
        return None
    entry_count = int.from_bytes(saio[saio_cursor : saio_cursor + 4], "big")
    if entry_count < 1:
        return None
    aux_offset = int.from_bytes(
        saio[saio_cursor + 4 : saio_cursor + 4 + offset_width],
        "big",
    )
    return sizes, offsets, chunk_samples, aux_sizes, aux_offset, sample_count

def _replace_fourcc(data: bytearray, old: bytes, new: bytes) -> None:
    position = 0
    while True:
        position = data.find(old, position)
        if position < 0:
            return
        data[position : position + len(old)] = new
        position += len(new)

def _replace_sinf(data: bytearray) -> None:
    # sinf 盒的首个子盒必为 frma（CENC 规范：frma/schm/schi）。
    # 这里校验后再清零，避免把 avcC/hvcC 配置数据里恰好出现的 "sinf" 字节
    # 当成盒来清零，那样会毁掉解码器配置，表现为视轨丢失/只有声音。
    _sinf_children = (b"frma", b"schm", b"schi")
    position = 0
    while True:
        position = data.find(b"sinf", position)
        if position < 0:
            return
        if position >= 4:
            size = struct.unpack(">I", data[position - 4 : position])[0]
            end = position - 4 + size
            child = bytes(data[position + 8 : position + 12])
            if 8 <= size < 50_000 and end <= len(data) and child in _sinf_children:
                data[position : position + 4] = b"free"
                data[position + 4 : end] = b"\x00" * max(0, end - position - 4)
                position = end
                continue
        position += 4

def decrypt_mp4_cenc(data: bytes, content_key: bytes) -> bytes:
    if len(content_key) != 16:
        raise _HgErr("CENC 密钥长度错误")
    result = bytearray(data)
    if len(result) < 16:
        raise _HgErr("MP4 数据过短")
    moov_start, moov_size = _find_box(memoryview(result), b"moov", 0)
    if moov_start < 0 or moov_size < 8:
        raise _HgErr("MP4 moov 越界")
    moov = memoryview(result)[moov_start : moov_start + moov_size]
    tracks: list[int] = []
    track_search = 0
    while True:
        track, track_size = _find_box(moov, b"trak", track_search)
        if track < 0:
            break
        tracks.append(track)
        track_search = track + max(track_size, 8)
    decrypted_samples = 0
    for track in tracks:
        parsed = _parse_track(moov, track)
        if parsed is None:
            continue
        sizes, offsets, chunk_counts, aux_sizes, aux_offset, sample_count = parsed
        aux_size = sum(max(size, 8) for size in aux_sizes)
        if not sample_count or aux_offset < 0 or aux_offset + aux_size > len(result):
            continue
        aux = result[aux_offset : aux_offset + aux_size]
        sample_index = 0
        aux_index = 0
        for chunk_index, chunk_offset in enumerate(offsets):
            current = chunk_offset
            for _ in range(chunk_counts[chunk_index]):
                if sample_index >= sample_count or sample_index >= len(sizes):
                    break
                size = sizes[sample_index]
                if current + size > len(result):
                    raise _HgErr("MP4 样本越界")
                if sample_index >= len(aux_sizes):
                    raise _HgErr("MP4 辅助信息数量不足")
                entry_size = max(aux_sizes[sample_index], 8)
                iv = bytes(aux[aux_index : aux_index + min(entry_size, 8)]).ljust(
                    8, b"\0"
                ) + b"\0" * 8
                result[current : current + size] = _aes_ctr_decrypt(
                    content_key, iv, bytes(result[current : current + size])
                )
                current += size
                sample_index += 1
                aux_index += entry_size
                decrypted_samples += 1
    if not decrypted_samples:
        raise _HgErr("MP4 没有可解密的 CENC 样本")
    moov_buffer = bytearray(result[moov_start : moov_start + moov_size])
    _restore_cenc_codecs(moov_buffer)
    _replace_sinf(moov_buffer)
    result[moov_start : moov_start + moov_size] = moov_buffer
    return bytes(result)


# ---- 红果官方高清线路：multi_video_model 取片 → CENC 解密 → 本机 206 流服务 ----
import struct as _hg_struct
import binascii as _hg_binascii
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

HG_API = "https://api5-normal-sinfonlineb.fqnovel.com/novel/player/multi_video_model/v1/"
HG_QUERY = ("iid=1&device_id=1&ac=wifi&channel=update_64&aid=8662&app_name=novelread"
            "&version_code=71332&version_name=7.1.3.32&device_platform=android&os=android"
            "&ssmix=a&device_type=25053RT47C&device_brand=Redmi&language=zh&os_api=36"
            "&os_version=16&manifest_version_code=71332&resolution=1280*2772&dpi=520"
            "&update_version_code=71332&host_abi=arm64-v8a&pv_player=71332&player_so_load=1")
HG_MEDIA_UA = "com.dragon.read"
_HG_VM_CACHE = {}
_HG_DATA = {}
_HG_PORT = 0
_HG_LOCK = None
_HG_DEAD_TS = 0


def _hg_model(vid):
    """取字节系高清视频模型。
    实测（2026-11-15）：该接口现在会返回空响应体 —— HTTP 200、Content-Type 是
    application/json、body 长度为 0，各种参数组合都一样空。空体往下走会变成
    「解析成功但没有媒体」，播放器表现为放不了。所以这里把空响应 / 非 JSON
    当成明确失败，并记进全局冷却，别让每个 Range 请求都空跑一次上游。
    """
    global _HG_DEAD_TS
    vid = _dump(vid)
    hit = _HG_VM_CACHE.get(vid)
    if hit and hit[0] > time.time():
        return hit[1]
    if time.time() < _HG_DEAD_TS:
        raise _HgErr("上游高清接口处于冷却中")
    body = json.dumps({
        "biz_param": {"detail_page_version": 0, "device_level": 3,
                      "need_all_video_definition": True, "need_mp4_align": False,
                      "use_os_player": False, "video_platform": 1024},
        "mixed_video_id_map": {"1004": [vid]},
    }, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    req = urllib.request.Request(HG_API + "?" + HG_QUERY, data=body,
                                 headers={"Content-Type": "application/json; charset=utf-8",
                                          "User-Agent": HG_MEDIA_UA,
                                          "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            raw = resp.read()
    except Exception as exc:
        _HG_DEAD_TS = time.time() + 900
        raise _HgErr("上游高清接口请求失败: %s" % type(exc).__name__)
    if not raw or not raw.strip():
        _HG_DEAD_TS = time.time() + 900
        raise _HgErr("上游高清接口返回空响应")
    try:
        payload = json.loads(raw.decode("utf-8", "ignore"))
    except Exception:
        _HG_DEAD_TS = time.time() + 900
        raise _HgErr("上游高清接口返回不是 JSON")
    data = payload.get("data") or {}
    entry = data.get(vid)
    if not isinstance(entry, dict):
        entry = next((v for v in data.values() if isinstance(v, dict)), {})
    vm = entry.get("video_model") or data.get("video_model")
    if isinstance(vm, str):
        vm = json.loads(vm)
    if not isinstance(vm, dict):
        _HG_DEAD_TS = time.time() + 900
        raise _HgErr("video_model 为空")
    _HG_VM_CACHE[vid] = (time.time() + 240, vm)
    if len(_HG_VM_CACHE) > 60:
        _HG_VM_CACHE.clear()
    return vm


def _hg_hd_alive(vid):
    """探一次上游高清接口。False 表示这条高清线路取不到媒体，
    播放时应直接给官网直链，而不是给播放器一个必然空流的 127.0.0.1 地址。"""
    if time.time() < _HG_DEAD_TS:
        return False
    try:
        _hg_model(_dump(vid))
        return True
    except Exception:
        return False


def _hg_pick(vm, want=1080):
    """从 video_list 里挑不高于 want 的最高清晰度（默认 720p）。"""
    vl = vm.get("video_list") or {}
    items = []
    if isinstance(vl, dict):
        items = [x for x in vl.values() if isinstance(x, dict)]
    elif isinstance(vl, list):
        items = [x for x in vl if isinstance(x, dict)]
    best, best_h = None, -1
    for it in items:
        d = _dump(it.get("definition")) or _dump((it.get("video_meta") or {}).get("definition"))
        h = int(re.sub(r"[^0-9]", "", d) or 0)
        if h and h <= want and h > best_h and it.get("main_url"):
            best, best_h = it, h
    if best is None:
        for it in items:
            if it.get("main_url"):
                best = it
                break
    if best is None:
        raise _HgErr("没有可用清晰度")
    return best


def _hg_index(data):
    """只建索引、不当场解全片：返回（密文 buffer, 样本表, moov 位置），
    播放器要哪段就解哪段，首字节约 1 秒，不用等整集解完。"""
    buf = bytearray(data)
    moov_start, moov_size = _find_box(memoryview(buf), b"moov", 0)
    if moov_start < 0:
        raise _HgErr("MP4 无 moov")
    moov = memoryview(buf)[moov_start: moov_start + moov_size]
    entries = []
    track_search = 0
    while True:
        track, ts = _find_box(moov, b"trak", track_search)
        if track < 0:
            break
        track_search = track + max(ts, 8)
        parsed = _parse_track(moov, track)
        if parsed is None:
            continue
        sizes, offsets, chunk_counts, aux_sizes, aux_offset, sample_count = parsed
        if not sample_count or aux_offset < 0:
            continue
        aux_size = sum(max(x, 8) for x in aux_sizes)
        if aux_offset + aux_size > len(buf):
            continue
        aux = bytes(buf[aux_offset: aux_offset + aux_size])
        si = ai = 0
        for ci, coff in enumerate(offsets):
            cur = coff
            for _ in range(chunk_counts[ci]):
                if si >= sample_count or si >= len(sizes):
                    break
                size = sizes[si]
                if si >= len(aux_sizes):
                    break
                esz = max(aux_sizes[si], 8)
                iv = aux[ai: ai + min(esz, 8)].ljust(8, b"\0") + b"\0" * 8
                entries.append((cur, size, iv))
                cur += size
                si += 1
                ai += esz
    if not entries:
        raise _HgErr("没有 CENC 样本")
    mb = bytearray(buf[moov_start: moov_start + moov_size])
    _restore_cenc_codecs(mb)
    _replace_sinf(mb)
    buf[moov_start: moov_start + moov_size] = mb
    entries.sort()
    return buf, entries, moov_start + moov_size


def _hg_hd_source(vid, want=1080):
    """下载并建索引，缓存 3 集；返回 (buffer, 样本表, key, 已解密集合)。"""
    vid = _dump(vid)
    key_c = "%s|%s" % (vid, want)
    hit = _HG_DATA.get(key_c)
    if hit and hit[0] > time.time():
        return hit[1]
    vm = _hg_model(vid)
    it = _hg_pick(vm, want)
    url = _dump(it.get("main_url"))
    if not url.startswith("http"):
        url = _b64(url).decode("utf-8", "ignore")
    if not url.startswith("http"):
        raise _HgErr("片源地址无效")
    data = _hg_fetch_plain(url)
    key = derive_content_key(it.get("spade_a") or (it.get("encrypt_info") or {}).get("spade_a") or "")
    buf, entries, data_start = _hg_index(data)
    holder = {"buf": buf, "entries": entries, "key": key,
              "done": set(), "start": data_start, "ts": time.time()}
    if len(_HG_DATA) > 3:
        _HG_DATA.clear()
    _HG_DATA[key_c] = (time.time() + 1800, holder)
    return holder


def _hg_read(holder, start, end):
    """按字节区间解出明文；只解覆盖到的样本。"""
    buf = holder["buf"]
    key = holder["key"]
    entries = holder["entries"]
    done = holder["done"]
    end = min(end, len(buf) - 1)
    # 二分找到第一个与区间有交集的样本
    lo, hi = 0, len(entries)
    while lo < hi:
        mid = (lo + hi) // 2
        if entries[mid][0] + entries[mid][1] <= start:
            lo = mid + 1
        else:
            hi = mid
    i = lo
    while i < len(entries) and entries[i][0] <= end:
        off, size, iv = entries[i]
        if i not in done:
            if i in done:
                pass
            buf[off: off + size] = _aes_ctr_decrypt(key, iv, bytes(buf[off: off + size]))
            done.add(i)
        i += 1
    return bytes(buf[start: end + 1])


def _hg_fetch_plain(vid_url):
    req = urllib.request.Request(vid_url, headers={"User-Agent": HG_MEDIA_UA,
                                                   "Referer": "https://novel.snssdk.com/"})
    with urllib.request.urlopen(req, timeout=60) as resp:
        return resp.read()


def _hg_hd_bytes(vid):
    """兼容旧调用：只把整集解出来（一般不用，播放走按段解）。"""
    holder = _hg_hd_source(vid)
    return _hg_read(holder, 0, len(holder["buf"]) - 1)


def _hg_warm(vid):
    try:
        _hg_hd_source(vid)
    except Exception:
        pass


def _hg_public_url(vid):
    return "https://hongguoduanju.com/video/public/%s/360p.mp4" % _dump(vid)


class _HgStreamHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def do_GET(self):
        q = urlparse(self.path).query
        vid = (parse_qs(q).get("vid") or [""])[0]
        try:
            want = int((parse_qs(q).get("q") or ["1080"])[0])
        except Exception:
            want = 1080
        if not vid:
            self.send_error(404)
            return
        try:
            holder = _hg_hd_source(vid, want)
            total = len(holder["buf"])
        except Exception:
            # 高清拿不到就退回官网 360P 直链，别让盒子吃 502
            self.send_response(302)
            self.send_header("Location", _hg_public_url(vid))
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        rng = _dump(self.headers.get("Range"))
        start, end = 0, total - 1
        m = re.match(r"bytes=(\d*)-(\d*)", rng)
        if m:
            if m.group(1):
                start = int(m.group(1))
            if m.group(2):
                end = int(m.group(2))
            end = min(end, total - 1)
            if start > end:
                start = 0
        try:
            chunk = _hg_read(holder, start, end)
        except Exception:
            chunk = b""
        if not chunk:
            # 原来这里直接 send_header 而没 send_response，客户端收到的是
            # 一条没有状态行的畸形响应，等于「解析成功但没有媒体」。
            self.send_response(503)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        self.send_response(206 if m else 200)
        self.send_header("Content-Type", "video/mp4")
        self.send_header("Accept-Ranges", "bytes")
        if m:
            self.send_header("Content-Range", "bytes %d-%d/%d" % (start, end, total))
        self.send_header("Content-Length", str(len(chunk)))
        self.end_headers()
        try:
            self.wfile.write(chunk)
        except Exception:
            pass


def _hg_stream_port():
    global _HG_PORT, _HG_LOCK
    if _HG_PORT:
        return _HG_PORT
    import threading
    if _HG_LOCK is None:
        _HG_LOCK = threading.Lock()
    with _HG_LOCK:
        if _HG_PORT:
            return _HG_PORT
        srv = ThreadingHTTPServer(("127.0.0.1", 0), _HgStreamHandler)
        srv.daemon_threads = True
        _HG_PORT = srv.server_address[1]
        threading.Thread(target=srv.serve_forever, daemon=True).start()
    return _HG_PORT

HGD_BASE = "https://hongguoduanju.com"
HGD_UA = ("Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 "
          "(KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1")
_HGD_CACHE = {}


def _hgd_get(path):
    """红果短剧（hongguoduanju）网页抓一次，带 10 分钟缓存。"""
    path = _dump(path)
    hit = _HGD_CACHE.get(path)
    if hit and hit[0] > time.time():
        return hit[1]
    body = ""
    try:
        req = urllib.request.Request(HGD_BASE + path, headers={
            "User-Agent": HGD_UA, "Referer": HGD_BASE + "/", "Accept-Language": "zh-CN,zh;q=0.9"})
        with urllib.request.urlopen(req, timeout=12) as resp:
            raw = resp.read()
        try:
            body = raw.decode("utf-8", "ignore")
        except Exception:
            body = raw.decode("gbk", "ignore")
    except Exception:
        body = ""
    _HGD_CACHE[path] = (time.time() + 600, body)
    if len(_HGD_CACHE) > 40:
        _HGD_CACHE.clear()
    return body


_HG_SEASON = {}
_CN_NUM = {"一": 1, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7,
           "八": 8, "九": 9, "十": 10, "十一": 11, "十二": 12, "十三": 13,
           "十四": 14, "十五": 15, "十六": 16, "十七": 17, "十八": 18,
           "十九": 19, "二十": 20}


def _cn_txt(n):
    """1~99 转中文数字：第七季这种搜索词必须用中文，接口不认阿拉伯数字。"""
    _d = "零一二三四五六七八九"
    n = int(n)
    if n < 10:
        return _d[n]
    if n < 20:
        return "十" + (_d[n % 10] if n % 10 else "")
    return _d[n // 10] + "十" + (_d[n % 10] if n % 10 else "")


def _cn_num(txt):
    txt = _dump(txt)
    if not txt:
        return 0
    if txt.isdigit():
        return int(txt)
    if txt == "十":
        return 10
    if txt.startswith("十"):
        return 10 + _CN_NUM.get(txt[1:], 0)
    if "十" in txt:
        a, b = txt.split("十", 1)
        return _CN_NUM.get(a, 0) * 10 + (_CN_NUM.get(b, 0) if b else 0)
    return _CN_NUM.get(txt, 0)


def _hg_base_name(name):
    """去掉尾部的「第X季 / 第X部 / 第X季共N集」，得到季名前的主名。"""
    name = _dump(name).strip()
    base = re.sub(r"第[0-9一二三四五六七八九十]+[季部]$", "", name).strip()
    return base or name


def _hg_search(base, pages=3):
    """红果站内搜索，返回 (季号, series_id, 标题) 列表。"""
    rows = []
    for pg in range(1, max(1, pages) + 1):
        body = _hgd_get("/api/search/result?aid=8662&query=%s&page=%d"
                        % (urllib.parse.quote(base), pg))
        try:
            obj = json.loads(body)
        except Exception:
            break
        for it in obj.get("searchList") or []:
            vd = it.get("video_data") or {}
            title = _dump(vd.get("series_title"))
            sid = _dump(vd.get("series_id"))
            if not title or not sid:
                continue
            m = re.search(r"第([0-9一二三四五六七八九十]+)[季部]", title)
            no = _cn_num(m.group(1)) if m else (1 if title.split("·")[0].strip() == base else 0)
            if not no:
                continue
            if not (title == base or title.startswith(base)):
                continue
            rows.append((no, sid, title))
        if obj.get("totalPages") and pg >= int(obj.get("totalPages") or 1):
            break
    seen, out = {}, []
    for no, sid, title in rows:
        if no in seen:
            continue
        seen[no] = 1
        out.append((no, sid, title))
    return sorted(out, key=lambda x: x[0])


_HGD_POOL = {}
_HGD_POOL_KEYS = ("短剧", "剧", "重生", "逆袭", "穿越", "系统", "都市", "校园")


def _hgd_pool():
    """状态/时间这两种筛选红果接口根本不给，只能自己攒一个池子(约 110 部)再筛。
    多个关键词并发搜，按 series_id 去重，缓存 5 分钟。"""
    hit = _HGD_POOL.get("v")
    if hit and hit[0] > time.time():
        return hit[1]
    import threading as _th
    box, lock = {}, _th.Lock()

    def pull(q, pg):
        try:
            body = _hgd_get("/api/search/result?aid=8662&query=%s&page=%d"
                            % (urllib.parse.quote(q), pg))
            obj = json.loads(body)
        except Exception:
            return
        got = {}
        for it in obj.get("searchList") or []:
            vd = it.get("video_data") or {}
            sid = _dump(vd.get("series_id"))
            if sid:
                got[sid] = vd
        with lock:
            box.update(got)
    ths = [_th.Thread(target=pull, args=(q, pg), daemon=True)
           for q in _HGD_POOL_KEYS for pg in (1, 2)]
    for t in ths:
        t.start()
    for t in ths:
        t.join(10)
    items = list(box.values())
    _HGD_POOL["v"] = (time.time() + 300, items)
    return items


def _hgd_tag_rows(tag, page=1, days=0, status=""):
    """红果没有网页筛选参数（?tags=/status=/days= 全被忽略），
    只能拿搜索接口按标签搜，再按 category_list 里的标签名过一遍。
    days>0 按上线时间卡；status=1/0 卡连载状态（红果 series_status：1 完结、0 连载）。"""
    tag = _dump(tag).strip()
    if days:
        # 光靠搜索池子「7天内」只有几条，页面看着像没内容：
        # 用新剧榜兜底（它本来就是最近上新的），再和池子里真实按时间筛出来的合并
        cap = {7: 20, 14: 40, 30: 60, 90: 200}.get(int(days), 60)
        out, seen = [], set()

        def add(it, hot="", tags=None, dflt="新剧"):
            sid = _dump(it.get("sid"))
            if not sid or sid in seen:
                return
            seen.add(sid)
            _tg5 = (tags or [""])[0] or dflt
            out.append({"name": it.get("name", ""), "pic": it.get("pic", ""),
                        "eps": int(it.get("eps") or 0), "sid": sid,
                        "hot": hot, "tag": _tg5})
        for pg in range(1, (cap + 19) // 20 + 1):
            for it in _hgd_rows("/rank/new-comic-drama" + ("?page=%d" % pg if pg > 1 else "")):
                add(it, "", it.get("tags"))
        now = time.time()
        for vd in _hgd_pool():
            try:
                _ct = int(vd.get("create_time") or 0)
            except Exception:
                _ct = 0
            if not _ct or (now - _ct) > int(days) * 86400:
                continue
            add({"name": _dump(vd.get("series_title")).strip(),
                 "pic": _dump(vd.get("series_cover")),
                 "eps": int(vd.get("episode_cnt") or 0),
                 "sid": _dump(vd.get("series_id"))},
                _dump((vd.get("hot_score_data") or {}).get("text")),
                [_dump(c.get("name")) for c in (vd.get("category_list") or [])])
        out = out[:cap]
        start = (max(1, int(page or 1)) - 1) * 20
        return out[start:start + 20]
    if status != "":
        pool = _hgd_pool()
        now = time.time()
        keep = []
        for vd in pool:
            try:
                _ct = int(vd.get("create_time") or 0)
            except Exception:
                _ct = 0
            if days and (not _ct or (now - _ct) > days * 86400):
                continue
            if status != "" and _dump(vd.get("series_status")) != _dump(status):
                continue
            keep.append((_ct, vd))
        keep.sort(key=lambda x: -x[0])
        start = (max(1, int(page or 1)) - 1) * 20
        out = []
        for _ct, vd in keep[start:start + 20]:
            _cats = [_dump(c.get("name")) for c in (vd.get("category_list") or [])]
            out.append({"name": _dump(vd.get("series_title")).strip(),
                        "pic": _dump(vd.get("series_cover")),
                        "eps": int(vd.get("episode_cnt") or 0),
                        "sid": _dump(vd.get("series_id")),
                        "hot": _dump((vd.get("hot_score_data") or {}).get("text")),
                        "tag": (_cats[0] if _cats else "")})
        return out
    try:
        body = _hgd_get("/api/search/result?aid=8662&query=%s&page=%d"
                        % (urllib.parse.quote(tag or "漫剧"), max(1, int(page or 1)))
        )
        obj = json.loads(body)
    except Exception:
        return []
    now = time.time()
    out = []
    for it in obj.get("searchList") or []:
        vd = it.get("video_data") or {}
        title = _dump(vd.get("series_title")).strip()
        sid = _dump(vd.get("series_id"))
        if not title or not sid:
            continue
        cats = [_dump(c.get("name")) for c in (vd.get("category_list") or [])]
        if tag and tag not in ("男频", "女频") and tag not in cats:
            continue
        _ct = 0
        try:
            _ct = int(vd.get("create_time") or 0)
        except Exception:
            _ct = 0
        if days and _ct and (now - _ct) > days * 86400:
            continue
        if status != "":
            try:
                if int(vd.get("series_status")) != int(status):
                    continue
            except Exception:
                pass
        out.append({"name": title, "pic": _dump(vd.get("series_cover")),
                    "eps": int(vd.get("episode_cnt") or 0), "sid": sid,
                    "hot": _dump((vd.get("hot_score_data") or {}).get("text")),
                    "tag": (cats[0] if cats else tag)})
    # 同名去重（季号小的留）
    box = {}
    for it in out:
        b = _hg_base_name(it["name"])
        no = 1
        mm = re.search(r"第([0-9一二三四五六七八九十]+)[季部]$", it["name"])
        if mm:
            no = _cn_num(mm.group(1))
        if b not in box or no < box[b][0]:
            box[b] = (no, it)
    return [v for _n, v in sorted(box.values(), key=lambda x: x[0])]


def _hg_search_vods(key, limit=10):
    """豆瓣搜索时顺带查红果漫剧：按主名去重，同一部只出一条（取季号最小的那季）。"""
    key = _dump(key).strip()
    if not key:
        return []
    try:
        body = _hgd_get("/api/search/result?aid=8662&query=%s&page=1"
                        % urllib.parse.quote(key))
        obj = json.loads(body)
    except Exception:
        return []
    box = {}
    for it in obj.get("searchList") or []:
        vd = it.get("video_data") or {}
        title = _dump(vd.get("series_title")).strip()
        sid = _dump(vd.get("series_id"))
        if not title or not sid:
            continue
        base = _hg_base_name(title)
        # 只挂和搜索词真沾边的，别把红果的推荐片也塞进来
        _k2 = key.replace(" ", "")
        if _k2 not in title.replace(" ", "") and _k2 not in base.replace(" ", ""):
            continue
        mm = re.search(r"第([0-9一二三四五六七八九十]+)[季部]$", title)
        no = _cn_num(mm.group(1)) if mm else 1
        cur = box.get(base)
        if cur is None or no < cur[0]:
            box[base] = (no, {
                "vod_id": "hgd:" + sid,
                "vod_name": title,
                "vod_pic": _dump(vd.get("series_cover")),
                "type_name": "红果漫剧",
                "vod_remarks": "红果漫剧 · 全%s集" % _dump(vd.get("episode_cnt")),
                "vod_year": "",
                "vod_area": "",
                "vod_content": "",
                "vod_lang": "国语",
                "vod_actor": "",
                "vod_director": "",
            })
    return [v for _n, v in sorted(box.values(), key=lambda x: x[0])][:max(1, limit)]


def _hg_vids_of(sid):
    body = _hgd_get("/player/" + _dump(sid))
    m = re.search(r'"vid_list":\[(.*?)\]', body or "")
    return re.findall(r'"(\d{10,})"', m.group(1)) if m else []


def _hg_seasons(sid, name):
    """多季合集：返回 [(季号, 季series_id, 集vid列表)]，单季就返回空。
    合集必须包含「当前打开的这一季」：以前只取搜索结果的前 10 季，
    打开「第十四季」时列表里根本没有第十四季，点第 1 集放的是第一季的内容。
    当前这一季还排在最前，点第 1 集才是用户点开的那一季。
    """
    sid = _dump(sid)
    hit = _HG_SEASON.get(sid)
    if hit and hit[0] > time.time():
        return hit[1]
    base = _hg_base_name(name)
    res = []
    # 不能因为片名不带「第X季」就跳过合集：很多漫剧分季但标题只写主名，
    # 只取当前播放页会导致后半季的集数整段缺失。统一查一次全季。

    try:
        seasons = _hg_search(base, 3)
        # 红果搜索按主名会漏季（实测 16 季里缺第 7 季），按缺号用中文季名补查
        if seasons:
            _have = {no for no, _s, _t in seasons}
            _max = max(_have)
            for _n in range(1, _max + 1):
                if _n in _have:
                    continue
                try:
                    _more = _hg_search(base + "第" + _cn_txt(_n) + "季", 1)
                except Exception:
                    _more = []
                for _no, _s2, _t2 in _more:
                    if _no not in _have:
                        seasons.append((_no, _s2, _t2))
                        _have.add(_no)
            seasons.sort(key=lambda x: x[0])
        if len(seasons) < 2:
            res = []
        else:
            # 当前打开的这一季的季号
            cur_no = 0
            for no, s2, _t in seasons:
                if _dump(s2) == sid:
                    cur_no = no
            if not cur_no:
                _mm = re.search(r"第([0-9一二三四五六七八九十]+)[季部]", _dump(name))
                cur_no = _cn_num(_mm.group(1)) if _mm else 0
            # 各季播放页并发拉，否则十几季串行能拖到十几秒
            import threading as _ts
            box = {}

            def _pull(no, _sid2):
                try:
                    vs = _hg_vids_of(_sid2)
                    if vs:
                        box[no] = (_sid2, vs)
                except Exception:
                    pass

            _thr = []
            for no, _sid2, _t in seasons[:40]:
                t = _ts.Thread(target=_pull, args=(no, _sid2), daemon=True)
                t.start()
                _thr.append(t)
            _deadline = time.time() + 4.0
            for t in _thr:
                t.join(max(0.0, _deadline - time.time()))
            # 并发拉时个别季会超时被丢（实测第 1/7 季），串行再补一次
            _smap = {no: _sid2 for no, _sid2, _t in seasons}
            for _no in sorted(_smap):
                if _no in box:
                    continue
                try:
                    _vs = _hg_vids_of(_smap[_no])
                    if _vs:
                        box[_no] = (_smap[_no], _vs)
                except Exception:
                    pass
            res = sorted(((no, vs[0], vs[1]) for no, vs in box.items()), key=lambda x: x[0])
            if len(res) < 2:
                res = []
            else:
                # 选集顺序：第1季第1集 → 第1季第N集 → 第2季第1集 … 严格按季号升序
                # 季数封顶 10（合集太大会把播放列表撑爆）：前 9 季 + 当前这一季，
                # 当前季排在最后但季号正确，不会点错片
                    # 不封顶：漫剧十几季很常见，封 10 季会让第 11 季以后整段消失
                res = sorted(res, key=lambda x: x[0])
    except Exception:
        res = []
    _HG_SEASON[sid] = (time.time() + 900, res)
    if len(_HG_SEASON) > 20:
        _HG_SEASON.clear()
    return res


def _hgd_ep_count(body):
    """页面上「全68集」这种字样，按 href 顺序切块后对得上再取。"""
    m = re.search(r"全(\d+)集", body)
    return int(m.group(1)) if m else 0


def _hgd_rows(path, tag=""):
    """解析红果页面：优先 ld+json 的 ItemList，退回去扫卡片 a 标签。"""
    body = _hgd_get(path)
    if not body:
        return []
    items = []
    for blob in re.findall(r'type="application/ld\+json">(.*?)</script>', body, re.S):
        try:
            obj = json.loads(blob)
        except Exception:
            continue
        stack = [obj]
        while stack:
            cur = stack.pop()
            if isinstance(cur, dict):
                if cur.get("@type") == "ItemList" and cur.get("itemListElement"):
                    items = cur["itemListElement"]
                    break
                stack.extend(cur.values())
            elif isinstance(cur, list):
                stack.extend(cur)
        if items:
            break
    out = []
    if items:
        for it in items:
            if not isinstance(it, dict):
                continue
            name = _dump(it.get("name"))
            pic = _dump(it.get("image"))
            if name:
                _q = re.search(r"series_id=(\d+)", _dump(it.get("url")))
                out.append({"name": name, "pic": pic, "eps": 0,
                            "sid": _q.group(1) if _q else ""})
    if not out:
        # 卡片区：/<a ... href="/detail?series_id=xxx" ...> 里带封面和标题
        for m in re.finditer(r'href="/detail\?series_id=(\d+)"', body):
            # 一张卡的边界切到下一张卡，别把隔壁卡的封面算进来（封面和片名就对不上了）
            _nx = body.find('href="/detail?series_id=', m.end())
            seg = body[m.start(): _nx if _nx > 0 else m.start() + 3000]
            t = re.search(r'class="[^"]*m-title[^"]*">([^<]+)<', seg)
            _alt = _dump(t.group(1)) if t else ""
            img = None
            for _tag in re.findall(r'<img[^>]*>', seg):
                _u = re.search(r'src="(https://[^"]+)"', _tag)
                if not _u or "empty_play" in _u.group(1) or "bytegecko" in _u.group(1):
                    continue
                if _alt and ('alt="%s"' % _alt) in _tag:
                    img = _u
                    break
                if img is None:
                    img = _u
            ep = re.search(r">全(\d+)集<", seg)
            if not t:
                continue
            name = _dump(t.group(1))
            if not name:
                continue
            tags = re.findall(r'm-tag-text-[^"]*">([^<]+)<', seg)[:3]
            out.append({"name": name,
                        "pic": _dump(img.group(1)) if img else "",
                        "eps": int(ep.group(1)) if ep else 0,
                        "sid": m.group(1),
                        "tags": [_dump(t) for t in tags]})
    seen, uniq = set(), []
    for it in out:
        key = it["name"].replace(" ", "")
        if key in seen:
            continue
        seen.add(key)
        if it["eps"]:
            it["eps"] = it["eps"]
        uniq.append(it)
    return uniq


_HGD_HOT = {}


def _hgd_meta(sid, title):
    """按片名搜一次，把热度/首个标签/集数都拿回来（分类页、榜单页都没有这些）。"""
    sid = _dump(sid)
    if not sid or not _dump(title):
        return {}
    hit = _HGD_HOT.get(sid)
    if hit and hit[0] > time.time():
        return hit[1]
    meta = {}
    try:
        body = _hgd_get("/api/search/result?aid=8662&query=%s&page=1"
                        % urllib.parse.quote(_dump(title)[:30]))
        obj = json.loads(body)
        for it in obj.get("searchList") or []:
            vd = it.get("video_data") or {}
            if _dump(vd.get("series_id")) == sid:
                cats = [_dump(c.get("name")) for c in (vd.get("category_list") or [])]
                meta = {"hot": _dump((vd.get("hot_score_data") or {}).get("text")),
                        "tag": (cats[0] if cats else ""),
                        "eps": int(vd.get("episode_cnt") or 0)}
                break
    except Exception:
        meta = {}
    _HGD_HOT[sid] = (time.time() + 600, meta)
    while len(_HGD_HOT) > 300:
        _HGD_HOT.pop(next(iter(_HGD_HOT)), None)
    return meta


def _hgd_hot(sid, title):
    return _dump(_hgd_meta(sid, title).get("hot"))


def hgd_category(tid, page, extend=None):
    """tid: hgd|comic-drama（分类，可带子标签 hgd|comic-drama|fantasy）/ hgd_rank|hot-comic-drama（榜单）"""
    parts = _dump(tid).split("|")
    extend = extend if isinstance(extend, dict) else {}
    page = max(1, int(page or 1))
    _rk = _dump(extend.get("rank"))
    _cate = _dump(extend.get("cate"))
    if parts[0] == "hgd_rank" or _rk:
        _which = _rk or (parts[1] if len(parts) > 1 else "hot-comic-drama")
        path = "/rank/%s" % _which
        label = "新剧榜" if "new" in _which else "热播榜"
    else:
        path = "/category/%s" % (parts[1] if len(parts) > 1 else "comic-drama")
        _tag = _cate or (parts[2] if len(parts) > 2 else "")
        if _tag:
            path += "/" + _tag
        label = "漫剧"
    # 背景／设定／受众／状态／时间：红果网页不接受这些参数，改走搜索接口按标签筛
    _bg = _dump(extend.get("bg"))
    _set = _dump(extend.get("set"))
    _aud = _dump(extend.get("aud"))
    _st = _dump(extend.get("st"))
    _days = _dump(extend.get("days"))
    _tg = ""
    if parts[0] != "hgd_rank" and not _rk and not _cate:
        _tg = _bg or _set or _aud
    if not _tg and (_st or _days):
        _tg = "漫剧"      # 只挑了状态/时间：拿漫剧做底再筛
    if _tg:
        _status = {"已完结": "0", "连载中": "1"}.get(_st, "")
        rows = []
        try:
            _d = int(_days or 0)
        except Exception:
            _d = 0
        _rows_t = _hgd_tag_rows(_tg, page, _d, _status)
        for it in _rows_t:
            _tg3 = it.get("tag") or ""
            if _tg3 and it.get("hot"):
                rem = _tg3 + "·" + it["hot"]
            elif _tg3:
                rem = _tg3
            elif it["eps"]:
                rem = "全%d集" % it["eps"]
            else:
                rem = _tg
            rows.append({"vod_id": "hgd:" + it["sid"], "vod_name": it["name"],
                         "vod_pic": it["pic"], "vod_remarks": rem, "vod_content": ""})
        return rows
    if page > 1:
        path += ("&" if "?" in path else "?") + "page=%d" % page
    rows = []
    _is_rank = bool(parts[0] == "hgd_rank" or _rk)
    for idx, it in enumerate(_hgd_rows(path), 1):
        if _is_rank:
            rem = "%s %d" % (label, idx)
        else:
            _tg2 = (it.get("tags") or [""])[0] or label
            rem = _tg2
        if it["eps"]:
            rem += " · 全%d集" % it["eps"]
        rows.append({
            "vod_id": ("hgd:" + it["sid"]) if it.get("sid") else ("a5:" + _sz_enc({"t": it["name"]})),
            "vod_name": it["name"],
            "vod_pic": it["pic"],
            "vod_remarks": rem,
            "vod_content": "",
            "_tg0": (it.get("tags") or [""])[0] if not _is_rank else "",
            "_eps": it["eps"],
        })
    if not _is_rank:
        # 备注只用页面自带的标签和集数，不再逐条查热度：几十个并发请求在盒子上会被限速，
        # 一整页就卡住、点了筛选像没反应
        for r in rows:
            _tg4 = r.pop("_tg0", "") or "红果漫剧"
            _ep4 = r.pop("_eps", 0)
            r["vod_remarks"] = _tg4 + (" · 全%d集" % _ep4 if _ep4 else "")
    return rows


def a5_category(tid, page):
    """tid 形如 a5|iq|1 / a5|tx|movie / a5|yk|电影 / a5|mg|2 / a5|bl|1"""
    parts = _dump(tid).split("|")
    if len(parts) < 3:
        return []
    plat, cid = parts[1], parts[2]
    key = "%s|%s|%s" % (plat, cid, page)
    if plat == "tx":
        return _a5_cached(key, lambda: a5_tx_cate(cid, page))
    if plat == "iq":
        return _a5_cached(key, lambda: a5_iq_cate(cid, page))
    if plat == "yk":
        return _a5_cached(key, lambda: a5_yk_cate(cid, page))
    if plat == "mg":
        return _a5_cached(key, lambda: a5_mg_cate(cid, page))
    if plat == "bl":
        return _a5_cached(key, lambda: a5_bl_cate(cid, page))
    return []


