def home_content():
    classes = [{"type_id": "newshow", "type_name": "新开播"},
               {"type_id": "recommend", "type_name": "推荐"},
               {"type_id": "tx_update", "type_name": "腾讯更新"},
               {"type_id": "tx_anime_home", "type_name": "动漫首页"}]
    classes += [{"type_id": tid, "type_name": name}
                for tid, name, *_ in BROWSE]
    # 五大平台各自的分类（点进按片名对豆瓣条目，线路走豆瓣那套）
    classes += [{"type_id": tid, "type_name": name} for tid, name in A5_CLASSES]
    classes += [{"type_id": "movie_rank", "type_name": "电影榜单"},
                {"type_id": "tv_rank", "type_name": "电视剧榜单"}]
    return {"class": classes, "filters": FILTERS}


def _tag_pick(extend, row):
    """筛选条件里挑一个能直接当豆瓣标签用的（标签接口只吃单一标签）。"""
    for key in ("form", "genre", "plat", "year", "area"):
        value = _dump(extend.get(key))
        if value and value not in ("全部", "all", "All"):
            return value
    return row[2] or "热门"


def _sort_of(extend):
    value = _dump(extend.get("sort")).upper()
    return {"": "recommend", "S": "recommend", "T": "time", "U": "time",
            "R": "rank", "RECOMMEND": "recommend", "TIME": "time",
            "RANK": "rank"}.get(value, "recommend")


_HUA = ("中国大陆", "中国香港", "中国台湾", "中国澳门")


def _subject_match(subject, extend):
    year = _dump(extend.get("year"))
    if year and year not in ("全部", "all"):
        if _dump(subject.get("release_year")) != year:
            return False
    area = _dump(extend.get("area"))
    if area and area not in ("全部", "all"):
        region = _dump(subject.get("region"))
        if area == "华语":
            if not any(x in region for x in _HUA):
                return False
        elif area not in region:
            return False
    genre = _dump(extend.get("genre"))
    if genre and genre not in ("全部", "all"):
        types = [_dump(x) for x in (subject.get("types") or [])]
        if not any(genre in x for x in types):
            return False
    form = _dump(extend.get("form"))
    if form and form not in ("全部", "all"):
        types = [_dump(x) for x in (subject.get("types") or [])]
        if not any(form in x for x in types):
            return False
    return True


def _abstracts(ids):
    """并发取条目摘要（年份／地区／类型），只在真的用到本地筛选时才拉。"""
    result = {}
    todo = [sid for sid in ids if sid]
    if not todo:
        return result
    def _one(sid):
        subject = _db_abstract(sid)
        if subject:
            result[sid] = subject
    try:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=4) as pool:
            list(pool.map(_one, todo))
    except Exception:
        for sid in todo:
            _one(sid)
    return result


def _has_local_filter(extend):
    return any(_dump(extend.get(k)) not in ("", "全部", "all")
               for k in ("year", "area", "genre", "form"))


def _collection_page(items, data, page, limit=20):
    rows = _fill_years(_rows(items), limit)
    try:
        total = int(data.get("total") or 0)
    except (TypeError, ValueError):
        total = 0
    pagecount = (total + limit - 1) // limit if total else page + (1 if items else 0)
    return {"list": rows, "page": page, "pagecount": pagecount, "limit": limit,
            "total": total or (page - 1) * limit + len(rows)}


