_HIST_ROWS = []


def _remember(rows):
    """记住搜到过的片名，下次单字/拼音联想时一起带出来"""
    try:
        _ids = set(_dump(x.get("vod_id")) for x in _HIST_ROWS)
        for x in rows[:12]:
            _id = _dump(x.get("vod_id"))
            if _id and _id not in _ids:
                _HIST_ROWS.append(x)
                _ids.add(_id)
        del _HIST_ROWS[80:]
    except Exception:
        pass


def _official_entries(key, timeout=4):
    try:
        from threading import Thread
        box = {}
        def _run():
            try:
                box["x"] = _pf_search_entries(key, timeout=timeout)
            except Exception:
                box["x"] = []
        t = Thread(target=_run)
        t.daemon = True
        t.start()
        t.join(timeout + 0.5)
        return box.get("x") or []
    except Exception:
        return []


def _pf_b64(name):
    import base64 as _b64
    return _b64.urlsafe_b64encode(_dump(name).encode("utf-8")).decode("ascii").rstrip("=")


def _pf_unb64(enc):
    import base64 as _b64
    pad = "=" * (-len(enc) % 4)
    try:
        return _b64.urlsafe_b64decode(enc + pad).decode("utf-8")
    except Exception:
        return ""


def _pf_name(enc):
    """旧版把名字塞成了 {"t":"片名","n":""} 的 JSON 串，解出来还是乱的；
    这里兜一层：是 JSON 就取 t/name，正常情况下原样返回"""
    txt = _pf_unb64(_dump(enc))
    txt = _dump(txt).strip()
    if txt.startswith("{") and "}" in txt:
        try:
            obj = json.loads(txt)
            if isinstance(obj, dict):
                return _dump(obj.get("t") or obj.get("name") or obj.get("title") or "")
        except Exception:
            pass
    return txt


IQ_SEARCH = "https://mesh.if.iqiyi.com/portal/lw/search/homePageV3?key="
IQ_CACHE = {}


def _iq_album(name):
    """爱奇艺官方搜索：返回 (片名, 总集数)，只认爱奇艺自家片库（siteId=iqiyi 且非短视频）"""
    name = _dump(name).strip()
    if not name:
        return "", 0
    hit = IQ_CACHE.get(name)
    if hit and hit[0] > time.time():
        return hit[1], hit[2]
    title, total = "", 0
    try:
        j = json.loads(_http_text(IQ_SEARCH + quote(name, safe=""),
                                  {"User-Agent": UA, "Referer": "https://www.iqiyi.com/"}, 12) or "{}")
        for t in ((j.get("data") or {}).get("templates") or []):
            a = t.get("albumInfo") or {}
            if _dump(a.get("siteId")) != "iqiyi":
                continue
            _n = _dump(a.get("title")).strip()
            _total = int(a.get("totalNumber") or 0)
            if not _total:
                continue                      # 短视频没有集数，不要
            if _n == name:
                title, total = _n, _total
                break
            if _n.startswith(name) and not title:
                title, total = name, _total
    except Exception:
        pass
    IQ_CACHE[name] = (time.time() + 180, title, total)
    while len(IQ_CACHE) > 60:
        IQ_CACHE.pop(next(iter(IQ_CACHE)), None)
    return title, total


def _iq_lines(name):
    """爱奇艺官方有这部片时，借已有的云盘/高清线出流（集数必须对得上，否则不挂）"""
    title, total = _iq_album(name)
    if not title:
        return []
    picked = None
    for src in ("yt", "agg", "yk"):
        try:
            pairs = _pf_lines_raw(src, name)
        except Exception:
            pairs = []
        for f, u in pairs:
            n = len([x for x in _dump(u).split("#") if x])
            if total and n == total:
                picked = (f, u, n)
                break
            if picked is None and total and abs(n - total) <= 2:
                picked = (f, u, n)
        if picked and picked[2] == total:
            break
    if not picked:
        return []
    f, u, n = picked
    return [("爱奇艺·" + _dump(f), u)]


def _pf_lines_raw(pf, name):
    """按平台原始搜索取线路（内部用，不做二次验证）"""
    name = _dump(name)
    try:
        if pf == "tx":
            fs, us = tx_collect(name)
            if not us:
                merged = _tx_season_merge(name)
                if merged:
                    fs, us = ["腾讯视频"], [merged]
        elif pf == "mg":
            fs, us = mg_collect(name)
        elif pf == "yt":
            fs, us = yt_cloud_collect(name)
        elif pf == "agg":
            fs, us = agg_collect(name)
        elif pf == "yk":
            lb, u = yk_borrow(name)
            if lb and u and "youku.com" in _dump(u):
                fs, us = [lb], [u]
            else:
                fs, us = [], []
        elif pf == "iq":
            return _iq_lines(name)
        else:
            fs, us = [], []
    except Exception:
        fs, us = [], []
    return list(zip(fs, us))


def _pf_lines(pf, name):
    """直接拿各平台自己的搜索/选集接口，给「平台引擎」条目拼线路"""
    name = _dump(name)
    if pf == "iq":
        # 爱奇艺官方片库命中时，借云盘/高清线出流（集数必须对得上）
        return _iq_lines(name)
    try:
        if pf == "tx":
            fs, us = tx_collect(name)
            if not us:
                # 同名只搜到短剧/短视频时，退回按季拼动漫正片
                merged = _tx_season_merge(name)
                if merged:
                    fs, us = ["腾讯视频"], [merged]
        elif pf == "mg":
            fs, us = mg_collect(name)
        elif pf == "yt":
            fs, us = yt_cloud_collect(name)
        elif pf == "agg":
            fs, us = agg_collect(name)
        elif pf == "yk":
            lb, u = yk_borrow(name)
            # 优酷搜索偶尔把腾讯/芒果的页面当结果返回，这种不是优酷自己的片，别挂
            if lb and u and "youku.com" in _dump(u):
                fs, us = [lb], [u]
            else:
                fs, us = [], []
        else:
            fs, us = [], []
    except Exception:
        fs, us = [], []
    pairs = []
    for f, u in zip(fs, us):
        if not f or not u:
            continue
        eps = [x for x in _dump(u).split("#") if x]
        if not eps:
            continue
        # 至少得有一集拿得到可播地址，否则这条平台线是空的（优酷常见的空壳）
        if not any("http" in e.split("$", 1)[-1] or ":" in e.split("$", 1)[-1] for e in eps):
            continue
        pairs.append((f, u))
    return pairs


_PF_NOISE = re.compile(r"(动漫|动画|电视剧|剧版|电影版|大电影|电影|综艺|纪录片|全集|完整版|在线观看|高清|免费|国语版|日语版|中文版|版)")


def _pf_clean(key):
    """「诛仙动漫」「诛仙 动画」这种带类型词的搜索，平台接口按片名是搜不到的，
    把类型词剥掉再查（诛仙 动画 -> 诛仙）"""
    k = _PF_NOISE.sub(" ", _dump(key))
    k = re.sub(r"\s+", " ", k).strip()
    return k or _dump(key).strip()


def _pf_poster(rows, key):
    """平台条目的封面：优先用「正剧/番剧」条目，别拿同名电影（诛仙Ⅰ）的海报凑"""
    key = _dump(key).replace(" ", "")
    best = ""
    for _r in rows or []:
        _n = _dump(_r.get("vod_name")).replace(" ", "")
        _p = _dump(_r.get("vod_pic"))
        if not _p or "tv_default" in _p or "movie-static/pics" in _p:
            continue          # 豆瓣占位图，不如拿同名片另一条的真海报
        _kind = _dump(_r.get("vod_id")).partition(":")[0]
        _exact = (_n == key)
        _tail_num = bool(re.match(r"^[0-9ⅠⅡⅢ]+", _n[len(key):] or "")) if _n.startswith(key) else False
        if _exact and _kind in ("tv", "anime"):
            return _p
        if _n.startswith(key) and not _tail_num and not best:
            best = _p
        if _exact and not best:
            best = _p
    return best


def _group_pf_entries(items):
    """把同一部片的腾讯/爱奇艺/优酷/芒果搜索结果合成一条，线路进详情统一集合。"""
    out, by = [], {}
    for x in items or []:
        name = _dump(x.get("vod_name"))
        k = _pf_clean(name) or name
        rem = _dump(x.get("vod_remarks"))
        label, _, cnt = rem.partition(" · ")
        if k not in by:
            y = dict(x)
            y["type_name"] = "官方合集"
            y["vod_content"] = "官方平台合集，详情里合并所有官方与网盘线路"
            by[k] = {"vod": y, "labels": [label + (" " + cnt if cnt else "")]}
            out.append(by[k])
        else:
            lab = label + (" " + cnt if cnt else "")
            if lab not in by[k]["labels"]:
                by[k]["labels"].append(lab)
    for g in out:
        g["vod"]["vod_remarks"] = "官方合集 · " + " / ".join(g["labels"][:4])
    return [g["vod"] for g in out]


def _pf_search_entries(key, pic="", timeout=9):
    """豆瓣搜索时顺带把五大平台的同名结果也列出来，点开就是那个平台的正片"""
    key = _dump(key)
    if not key:
        return []
    import threading as _th
    out, lock = [], _th.Lock()

    # 模糊词：原名、去修饰词、取空格/标点前的主标题，三种都试
    import re as _r
    _core = _r.split(r"[ \t·:：,，、/|\-—_]+", _pf_clean(key))[0]
    _core = _r.sub(r"(第[一二三四五六七八九十0-9]+季|年番[0-9]*|最终季|新番|剧场版)$",
                   "", _core).strip()
    variants = []
    for q in (key, _pf_clean(key), _core):
        q = _dump(q).strip()
        if q and q not in variants:
            variants.append(q)
    variants = variants[:3]

    def run(pf):
        pairs, matched = [], key
        for q in variants:
            try:
                pairs = _pf_lines(pf, q)
            except Exception:
                pairs = []
            if pairs:
                matched = q
                break
        if not pairs:
            return
        n = len([x for x in _dump(pairs[0][1]).split("#") if x])
        vod = {
            "vod_id": "pf:%s:%s" % (pf, _pf_b64(matched)),
            "vod_name": matched,
            "vod_pic": pic,
            "vod_remarks": ("%s · %d集" % (PF_LABELS.get(pf, pf), n)) if n > 1
                            else ("%s · 正片" % PF_LABELS.get(pf, pf)),
            "vod_year": "",
            "vod_content": "来自%s的搜索结果，线路都在这个平台自己身上" % PF_LABELS.get(pf, pf),
            "type_name": PF_LABELS.get(pf, pf),
        }
        with lock:
            out.append(vod)

    # 按官方平台自己的标题搜索结果收录：腾讯、爱奇艺、优酷、芒果。
    # 集数残缺的平台也保留，用户点进去看到的就是该平台官方集数。
    ths = []
    for pf in ("tx", "iq", "yk", "mg"):
        t = _th.Thread(target=run, args=(pf,))
        t.daemon = True
        ths.append(t)
        t.start()
    for t in ths:
        t.join(timeout)
    def _eps(x):
        m = re.search(r"(\d+)集", _dump(x.get("vod_remarks")))
        return int(m.group(1)) if m else 0
    out.sort(key=lambda x: (0 if _dump(x.get("vod_remarks")).endswith("正片") else 1,
                            -_eps(x)))
    return out


SEARCH_CACHE = {}


_WOGG_SESS = {}


def _wogg_pan_eps(pans, title):
    """把玩偶详情里的「一个分享链接」展开成逐集令牌，否则重复同一个链接必然播放失败。"""
    out = {}
    try:
        _uc = UCDrive("")
        _qk = QuarkDrive(_local_quark_cookie())
    except Exception:
        _uc = _qk = None
    for _p, _links in (pans or {}).items():
        _p = _nd_pan(_p)
        if _p in ("UC", "夸克") and (_uc if _p == "UC" else _qk) is not None:
            _drv = _uc if _p == "UC" else _qk
            # 玩偶两种形态：①一个分享文件夹里 40 个文件；②40 集各一个分享链接。
            # 只展开第一个链接会把 ② 变成“1 个令牌重复 40 集”，点哪集都回第 1 集。
            # 先展开首个：若它本身就是多文件文件夹，直接用；只有 1 个文件才并行展开其余链接。
            _items_map = {}
            try:
                _first = _drv.list_videos(_links[0], limit=500) if _links else []
            except Exception:
                _first = []
            if len(_first) > 1 or len(_links) <= 1:
                for it in _first:
                    _items_map[str(it.get("fid"))] = it
            else:
                from concurrent.futures import ThreadPoolExecutor as _TPE
                def _one(_lk):
                    try:
                        return _drv.list_videos(_lk, limit=50)
                    except Exception:
                        return []
                with _TPE(max_workers=8) as _ex:
                    _all = _ex.map(_one, _links)
                    for _lst in _all:
                        for it in _lst:
                            _items_map.setdefault(str(it.get("fid")), it)
            _eps = []
            for i, it in enumerate(_items_map.values()):
                _pre = "Q~" if _p == "夸克" else ""
                _eps.append("%s$%s%s__%s+%s+%s" % (
                    "第%02d集" % (i + 1), _pre,
                    it["file_name"], it["fid"], it["pwd_id"], it["share_fid_token"]))
            if _eps:
                out[_p] = "#".join(_eps)
        elif _p == "百度" and BD_COOKIE:
            try:
                _bd = BaiduDrive(BD_COOKIE)
                for _link in _links[:1]:
                    _items = _bd.walk(_link, limit=500)
                    if _items:
                        _eps = []
                        for i, it in enumerate(_items):
                            _tok = json.dumps({"u": _link, "p": it["path"], "f": it.get("fs_id", "")},
                                              ensure_ascii=False)
                            _eps.append("%s$BD~%s" % (
                                "第%02d集" % (i + 1),
                                quote(_tok, safe="")))
                        out[_p] = "#".join(_eps)
            except Exception:
                pass
    return out


def _wogg_api_pans(site, detail_url):
    """HTML 详情解析不到链接时，改走苹果CMS 数据接口；接口常比详情页少一层盾。"""
    try:
        _m = re.search(r"/(\d+)\.html", _dump(detail_url))
        if not _m:
            return {}
        _base = site.get("url") or ""
        _s = _WOGG_SESS.get(_base) or site.get("session") or make_session()
        _u = "%s/api.php/provide/vod/?ac=detail&ids=%s" % (_base, _m.group(1))
        _r = _s.get(_u, timeout=10)
        if _r.status_code != 200:
            return {}
        _d = json.loads(_r.text or "{}")
        _v = ((_d.get("list") or [])[:1] or [{}])[0]
        _txt = " ".join([_dump(_v.get("vod_play_url")), _dump(_v.get("vod_content"))])
        return _extract_pans(_txt)
    except Exception:
        return {}


def _wogg_plain_pans(site, detail_url):
    """照参考源直接 GET 详情页解析网盘链接，绕过 _wogg_get 的挑战识别/curl 兜底。"""
    try:
        _u = _to_detail_url(detail_url)
        _m = re.match(r"(https?://[^/]+)", _u)
        _base = _m.group(1) if _m else site.get("url", "")
        _s = _WOGG_SESS.get(_base)
        if _s is None:
            _s = make_session()
            try:
                _s.get(_base + "/", timeout=8)
            except Exception:
                pass
        _r = _s.get(_u, timeout=10)
        if _r.status_code != 200:
            return {}, "", _r.status_code
        _html = _r.text or ""
        _found = {}
        if BeautifulSoup is not None:
            _soup = BeautifulSoup(_html, "html.parser")
            for _row in _soup.select(".module-row-text"):
                _cands = []
                _le = _row.select_one("[data-clipboard-text]")
                if _le:
                    _cands.append(_le.get("data-clipboard-text", ""))
                _cands.append(_row.get_text(" ", strip=True))
                for _txt in _cands:
                    for _name, _rx in PAN_RES:
                        for _m in _rx.finditer(_txt or ""):
                            _url = _m.group(0)
                            _found.setdefault(_name, [])
                            if _url not in _found[_name]:
                                _found[_name].append(_url)
        if not _found:
            _found = _extract_pans(_html)
        if not _found:
            _found = _wogg_api_pans(site, _u)
        return _found, _html, 200
    except Exception:
        return {}, "", 0


def _wogg_plain_search(key):
    """照参考源并行跑全部玩偶镜像：每个镜像先拿首页 Cookie 再搜，哪个先出结果用哪个。
    参考源能搜到说明至少有一个镜像在设备上可过盾；之前只跑前 3 个，可能全是死的。"""
    try:
        _cfg = next((x for x in SITES if _dump(x.get("id")) == "玩偶"), None)
        if not _cfg:
            return []
        _bases = [b for b in (_cfg.get("site") or []) if b]
        if not _bases:
            return []

        def _one(_base):
            try:
                _s = make_session()
                try:
                    _s.get(_base + "/", timeout=3)
                except Exception:
                    pass
                _u = "%s/vodsearch/-------------.html?wd=%s&submit=" % (_base, quote(key))
                _r = _s.get(_u, timeout=6)
                if _r.status_code != 200:
                    return []
                _vv = maccms_parse_list(dict(_cfg, url=_base), _r.text or "") or []
                if _vv:
                    _WOGG_SESS[_base] = _s
                return _vv
            except Exception:
                return []

        import concurrent.futures as _cw
        _ex = _cw.ThreadPoolExecutor(max_workers=min(9, len(_bases)))
        _futs = [_ex.submit(_one, b) for b in _bases]
        try:
            for _f in _cw.as_completed(_futs, timeout=8):
                try:
                    _v = _f.result(timeout=0.1)
                except Exception:
                    continue
                if _v:
                    _ex.shutdown(wait=False)
                    return _v
        finally:
            _ex.shutdown(wait=False)
    except Exception:
        pass
    return []


def _wogg_search_vods(key, limit=2):
    """玩偶站直搜，给五大平台搜索补出可点开的独立条目。
    这里只建一个轻量 site（不经过聚合客户端）：避免移动端 LocalStreamProxy 启动失败时
    连搜索都被 _agg_client()=None 一起拖死。"""
    try:
        _cfg = next((x for x in SITES if _dump(x.get("id")) == "玩偶"), None)
        if not _cfg:
            return []
        site = dict(_cfg)
        site["session"] = make_session()
        site["url"] = (site.get("site") or [""])[0]
        # 先访问首页拿 Cloudflare 通行 cookie，再搜；否则直接搜会被识别成机器人。
        try:
            site["session"].get(site["url"] + "/", timeout=8)
        except Exception:
            pass
        # maccms_search 会按 site 列表逐个域名顺序试，哪个先出结果用哪个，
        # 不再把 www.wogg.net 一个死镜像写死。
        vods = _wogg_plain_search(key) or maccms_search(site, key, "1") or []
        out = []
        for v in vods:
            _nm = _dump(v.get("vod_name"))
            if not _nm:
                continue
            out.append({"vod_id": "玩偶@" + _dump(v.get("vod_id")),
                        "vod_name": _nm,
                        "vod_pic": _dump(v.get("vod_pic")),
                        "vod_remarks": ("玩偶 · " + _dump(v.get("vod_remarks"))).strip(" ·")})
            if len(out) >= limit:
                break
        return out
    except Exception:
        return []




def _sw(key, default=1):
    """远程开关：switch.json 里 0 就关、1 就开；拉不到用 default"""
    try:
        if _SW_T[0] == 0 or time.time() - _SW_T[0] > 1800:
            _SW_T[0] = time.time()
            req = urllib.request.Request(_SW_URL + "?t=%d" % int(time.time()), headers={"User-Agent": "okhttp/3.12.0"})
            with urllib.request.urlopen(req, timeout=5) as r:
                obj = json.loads(r.read().decode("utf-8", "ignore"))
            if isinstance(obj, dict):
                for k, v in obj.items():
                    try:
                        _SW[k] = int(v)
                    except Exception:
                        pass
    except Exception:
        pass
    if int(_SW.get("all", 1)) == 0:
        return False          # 总开关：一关全关
    return int(_SW.get(key, default)) != 0

def _glm_chat(prompt, timeout=20):
    """智谱免费模型：模型忙时(429)自动退避重试，并换 glm-4-flash 兜底"""
    key = (_GLM_KEY or "").strip()
    if not key or not _sw("ai", 1):
        return ""
    body_base = {"messages": [{"role": "user", "content": prompt}], "temperature": 0.1}
    for model in ("glm-4.7-flash", "glm-4-flash"):
        for attempt in range(3):
            try:
                body = dict(body_base)
                body["model"] = model
                req = urllib.request.Request(
                    "https://open.bigmodel.cn/api/paas/v4/chat/completions",
                    data=json.dumps(body).encode(),
                    headers={"Authorization": "Bearer " + key,
                             "Content-Type": "application/json"})
                with urllib.request.urlopen(req, timeout=timeout) as r:
                    obj = json.loads(r.read().decode("utf-8", "ignore"))
                txt = (obj.get("choices") or [{}])[0].get("message", {}).get("content", "")
                if txt:
                    return txt
            except Exception:
                if attempt < 2:
                    time.sleep(1.2)
    return ""


def _glm_fix(name):
    """把乱七八糟的搜索词/长标题整理成纯片名 + 集数，失败就原样返回"""
    t = _dump(name).strip()
    if not t:
        return {"title": "", "eps": 0}
    if t in _GLM_CACHE:
        return _GLM_CACHE[t]
    out = {"title": t, "eps": 0}
    ans = _glm_chat("把下面的影视标题整理成JSON，只输出JSON，不要解释。"
                    "字段：title（纯片名，去掉画质/更新集数/年份/演员/标签等修饰）、"
                    "eps（总集数，没有就0）。标题：" + t)
    try:
        m = re.search(r"\{[\s\S]*\}", ans)
        if m:
            o = json.loads(m.group(0))
            ti = _dump(o.get("title"))
            if ti:
                out["title"] = ti
            try:
                out["eps"] = int(o.get("eps") or 0)
            except Exception:
                out["eps"] = 0
    except Exception:
        pass
    _GLM_CACHE[t] = out
    return out

def search_content(key, pg):
    key = _dump(key)
    page = _page_of(pg)
    _ck = "%s|%s" % (key, page)
    _ch = SEARCH_CACHE.get(_ck)
    if _ch and _ch[0] > time.time():
        return _ch[1]
    limit = 20
    if not key:
        return {"list": [], "page": page, "pagecount": 0, "limit": limit, "total": 0}
    rows = _db_html_search(key)
    if not rows:
        rows = _db_search(key, 0, limit)
    if not rows:
        rows = _fill_years(_rows(_db_suggest(key)))
    rows = _fill_years(rows, limit)
    start = (page - 1) * limit
    rows = rows[start:start + limit]
    # 万一混进旧版那种 {"t":"片名","n":""} 的名字，直接还原成片名
    for _r in rows:
        _n = _dump(_r.get("vod_name")).strip()
        if _n.startswith("{") and '"t"' in _n:
            try:
                _o = json.loads(_n)
                _r["vod_name"] = _dump(_o.get("t") or _o.get("name") or _n)
            except Exception:
                pass
    more = 1 if len(rows) >= limit else 0
    if page == 1:
        # 片源不再作为独立搜索结果列出，全部并入豆瓣条目的线路里；
        # 只保留红果漫剧这种豆瓣没有的独立内容源。
        try:
            for vod in _hg_search_vods(key):
                rows.append(vod)
        except Exception:
            pass
        # 五大平台搜索补玩偶：玩偶有两条 4K/HDR 候选就出两条，点进去各自查详情
        try:
            _wv = _wogg_search_vods(key, 2)
            # 玩偶条目插到第 2、3 位，跟着豆瓣同名卡一起露出来；
            # 以前 append 到 20 条豆瓣后面，第一屏根本看不到，就像“搜不到玩偶”。
            if _wv:
                rows[1:1] = _wv
        except Exception:
            pass
        # 影集和动漫都按季合并成一条「全季」：搜索只留一个豆瓣条目，
        # 点进去线路按「第1季 / 年番1 / 年番2…」分段，不再逐季列出。
        _has_exact = any(_dump(r.get("vod_name")).replace(" ", "") == key.replace(" ", "")
                         for r in rows)
        if key and _has_exact:
            _base = key.replace(" ", "")
            _seasons = []
            _tags = []
            for _i, _r in enumerate(rows):
                if _dump(_r.get("vod_id")).startswith(("hgd:", "pf:", "txa:")):
                    continue
                _n = _dump(_r.get("vod_name")).replace(" ", "")
                if not _n.startswith(_base):
                    continue
                _rest = _n[len(_base):]
                if _season_tag(_rest):
                    _seasons.append((_i, _r))
                    _tags.append(_season_tag(_rest))
            # 动漫按季单独列在搜索里，方便直接点第一季/第二季/第三季/最终季；
            # 影集仍合成一条「全季」，避免出现两个庆余年。
            _anime_season = bool(_seasons) and any(
                ("动画" in _dump(r.get("type_name")) or "动漫" in _dump(r.get("type_name")))
                for _i, r in _seasons)
            _tags = sorted(set(_season_norm(t) for t in _tags if t), key=_season_rank)
            if len(_seasons) >= 2 and _anime_season:
                # 动漫搜索按季排好：第一季、第二季、第三季、最终季/年番
                _sorted_seasons = sorted(
                    _seasons, key=lambda x: _season_rank(_season_tag(_dump(x[1].get("vod_name")))))
                _sit = {i for i, _r in _seasons}
                _ins = 0
                rows = [r for i, r in enumerate(rows) if i not in _sit]
                for _off, (_i0, _r0) in enumerate(_sorted_seasons):
                    rows.insert(min(_ins + _off, len(rows)), _r0)
            if len(_seasons) >= 2 and not _anime_season:
                _rows2 = [r for i, r in _seasons]
                _pic0 = next((_dump(r.get("vod_pic")) for r in _rows2
                              if _dump(r.get("vod_pic")) and "tv_default" not in _dump(r.get("vod_pic"))), "")
                _merged = {
                    "vod_id": "mrg:" + _pf_b64(key),
                    "vod_name": key + " 全季",
                    "vod_pic": _pic0,
                    "vod_remarks": "全季 · " + "、".join([t for t in _tags if t]) if _tags else ("%d季" % len(_seasons)),
                    "vod_year": _dump(_rows2[0].get("vod_year")),
                    "vod_content": "豆瓣按季合并，线路按季分段",
                    "type_name": _dump(_rows2[0].get("type_name")) or "国产剧",
                }
                _first = _seasons[0][0]
                _drop = {i for i, _ in _seasons}
                # 同名裸条目也并进「全季」，搜索只留一张卡片；红果/平台壳不并
                for _i, _r in enumerate(rows):
                    _rid = _dump(_r.get("vod_id"))
                    if _rid.startswith(("hgd:", "pf:", "txa:", "mrg:")):
                        continue
                    # 玩偶直搜条目是「玩偶@详情页」，不能并进豆瓣「全季」卡，
                    # 否则搜索里永远只剩一张豆瓣卡，看不到玩偶条目。
                    if "@" in _rid:
                        continue
                    if _dump(_r.get("vod_name")).replace(" ", "") == _base:
                        _drop.add(_i)
                rows = [r for i, r in enumerate(rows) if i not in _drop]
                rows.insert(min(_first, len(rows)), _merged)
        # 云帧享加权：把豆瓣里最靠前的同名条目提到第一位；
        # 豆瓣没收录的片子，补一条云帧享条目进来，点开直接播
        try:
            _yr = yz_search_vods(key)
        except Exception:
            _yr = []
        if _yr:
            _kw_norm = _yz_norm(key)
            _boost_i = None
            for _i, _r in enumerate(rows):
                _rid0 = _dump(_r.get("vod_id"))
                if _rid0.startswith(("pf:", "hgd:", "yz:")):
                    continue
                _rn = _yz_norm(_r.get("vod_name"))
                if _rn == _kw_norm or _rn.startswith(_kw_norm):
                    _boost_i = _i
                    break
            if _boost_i is not None:
                _b = rows.pop(_boost_i)
                # 标一下「云帧享 N 集」，让人看得出这条被加权了，也方便判断集数
                _ym = next((x for x in _yr if _yz_norm(x["vod_name"]) == _kw_norm), None)
                if _ym:
                    _rm = _dump(_b.get("vod_remarks"))
                    if "云帧享" not in _rm:
                        _b["vod_remarks"] = (_rm + " · " if _rm else "") + _dump(_ym.get("vod_remarks"))
                rows.insert(0, _b)
            _have = {_yz_norm(_r.get("vod_name")) for _r in rows}
            _extra = [x for x in _yr if _yz_norm(x["vod_name"]) not in _have]
            rows = _extra + rows
    # 影集（真人剧）只留一条「全季」集成条目，不再把第一季/第二季单独铺在搜索里；
    # 动漫仍保留每条「第N季 / 年番」，方便追更时直接点年番。
    try:
        _is_anime = any(("动画" in _dump(r.get("type_name")) or "动漫" in _dump(r.get("type_name")))
                        for r in rows if _dump(r.get("vod_id")).startswith("tv:"))
        if _txa and not _is_anime:
            _base_d = key.replace(" ", "")
            _keep = []
            for _r in rows:
                _rid = _dump(_r.get("vod_id"))
                _nm = _dump(_r.get("vod_name")).replace(" ", "")
                if _rid.startswith("tv:") and _nm.startswith(_base_d) and _season_tag(_nm[len(_base_d):]):
                    continue
                _keep.append(_r)
            rows = _keep
    except Exception:
        pass
    # 有「全季」合并条目时，云帧享同名裸条目不再单独占一张卡
    if page == 1 and any(_dump(_r.get("vod_id")).startswith("mrg:") for _r in rows):
        _kb = key.replace(" ", "")
        rows = [r for r in rows
                if not (_dump(r.get("vod_id")).startswith("yz:")
                        and _dump(r.get("vod_name")).replace(" ", "") == _kb)]
    # 顺手补封面：豆瓣占位图（tv_default / movie-static）换成同名片里能用的那张
    def _pic_ok(_p):
        _p = _dump(_p)
        return bool(_p) and "tv_default" not in _p and "movie-static/pics" not in _p

    _pool = [(_dump(_r.get("vod_name")).strip(), _dump(_r.get("vod_pic"))) for _r in rows]
    for _r in rows:
        if _pic_ok(_r.get("vod_pic")):
            continue
        _nm = _dump(_r.get("vod_name")).strip()
        _hit = next((p for n, p in _pool if p and n == _nm and _pic_ok(p)), "")
        if not _hit:
            _hit = next((p for n, p in _pool if p and n.startswith(_nm) and _pic_ok(p)), "")
        if not _hit:
            _hit = _pf_poster(rows, key) or _dump((rows[0] or {}).get("vod_pic"))
        if _pic_ok(_hit):
            _r["vod_pic"] = _hit
    # 收尾统一洗一遍片名：旧 id、加密串、JSON 串都不许露到界面上
    for _r in rows:
        _n = _dump(_r.get("vod_name")).strip()
        if not _n:
            _r["vod_name"] = "未知片名"
            continue
        if '{' in _n and '"t"' in _n:
            try:
                _o = json.loads(_n[_n.index("{"):])
                _t = _dump(_o.get("t") or _o.get("name") or "")
                if _t:
                    _r["vod_name"] = _t
            except Exception:
                _r["vod_name"] = re.sub(r'\{.*\}', "", _n).strip() or "未知片名"
    # 短剧只留红果的：豆瓣自己的短剧、五大平台官方短剧全部屏蔽
    _SD_WORD = ("短剧", "微短剧", "竖屏剧", "短片", "短剧场", "抖音剧", "快手剧")
    _sd_ids, _sd_names = set(), set()
    for _r in rows:
        _rid = _dump(_r.get("vod_id"))
        if _rid.startswith("hgd:"):
            continue
        _blob = " ".join([_dump(_r.get("vod_name")), _dump(_r.get("type_name")),
                          _dump(_r.get("vod_remarks")), _dump(_r.get("vod_content"))])
        if any(w in _blob for w in _SD_WORD):
            _sd_ids.add(_rid)
            if not _rid.startswith("pf:"):
                _sd_names.add(_dump(_r.get("vod_name")).replace(" ", ""))
    _drop = []
    for _i, _r in enumerate(rows):
        _rid = _dump(_r.get("vod_id"))
        if _rid.startswith("hgd:"):
            continue
        if _rid in _sd_ids:
            _drop.append(_i)
            continue
        # 优酷/爱奇艺两条线整条去过，搜索里的同名条目也别挂
        if _rid.startswith("pf:yk:") or _rid.startswith("pf:iq:"):
            _drop.append(_i)
            continue
        # 平台线：和刚被判定为短剧的同名片(豆瓣那条)同名，也一起屏
        if _rid.startswith("pf:") and _dump(_r.get("vod_name")).replace(" ", "") in _sd_names:
            _drop.append(_i)
    if _drop:
        rows = [r for i, r in enumerate(rows) if i not in set(_drop)]
    _r = {"list": rows, "page": page, "pagecount": page + more, "limit": limit,
          "total": start + len(rows) + (limit if more else 0)}
    SEARCH_CACHE[_ck] = (time.time() + 120, _r)
    while len(SEARCH_CACHE) > 30:
        SEARCH_CACHE.pop(next(iter(SEARCH_CACHE)), None)
    return _r


