def yz_build_sbox():
    p = [0] * 256
    l = [0] * 256
    x = 1
    for i in range(255):
        p[i] = x
        l[x] = i
        x ^= (x << 1) ^ (0x11b if x & 0x80 else 0)
        x &= 0xff

    def rotl(v, n):
        return ((v << n) | (v >> (8 - n))) & 0xff

    box = [0] * 256
    for i in range(256):
        inv = p[(255 - l[i]) % 255] if i else 0
        box[i] = (inv ^ rotl(inv, 1) ^ rotl(inv, 2) ^ rotl(inv, 3) ^ rotl(inv, 4) ^ 0x63) & 0xff
    return box


YZ_SBOX = yz_build_sbox()


def yz_gmul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a = ((a << 1) ^ (0x1b if a & 0x80 else 0)) & 0xff
        b >>= 1
    return r


def yz_expand(key):
    nk, nr = 8, 14
    w = [0] * (16 * (nr + 1))
    w[:32] = list(key[:32])
    rcon = (0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36, 0x6c, 0xd8, 0xab, 0x4d)
    for i in range(nk, 4 * (nr + 1)):
        t = w[(i - 1) * 4:(i - 1) * 4 + 4]
        if i % nk == 0:
            t = [YZ_SBOX[t[1]] ^ rcon[i // nk - 1], YZ_SBOX[t[2]], YZ_SBOX[t[3]], YZ_SBOX[t[0]]]
        elif i % nk == 4:
            t = [YZ_SBOX[x] for x in t]
        b, p = i * 4, (i - nk) * 4
        for j in range(4):
            w[b + j] = w[p + j] ^ t[j]
    return w, nr


def yz_block(ks, block):
    w, nr = ks
    s = [block[i] ^ w[i] for i in range(16)]
    for rnd in range(1, nr + 1):
        for i in range(16):
            s[i] = YZ_SBOX[s[i]]
        t = s[:]
        s[1], s[5], s[9], s[13] = t[5], t[9], t[13], t[1]
        s[2], s[6], s[10], s[14] = t[10], t[14], t[2], t[6]
        s[3], s[7], s[11], s[15] = t[15], t[3], t[7], t[11]
        if rnd != nr:
            for c in range(4):
                a0, a1, a2, a3 = s[c * 4], s[c * 4 + 1], s[c * 4 + 2], s[c * 4 + 3]
                s[c * 4] = yz_gmul(a0, 2) ^ yz_gmul(a1, 3) ^ a2 ^ a3
                s[c * 4 + 1] = a0 ^ yz_gmul(a1, 2) ^ yz_gmul(a2, 3) ^ a3
                s[c * 4 + 2] = a0 ^ a1 ^ yz_gmul(a2, 2) ^ yz_gmul(a3, 3)
                s[c * 4 + 3] = yz_gmul(a0, 3) ^ a1 ^ a2 ^ yz_gmul(a3, 2)
        b = rnd * 16
        for i in range(16):
            s[i] ^= w[b + i]
    return s


def yz_gcm_open(key, payload):
    iv, body = payload[:12], payload[12:]
    data = body[:-16] if len(body) > 16 else body
    ks = yz_expand(key)
    out = bytearray()
    ctr = 2
    for off in range(0, len(data), 16):
        cb = list(iv) + [0, 0, 0, 0]
        cb[12] = (ctr >> 24) & 0xff
        cb[13] = (ctr >> 16) & 0xff
        cb[14] = (ctr >> 8) & 0xff
        cb[15] = ctr & 0xff
        ctr = (ctr + 1) & 0xffffffff
        stream = yz_block(ks, bytes(cb))
        n = min(16, len(data) - off)
        for i in range(n):
            out.append(data[off + i] ^ stream[i])
    return bytes(out)


def yz_decrypt(raw):
    t = str(raw or "").strip()
    if not t:
        return ""
    if t[0] in "[{":
        return t
    s = "".join(ch for ch in t if ch.isalnum() or ch in "+/")
    s += "=" * ((4 - len(s) % 4) % 4)
    try:
        bs = base64.b64decode(s)
    except Exception:
        return ""
    if len(bs) < 40:
        return ""
    for k in YZ_KEYS:
        try:
            txt = yz_gcm_open(k.encode(), bs).decode("utf-8", "ignore")
            if txt.strip()[:1] in "[{":
                return txt
        except Exception:
            continue
    return ""


def yz_parse(text):
    t = str(text or "").strip()
    if not t:
        return None
    try:
        return json.loads(t)
    except Exception:
        pass
    end = max(t.rfind("]"), t.rfind("}"))
    if end > 0:
        try:
            return json.loads(t[:end + 1])
        except Exception:
            pass
    return None


def yz_http(path, data=None, headers=None, timeout=8):
    url = path if path.startswith("http") else YZ_HOST + path
    head = dict(YZ_BASE_HEAD)
    if headers:
        head.update(headers)
    body = None
    if data is not None:
        body = json.dumps(data, ensure_ascii=False).encode("utf-8")
        head.update(YZ_JSON_HEAD)
    req = urllib.request.Request(url, data=body, headers=head)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read().decode("utf-8", "ignore")
    except Exception:
        return ""


def yz_get(path, headers=None, timeout=8):
    return yz_parse(yz_decrypt(yz_http(path, headers=headers, timeout=timeout)))


def yz_post(path, obj, timeout=8):
    return yz_parse(yz_decrypt(yz_http(path, data=obj, timeout=timeout)))


def yz_cget(key, ttl):
    it = YZ_CACHE.get(key)
    if not it or time.time() - it[0] > ttl:
        return None
    return it[1]


def yz_cset(key, val, ttl=600):
    YZ_CACHE[key] = (time.time() + ttl, val)
    while len(YZ_CACHE) > 60:
        YZ_CACHE.pop(next(iter(YZ_CACHE)), None)
    return val


def yz_device_code():
    import random
    seed = "%s|%s|%s|%s" % (YZ_PKG, time.time(), random.random(), YZ_MODEL)
    return hashlib.md5(seed.encode()).hexdigest()[:16]


