# requests 沿用本文件既有绑定：有就用真库，没有就用 urllib 兜底实现
# AES 后端：多数壳没有 cryptography / pycryptodome，缺了就走纯 Python 实现
try:
    from cryptography.hazmat.primitives.ciphers import Cipher as HG2_Cipher, algorithms as HG2_algorithms, modes as HG2_modes
except Exception:
    HG2_Cipher = HG2_algorithms = HG2_modes = None
try:
    from Crypto.Cipher import AES as HG2_CryptoAES
except Exception:
    HG2_CryptoAES = None
if HG2_Cipher is not None:
    HG2_AES_BACKEND = 'cryptography'
elif HG2_CryptoAES is not None:
    HG2_AES_BACKEND = 'pycryptodome'
else:
    HG2_AES_BACKEND = 'none'

class HG2_PureAES128:
    """纯 Python AES-128，供无 pycryptodome/cryptography 的壳使用。"""
    _S = (99, 124, 119, 123, 242, 107, 111, 197, 48, 1, 103, 43, 254, 215, 171, 118, 202, 130, 201, 125, 250, 89, 71, 240, 173, 212, 162, 175, 156, 164, 114, 192, 183, 253, 147, 38, 54, 63, 247, 204, 52, 165, 229, 241, 113, 216, 49, 21, 4, 199, 35, 195, 24, 150, 5, 154, 7, 18, 128, 226, 235, 39, 178, 117, 9, 131, 44, 26, 27, 110, 90, 160, 82, 59, 214, 179, 41, 227, 47, 132, 83, 209, 0, 237, 32, 252, 177, 91, 106, 203, 190, 57, 74, 76, 88, 207, 208, 239, 170, 251, 67, 77, 51, 133, 69, 249, 2, 127, 80, 60, 159, 168, 81, 163, 64, 143, 146, 157, 56, 245, 188, 182, 218, 33, 16, 255, 243, 210, 205, 12, 19, 236, 95, 151, 68, 23, 196, 167, 126, 61, 100, 93, 25, 115, 96, 129, 79, 220, 34, 42, 144, 136, 70, 238, 184, 20, 222, 94, 11, 219, 224, 50, 58, 10, 73, 6, 36, 92, 194, 211, 172, 98, 145, 149, 228, 121, 231, 200, 55, 109, 141, 213, 78, 169, 108, 86, 244, 234, 101, 122, 174, 8, 186, 120, 37, 46, 28, 166, 180, 198, 232, 221, 116, 31, 75, 189, 139, 138, 112, 62, 181, 102, 72, 3, 246, 14, 97, 53, 87, 185, 134, 193, 29, 158, 225, 248, 152, 17, 105, 217, 142, 148, 155, 30, 135, 233, 206, 85, 40, 223, 140, 161, 137, 13, 191, 230, 66, 104, 65, 153, 45, 15, 176, 84, 187, 22)
    _RCON = (0, 1, 2, 4, 8, 16, 32, 64, 128, 27, 54)

    def __init__(self, key: bytes):
        if len(key) != 16:
            raise ValueError('AES-128 only')
        self._rk = self._expand(key)

    def _expand(self, key: bytes):
        s = self._S
        w = list(key)
        for i in range(4, 44):
            t0, t1, t2, t3 = (w[-4], w[-3], w[-2], w[-1])
            if i % 4 == 0:
                t0, t1, t2, t3 = (s[t1], s[t2], s[t3], s[t0])
                t0 ^= self._RCON[i // 4]
            base = (i - 4) * 4
            w.extend((w[base] ^ t0, w[base + 1] ^ t1, w[base + 2] ^ t2, w[base + 3] ^ t3))
        return w

    @staticmethod
    def _xtime(a: int) -> int:
        return (a << 1 ^ 27) & 255 if a & 128 else a << 1 & 255

    def encrypt_block(self, block: bytes) -> bytes:
        s = list(block)
        rk = self._rk
        for i in range(16):
            s[i] ^= rk[i]
        for rnd in range(1, 10):
            s = [self._S[b] for b in s]
            s = [s[0], s[5], s[10], s[15], s[4], s[9], s[14], s[3], s[8], s[13], s[2], s[7], s[12], s[1], s[6], s[11]]
            for c in range(4):
                i = c * 4
                a, b, c0, d = (s[i], s[i + 1], s[i + 2], s[i + 3])
                t = a ^ b ^ c0 ^ d
                u = a
                a ^= t ^ self._xtime(a ^ b)
                b ^= t ^ self._xtime(b ^ c0)
                c0 ^= t ^ self._xtime(c0 ^ d)
                d ^= t ^ self._xtime(d ^ u)
                s[i], s[i + 1], s[i + 2], s[i + 3] = (a, b, c0, d)
            off = rnd * 16
            for i in range(16):
                s[i] ^= rk[off + i]
        s = [self._S[b] for b in s]
        s = [s[0], s[5], s[10], s[15], s[4], s[9], s[14], s[3], s[8], s[13], s[2], s[7], s[12], s[1], s[6], s[11]]
        for i in range(16):
            s[i] ^= rk[160 + i]
        return bytes(s)

    def decrypt_block(self, block: bytes) -> bytes:

        def mul(a, b):
            p = 0
            for _ in range(8):
                if b & 1:
                    p ^= a
                hi = a & 128
                a = a << 1 & 255
                if hi:
                    a ^= 27
                b >>= 1
            return p
        s = list(block)
        rk = self._rk
        for i in range(16):
            s[i] ^= rk[160 + i]
        for rnd in range(9, 0, -1):
            s = [s[0], s[13], s[10], s[7], s[4], s[1], s[14], s[11], s[8], s[5], s[2], s[15], s[12], s[9], s[6], s[3]]
            s = [self._SI[b] for b in s]
            off = rnd * 16
            for i in range(16):
                s[i] ^= rk[off + i]
            for c in range(4):
                i = c * 4
                a, b, c0, d = (s[i], s[i + 1], s[i + 2], s[i + 3])
                s[i] = mul(a, 14) ^ mul(b, 11) ^ mul(c0, 13) ^ mul(d, 9)
                s[i + 1] = mul(a, 9) ^ mul(b, 14) ^ mul(c0, 11) ^ mul(d, 13)
                s[i + 2] = mul(a, 13) ^ mul(b, 9) ^ mul(c0, 14) ^ mul(d, 11)
                s[i + 3] = mul(a, 11) ^ mul(b, 13) ^ mul(c0, 9) ^ mul(d, 14)
        s = [s[0], s[13], s[10], s[7], s[4], s[1], s[14], s[11], s[8], s[5], s[2], s[15], s[12], s[9], s[6], s[3]]
        s = [self._SI[b] for b in s]
        for i in range(16):
            s[i] ^= rk[i]
        return bytes(s)

def HG2_pure_ctr_decrypt(key: bytes, counter: bytes, data: bytes) -> bytes:
    if not data:
        return b''
    if len(counter) < 16:
        counter = counter.ljust(16, b'\x00')
    else:
        counter = counter[:16]
    aes = HG2_PureAES128(key)
    ctr = int.from_bytes(counter, 'big')
    out = bytearray()
    for offset in range(0, len(data), 16):
        ks = aes.encrypt_block(ctr.to_bytes(16, 'big'))
        ctr = ctr + 1 & (1 << 128) - 1
        chunk = data[offset:offset + 16]
        out.extend((c ^ k for c, k in zip(chunk, ks)))
    return bytes(out)

def HG2_pure_cbc_decrypt(key: bytes, iv: bytes, data: bytes) -> bytes:
    if not data:
        return b''
    if len(data) % 16:
        data = data[:len(data) - len(data) % 16]
    aes = HG2_PureAES128(key)
    prev = (iv[:16] if len(iv) >= 16 else iv).ljust(16, b'\x00')
    out = bytearray()
    for i in range(0, len(data), 16):
        block = data[i:i + 16]
        dec = aes.decrypt_block(block)
        out.extend((d ^ p for d, p in zip(dec, prev)))
        prev = block
    return bytes(out)

def HG2_aes_ctr_decrypt(key: bytes, counter: bytes, data: bytes) -> bytes:
    if not data:
        return b''
    if HG2_AES_BACKEND == 'cryptography':
        decryptor = HG2_Cipher(HG2_algorithms.AES(key), HG2_modes.CTR(counter)).decryptor()
        return decryptor.update(data) + decryptor.finalize()
    if HG2_AES_BACKEND == 'pycryptodome':
        cipher = HG2_CryptoAES.new(key, HG2_CryptoAES.MODE_CTR, nonce=b'', initial_value=counter)
        return cipher.decrypt(data)
    return HG2_pure_ctr_decrypt(key, counter, data)

def HG2_aes_cbc_decrypt(key: bytes, iv: bytes, data: bytes) -> bytes:
    if not data:
        return b''
    if HG2_AES_BACKEND == 'cryptography':
        decryptor = HG2_Cipher(HG2_algorithms.AES(key), HG2_modes.CBC(iv)).decryptor()
        return decryptor.update(data) + decryptor.finalize()
    if HG2_AES_BACKEND == 'pycryptodome':
        return HG2_CryptoAES.new(key, HG2_CryptoAES.MODE_CBC, iv).decrypt(data)
    return HG2_pure_cbc_decrypt(key, iv, data)
