class HG2_HongguoPluginError(RuntimeError):
    pass

def HG2_text(value: Any) -> str:
    return str(value or '').strip()

def HG2_first(*values: Any) -> str:
    for value in values:
        if isinstance(value, (list, tuple)):
            result = HG2_first(*value)
        elif isinstance(value, Mapping):
            result = HG2_first(value.get('url'), value.get('uri'), value.get('src'), value.get('download_url'), value.get('main_url'), value.get('backup_url'), value.get('backup_url_1'), value.get('play_addr'), value.get('url_list'))
        else:
            result = HG2_text(value)
        if result:
            return result
    return ''

def HG2_json_response(response: requests.Response) -> Any:
    response.raise_for_status()
    try:
        return response.json()
    except ValueError as exc:
        raise HG2_HongguoPluginError('上游响应不是 JSON') from exc

def HG2_media_url(item: Mapping[str, Any]) -> str:
    return HG2_first(item.get('main_url'), item.get('backup_url'), item.get('backup_url_1'), item.get('play_addr'), item.get('url'))

def HG2_spade_value(item: Mapping[str, Any]) -> str:
    encrypt_info = item.get('encrypt_info')
    if not isinstance(encrypt_info, Mapping):
        encrypt_info = {}
    return HG2_first(item.get('spade_a'), encrypt_info.get('spade_a'))

def HG2_derive_content_key(spade_b64: str) -> bytes:
    raw = HG2_b64(spade_b64)
    if len(raw) < 3:
        raise HG2_HongguoPluginError('spade_a 太短')
    v8 = len(raw) - (raw[0] ^ raw[1] ^ raw[2]) + 47
    if v8 <= 0 or 1 + v8 > len(raw):
        v8 = len(raw) - 1
    if v8 < 33:
        raise HG2_HongguoPluginError('spade_a 长度异常')
    value = bytearray(raw[1:1 + v8])
    va, vb = (85, 246)
    for index in range(v8):
        previous = va if index & 1 else vb
        if index & 1:
            va = value[index]
        else:
            vb = value[index]
        value[index] = -21 - bin(index).count('1') + (previous ^ value[index]) & 255
    try:
        return binascii.unhexlify(bytes(value[1:33]).decode('ascii'))
    except (ValueError, binascii.Error) as exc:
        raise HG2_HongguoPluginError('spade_a 密钥材料无效') from exc

def HG2_find_box(data: memoryview, fourcc: bytes, start: int) -> tuple[int, int]:
    for index in range(max(4, start), len(data) - 4):
        if data[index:index + 4] != fourcc:
            continue
        size = struct.unpack('>I', data[index - 4:index])[0]
        if size == 1 and index + 12 <= len(data):
            size = struct.unpack('>Q', data[index + 4:index + 12])[0]
        if 8 <= size <= 5000000 and index - 4 + size <= len(data):
            return (index - 4, size)
    return (-1, 0)

def HG2_box_body(data: memoryview, fourcc: bytes, start: int) -> memoryview | None:
    offset, size = HG2_find_box(data, fourcc, start)
    return data[offset + 8:offset + size] if offset >= 0 else None

def HG2_parse_track(moov: memoryview, track_offset: int) -> tuple[list[int], list[int], list[int], list[int], int, int] | None:
    if track_offset < 0:
        return None
    stbl_offset, _ = HG2_find_box(moov, b'stbl', track_offset + 8)
    if stbl_offset < 0:
        return None
    stsz = HG2_box_body(moov, b'stsz', stbl_offset)
    stco = HG2_box_body(moov, b'stco', stbl_offset)
    co64 = HG2_box_body(moov, b'co64', stbl_offset)
    stsc = HG2_box_body(moov, b'stsc', stbl_offset)
    saiz = HG2_box_body(moov, b'saiz', stbl_offset)
    saio = HG2_box_body(moov, b'saio', stbl_offset)
    if any((value is None for value in (stsz, stsc, saiz, saio))) or (stco is None and co64 is None):
        return None
    assert stsz is not None and stsc is not None
    assert saiz is not None and saio is not None
    default_size = struct.unpack('>I', stsz[4:8])[0]
    sample_count = struct.unpack('>I', stsz[8:12])[0]
    sizes = [default_size] * sample_count if default_size else [struct.unpack('>I', stsz[12 + index * 4:16 + index * 4])[0] for index in range(sample_count)]
    chunk_table = stco if stco is not None else co64
    assert chunk_table is not None
    chunk_count = struct.unpack('>I', chunk_table[4:8])[0]
    chunk_width = 4 if stco is not None else 8
    offsets = [int.from_bytes(chunk_table[8 + index * chunk_width:8 + (index + 1) * chunk_width], 'big') for index in range(chunk_count)]
    entry_count = struct.unpack('>I', stsc[4:8])[0]
    entries = [(struct.unpack('>I', stsc[8 + index * 12:12 + index * 12])[0], struct.unpack('>I', stsc[12 + index * 12:16 + index * 12])[0]) for index in range(entry_count)]
    chunk_samples = [0] * chunk_count
    for index, (first_chunk, samples_per_chunk) in enumerate(entries):
        end = entries[index + 1][0] - 1 if index + 1 < len(entries) else chunk_count
        for chunk in range(first_chunk - 1, min(end, chunk_count)):
            chunk_samples[chunk] = samples_per_chunk
    saiz_flags = int.from_bytes(saiz[1:4], 'big')
    saiz_cursor = 12 if saiz_flags & 1 else 4
    if len(saiz) < saiz_cursor + 5:
        return None
    default_aux_size = saiz[saiz_cursor]
    aux_count = struct.unpack('>I', saiz[saiz_cursor + 1:saiz_cursor + 5])[0]
    aux_sizes = [default_aux_size] * aux_count if default_aux_size else [int(saiz[saiz_cursor + 5 + index]) for index in range(aux_count) if saiz_cursor + 5 + index < len(saiz)]
    if len(aux_sizes) != aux_count:
        return None
    saio_flags = int.from_bytes(saio[1:4], 'big')
    saio_cursor = 12 if saio_flags & 1 else 4
    offset_width = 8 if saio[0] == 1 else 4
    if len(saio) < saio_cursor + 4 + offset_width:
        return None
    entry_count = int.from_bytes(saio[saio_cursor:saio_cursor + 4], 'big')
    if entry_count < 1:
        return None
    aux_offset = int.from_bytes(saio[saio_cursor + 4:saio_cursor + 4 + offset_width], 'big')
    return (sizes, offsets, chunk_samples, aux_sizes, aux_offset, sample_count)

def HG2_replace_sinf(data: bytearray) -> None:
    _sinf_children = (b'frma', b'schm', b'schi')
    position = 0
    while True:
        position = data.find(b'sinf', position)
        if position < 0:
            return
        if position >= 4:
            size = struct.unpack('>I', data[position - 4:position])[0]
            end = position - 4 + size
            child = bytes(data[position + 8:position + 12])
            if 8 <= size < 50000 and end <= len(data) and (child in _sinf_children):
                data[position:position + 4] = b'free'
                data[position + 4:end] = b'\x00' * max(0, end - position - 4)
                position = end
                continue
        position += 4
HG2_MEDIA_HEADERS = {'User-Agent': HG2_MEDIA_UA, 'Referer': 'https://novel.snssdk.com/'}
HG2_STREAM_PORT_RANGE = (10010, 10030)
HG2_STREAM_CHUNK = 1 << 20
HG2_STREAM_HEAD_PROBE = 1 << 16
HG2_STREAM_TTL_SECONDS = 900
HG2_STREAM_MAX_SESSIONS = 4
HG2_STREAM_INFLIGHT_WAIT = 60
HG2_STREAM_STATE: dict[str, Any] = {'port': 0, 'server': None, 'sessions': {}, 'inflight': {}}
HG2_STREAM_LOCK = threading.RLock()

def HG2_toplevel_boxes(buf: bytes) -> list[tuple[int, int, bytes]]:
    boxes: list[tuple[int, int, bytes]] = []
    cursor = 0
    while cursor + 8 <= len(buf):
        size = struct.unpack('>I', buf[cursor:cursor + 4])[0]
        fourcc = bytes(buf[cursor + 4:cursor + 8])
        if size == 1:
            if cursor + 16 > len(buf):
                break
            size = struct.unpack('>Q', buf[cursor + 8:cursor + 16])[0]
        if size < 8:
            break
        boxes.append((cursor, size, fourcc))
        cursor += size
    return boxes

def HG2_range_get(url: str, start: int, end: int) -> tuple[bytes, int]:
    headers = dict(HG2_MEDIA_HEADERS)
    headers['Range'] = 'bytes=%d-%d' % (start, end)
    expected = end - start + 1
    last_error: Exception | None = None
    for attempt in range(HG2_RANGE_FETCH_ATTEMPTS):
        if attempt:
            time.sleep(HG2_RANGE_FETCH_BACKOFF_SECONDS * attempt)
        try:
            response = requests.get(url, headers=headers, timeout=60)
        except requests.RequestException as error:
            last_error = error
            continue
        if response.status_code not in (200, 206):
            last_error = HG2_HongguoPluginError('媒体分片请求失败 %s' % response.status_code)
            continue
        body = response.content
        if not body or (response.status_code == 206 and len(body) < expected):
            last_error = HG2_HongguoPluginError('媒体分片长度不足 %d/%d' % (len(body), expected))
            continue
        total = 0
        content_range = response.headers.get('Content-Range') or ''
        if '/' in content_range:
            tail = content_range.rsplit('/', 1)[1].strip()
            if tail.isdigit():
                total = int(tail)
        if not total:
            length = response.headers.get('Content-Length') or ''
            total = int(length) if length.isdigit() else 0
        return (body, total)
    raise last_error or HG2_HongguoPluginError('媒体分片请求失败')

def HG2_fetch_moov(url: str) -> tuple[int, int, bytes]:
    probe, total = HG2_range_get(url, 0, HG2_STREAM_HEAD_PROBE - 1)
    if not total:
        raise HG2_HongguoPluginError('媒体总长度未知')
    moov_start = 0
    moov_size = 0
    for offset, size, fourcc in HG2_toplevel_boxes(probe):
        if fourcc == b'moov':
            moov_start = offset
            moov_size = size
            break
    if not moov_size:
        raise HG2_HongguoPluginError('未找到 moov 顶层盒')
    if moov_start + moov_size > total:
        raise HG2_HongguoPluginError('moov 越界')
    if moov_start + moov_size <= len(probe):
        return (total, moov_start, bytes(probe[moov_start:moov_start + moov_size]))
    moov, _ = HG2_range_get(url, moov_start, moov_start + moov_size - 1)
    if len(moov) != moov_size:
        raise HG2_HongguoPluginError('moov 分片长度不符')
    return (total, moov_start, moov)
HG2_CONFIG_BOX_TO_FORMAT = ((b'hvcC', b'hvc1'), (b'hev1C', b'hev1'), (b'av1C', b'av01'), (b'vpcC', b'vp09'), (b'avcC', b'avc1'), (b'dvvC', b'dvh1'), (b'dvhC', b'dvh1'))
HG2_AUDIO_CONFIG_BOX_TO_FORMAT = ((b'esds', b'mp4a'), (b'opusC', b'Opus'), (b'ac-3', b'ac-3'), (b'ec-3', b'ec-3'))

def HG2_format_from_config_box(blob: bytes, kind: bytes) -> bytes:
    """按 sample entry 内的解码器配置盒推断真实编码，找不到返回空串。"""
    probes = HG2_AUDIO_CONFIG_BOX_TO_FORMAT + HG2_CONFIG_BOX_TO_FORMAT if kind == b'enca' else HG2_CONFIG_BOX_TO_FORMAT + HG2_AUDIO_CONFIG_BOX_TO_FORMAT
    hit_pos, hit_fmt = (-1, b'')
    for fourcc, fmt in probes:
        pos = blob.find(fourcc)
        if pos >= 0 and (hit_pos < 0 or pos < hit_pos):
            hit_pos, hit_fmt = (pos, fmt)
    return hit_fmt

def HG2_original_format_near(data: bytearray, entry_pos: int, default: bytes, kind: bytes=b'encv') -> bytes:
    """从 sample entry 后的 sinf/frma 读取原始四字符码（avc1/hvc1/mp4a 等）。
    frma 缺失/无效时回退到配置盒探测，而不是一律兜底 avc1。"""
    blob = bytes(data[entry_pos:min(len(data), entry_pos + 800)])
    idx = 0
    while True:
        pos = blob.find(b'frma', idx)
        if pos < 0:
            break
        if pos + 8 <= len(blob):
            fmt = bytes(blob[pos + 4:pos + 8])
            if fmt not in (b'', b'\x00\x00\x00\x00', b'encv', b'enca') and all((32 <= c < 127 for c in fmt)):
                return fmt
        idx = pos + 4
    probed = HG2_format_from_config_box(blob, kind)
    return probed or default

def HG2_restore_cenc_codecs(data: bytearray) -> None:
    """把 encv/enca 还原为真实编码（frma 优先，其次按 avcC/hvcC 等配置盒判定）。
    避免一律改成 avc1/hvc1 导致非对应编码的视轨解不出画面。"""
    pos = 0
    while True:
        pos = data.find(b'encv', pos)
        if pos < 0:
            break
        data[pos:pos + 4] = HG2_original_format_near(data, pos, b'avc1', b'encv')
        pos += 4
    pos = 0
    while True:
        pos = data.find(b'enca', pos)
        if pos < 0:
            break
        data[pos:pos + 4] = HG2_original_format_near(data, pos, b'mp4a', b'enca')
        pos += 4

def HG2_moov_has_video_track(moov: bytes) -> bool:
    """moov 中是否存在 hdlr='vide' 的轨。用于校验某清晰度是否真的带视轨。"""
    view = memoryview(moov)
    search = 0
    found_trak = False
    while True:
        trak, trak_size = HG2_find_box(view, b'trak', search)
        if trak < 0:
            break
        found_trak = True
        search = trak + max(trak_size, 8)
        hdlr = HG2_box_body(view, b'hdlr', trak + 8)
        if hdlr is not None and len(hdlr) >= 12:
            if bytes(hdlr[8:12]) == b'vide':
                return True
    return not found_trak

def HG2_rewrite_moov(moov: bytes) -> bytes:
    result = bytearray(moov)
    HG2_restore_cenc_codecs(result)
    HG2_replace_sinf(result)
    return bytes(result)

def HG2_sample_table(moov: bytes, moov_start: int) -> list[tuple[int, int, bytes]]:
    view = memoryview(moov)
    samples: list[tuple[int, int, bytes]] = []
    track_search = 0
    while True:
        track, track_size = HG2_find_box(view, b'trak', track_search)
        if track < 0:
            break
        track_search = track + max(track_size, 8)
        parsed = HG2_parse_track(view, track)
        if parsed is None:
            continue
        sizes, offsets, chunk_counts, aux_sizes, aux_offset, sample_count = parsed
        aux_length = sum((max(size, 8) for size in aux_sizes))
        aux_local = aux_offset - moov_start
        if aux_local < 0 or aux_local + aux_length > len(moov):
            raise HG2_HongguoPluginError('CENC 辅助信息不在 moov 内，无法流式解密')
        aux = moov[aux_local:aux_local + aux_length]
        sample_index = 0
        aux_index = 0
        for chunk_index, chunk_offset in enumerate(offsets):
            current = chunk_offset
            for _ in range(chunk_counts[chunk_index]):
                if sample_index >= sample_count or sample_index >= len(sizes):
                    break
                if sample_index >= len(aux_sizes):
                    raise HG2_HongguoPluginError('CENC 辅助信息数量不足')
                entry_size = max(aux_sizes[sample_index], 8)
                initial_vector = bytes(aux[aux_index:aux_index + min(entry_size, 8)]).ljust(8, b'\x00') + b'\x00' * 8
                samples.append((current, sizes[sample_index], initial_vector))
                current += sizes[sample_index]
                aux_index += entry_size
                sample_index += 1
    if not samples:
        raise HG2_HongguoPluginError('moov 中没有可解密的 CENC 样本')
    samples.sort()
    return samples

class HG2_StreamSession:
    """按 Range 逐块拉取加密 MP4，边下边解 CENC，供本地播放器直连。"""

    def __init__(self, url: str, content_key: bytes, total: int, moov_start: int, moov: bytes) -> None:
        if len(content_key) != 16:
            raise HG2_HongguoPluginError('CENC 密钥长度错误')
        self.url = url
        self.content_key = content_key
        self.total = total
        self.moov_start = moov_start
        self.moov_plain = HG2_rewrite_moov(moov)
        self.moov_end = moov_start + len(moov)
        self.samples = HG2_sample_table(moov, moov_start)
        self.offsets = [item[0] for item in self.samples]
        self.created = time.time()

    def expired(self) -> bool:
        return time.time() - self.created > HG2_STREAM_TTL_SECONDS

    def _patch(self, buffer: bytearray, base: int) -> None:
        end = base + len(buffer) - 1
        index = max(bisect.bisect_right(self.offsets, base) - 1, 0)
        while index < len(self.samples):
            offset, size, initial_vector = self.samples[index]
            index += 1
            if offset > end:
                break
            if offset + size <= base:
                continue
            first = max(offset, base)
            last = min(offset + size - 1, end)
            skip = first - offset
            counter = (int.from_bytes(initial_vector, 'big') + skip // 16 & (1 << 128) - 1).to_bytes(16, 'big')
            padding = skip % 16
            plain = HG2_aes_ctr_decrypt(self.content_key, counter, b'\x00' * padding + bytes(buffer[first - base:last - base + 1]))
            buffer[first - base:last - base + 1] = plain[padding:]
        if base < self.moov_end and end >= self.moov_start:
            first = max(base, self.moov_start)
            last = min(end, self.moov_end - 1)
            buffer[first - base:last - base + 1] = self.moov_plain[first - self.moov_start:last - self.moov_start + 1]

    def read_range(self, start: int, end: int) -> bytes:
        raw, _ = HG2_range_get(self.url, start, end)
        if not raw:
            raise HG2_HongguoPluginError('媒体分片为空')
        buffer = bytearray(raw)
        self._patch(buffer, start)
        return bytes(buffer)

    def iter_range(self, start: int, end: int):
        cursor = start
        while cursor <= end:
            stop = min(cursor + HG2_STREAM_CHUNK - 1, end)
            block = self.read_range(cursor, stop)
            yield block
            cursor += len(block)

def HG2_fresh_device_pair() -> tuple[str, str]:
    return (str(random.randint(10 ** 17, 10 ** 18 - 1)), str(random.randint(10 ** 17, 10 ** 18 - 1)))

def HG2_is_empty_model_error(err: BaseException) -> bool:
    text = str(err)
    return 'video_model 数据为空' in text or 'video_model 为空' in text or '上游响应不是 JSON' in text or ('播放模型没有清晰度' in text) or ('播放模型缺少地址或密钥材料' in text)

def HG2_register_device_pair() -> tuple[str, str] | None:
    try:
        import uuid as _uuid
        openudid = ''.join((random.choice('0123456789abcdef') for _ in range(16)))
        header = {'display_name': '红果免费短剧', 'aid': 8662, 'app_version': '7.1.3.32', 'version_code': 71332, 'manifest_version_code': 71332, 'update_version_code': 71332, 'channel': 'update_64', 'package': 'com.phoenix.read', 'app_language': 'zh', 'os': 'Android', 'os_version': '16', 'os_api': 36, 'device_model': '25053RT47C', 'device_brand': 'Redmi', 'device_manufacturer': 'Xiaomi', 'cpu_abi': 'arm64-v8a', 'density_dpi': 520, 'display_density': 'xxhdpi', 'resolution': '2772x1280', 'language': 'zh', 'timezone': 8, 'access': 'wifi', 'openudid': openudid, 'clientudid': str(_uuid.uuid4()), 'cdid': str(_uuid.uuid4()), 'region': 'CN', 'tz_name': 'Asia/Shanghai', 'tz_offset': 28800, 'sim_region': 'cn', 'device_platform': 'android', 'not_request_sender': 0, 'is_system_app': 0, 'sdk_flavor': 'china', 'rom': 'OS2.0', 'rom_version': 'BP2A.250605.031.A3'}
        body = json.dumps({'magic_tag': 'ss_app_log', 'header': header, '_gen_time': int(time.time() * 1000)}).encode('utf-8')
        qs = urlencode({'req_id': str(_uuid.uuid4()), '_rticket': int(time.time() * 1000)})
        resp = requests.post('https://log.snssdk.com/service/2/device_register/?' + qs, data=body, headers={'User-Agent': HG2_APP_UA, 'Accept': 'application/json', 'Content-Type': 'application/json; charset=utf-8'}, timeout=20)
        if resp.status_code != 200:
            return None
        data = resp.json()
        did = str(data.get('device_id_str') or data.get('device_id') or '')
        iid = str(data.get('install_id_str') or data.get('install_id') or '')
        if did.isdigit() and iid.isdigit() and (did != '0') and (iid != '0'):
            return (did, iid)
    except Exception:
        pass
    return None

def HG2_rotate_stream_device() -> dict[str, str]:
    registered = HG2_register_device_pair()
    if registered is not None:
        device_id, install_id = registered
        is_registered = True
    else:
        device_id, install_id = HG2_fresh_device_pair()
        is_registered = False
    pair = {'device_id': device_id, 'install_id': install_id}
    with HG2_STREAM_LOCK:
        stored = dict(pair)
        stored['registered'] = is_registered
        HG2_STREAM_STATE['device'] = stored
    return pair

def HG2_working_device_pair() -> dict[str, str] | None:
    with HG2_STREAM_LOCK:
        pair = HG2_STREAM_STATE.get('device')
    if isinstance(pair, dict) and pair.get('device_id') and pair.get('install_id'):
        return {'device_id': str(pair['device_id']), 'install_id': str(pair['install_id'])}
    return None

def HG2_video_model_rotating(video_id: str, config: Mapping[str, Any]) -> dict[str, Any]:
    """红果空包是按时间段成波出现的，不是某个 vid 坏了。
    实测只重试 2 轮经常全空，这里改成 5 轮：每轮两个 host 交替、
    失败就换一台新设备号，退避 0.2~0.6 秒，尽量在 3 秒级抓住空包间隙。"""
    last_err = None
    _deadline = time.time() + 9.0
    for attempt in range(5):
        if time.time() > _deadline:
            break
        try:
            return HG2_video_model(video_id, config, host_first=attempt % 2, deadline=_deadline)
        except Exception as err:
            last_err = err
            if not HG2_is_empty_model_error(err) and not isinstance(
                    err, (requests.ConnectionError, requests.Timeout)):
                # 签名/端点类错误也继续换组合，不要在第一轮就放弃
                pass
        try:
            time.sleep(min(0.2 * (attempt + 1), 0.6))
        except Exception:
            pass
        pair = HG2_rotate_stream_device()
        try:
            config['device_id'] = pair['device_id']
            config['install_id'] = pair['install_id']
        except (TypeError, AttributeError):
            config = dict(pair)
    raise last_err if last_err is not None else HG2_HongguoPluginError('video_model 为空')

def HG2_stream_session(video_id: str, config: Mapping[str, Any], quality: str='1080') -> '_StreamSession':
    quality = quality if quality in HG2_QUALITY_LINE_NAME_TO_Q else '1080'
    cache_key = '%s|%s' % (video_id, quality)
    with HG2_STREAM_LOCK:
        sessions = HG2_STREAM_STATE['sessions']
        for key in [key for key, item in sessions.items() if item.expired()]:
            sessions.pop(key, None)
        session = sessions.get(cache_key)
    if session is not None:
        return session
    with HG2_STREAM_LOCK:
        inflight = HG2_STREAM_STATE.setdefault('inflight', {})
        event = inflight.get(cache_key)
        leader = event is None
        if leader:
            event = threading.Event()
            inflight[cache_key] = event
    if not leader:
        event.wait(HG2_STREAM_INFLIGHT_WAIT)
        with HG2_STREAM_LOCK:
            session = HG2_STREAM_STATE['sessions'].get(cache_key)
        if session is not None:
            return session
    last_err = None
    try:
        for _attempt in range(3):
            try:
                model = HG2_video_model_rotating(video_id, config)
                rows = HG2_video_list_from_model(model)
                key_seed = HG2_key_seed_from_model(model) or ''
                wanted_order = [quality] + [q for q in HG2_QUALITY_ORDER if q != quality]
                seen_urls = set()
                reason = '媒体会话创建失败'
                probed = 0
                for want in wanted_order:
                    _, item = HG2_select_quality(rows, want)
                    raw_url = HG2_media_url(item)
                    spade = HG2_spade_value(item)
                    if not raw_url or not spade:
                        reason = reason if reason != '媒体会话创建失败' else '播放模型缺少地址或密钥材料 q=%s' % want
                        continue
                    if raw_url in seen_urls:
                        continue
                    seen_urls.add(raw_url)
                    url = raw_url
                    if key_seed:
                        try:
                            url = HG2_decrypt_spade_url(raw_url, key_seed) or raw_url
                        except HG2_HongguoPluginError:
                            url = raw_url
                    total, moov_start, moov = HG2_fetch_moov(url)
                    if HG2_moov_has_video_track(moov):
                        session = HG2_StreamSession(url, HG2_derive_content_key(spade), total, moov_start, moov)
                        with HG2_STREAM_LOCK:
                            sessions = HG2_STREAM_STATE['sessions']
                            while len(sessions) >= HG2_STREAM_MAX_SESSIONS:
                                sessions.pop(next(iter(sessions)), None)
                            sessions[cache_key] = session
                        return session
                    reason = '该清晰度没有视轨 q=%s' % want
                    probed += 1
                    if probed >= 2:
                        break
                raise HG2_HongguoPluginError(reason)
            except Exception as err:
                last_err = err
                try:
                    time.sleep(0.4 * (_attempt + 1))
                except Exception:
                    pass
        if last_err is not None:
            raise last_err
        raise HG2_HongguoPluginError('媒体会话创建失败')
    finally:
        if leader:
            with HG2_STREAM_LOCK:
                HG2_STREAM_STATE.get('inflight', {}).pop(cache_key, None)
            event.set()
HG2_RANGE_UNSATISFIABLE = 'unsatisfiable'

def HG2_parse_range(value: str, total: int) -> Any:
    """解析 Range 头。返回 (start, end)、None（忽略）或 _RANGE_UNSATISFIABLE。"""
    text = (value or '').strip().lower()
    if not text.startswith('bytes='):
        return None
    spec = text[6:].split(',')[0].strip()
    if '-' not in spec:
        return None
    left, right = spec.split('-', 1)
    if not left:
        if not right.isdigit():
            return None
        length = min(int(right), total)
        if not length:
            return HG2_RANGE_UNSATISFIABLE
        return (total - length, total - 1)
    if not left.isdigit():
        return None
    start = int(left)
    end = int(right) if right.isdigit() else total - 1
    end = min(end, total - 1)
    if start >= total or start > end:
        return HG2_RANGE_UNSATISFIABLE
    return (start, end)

class HG2_StreamHandler(BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'
    server_version = 'hg-stream'

    def log_message(self, *args: Any) -> None:
        return None

    def _params(self) -> dict[str, str]:
        parsed = urlparse(self.path)
        query = parse_qs(parsed.query)
        video_id = (query.get('vid') or query.get('id') or [''])[0]
        if not video_id:
            video_id = parsed.path.rsplit('/', 1)[-1].split('.')[0]
        return {'vid': video_id if video_id.isdigit() else '', 'quality': (query.get('q') or ['1080'])[0], 'device_id': (query.get('did') or [''])[0], 'install_id': (query.get('iid') or [''])[0]}

    def _fail(self, code: int, message: bytes) -> None:
        self.send_response(code)
        self.send_header('Content-Type', 'text/plain; charset=utf-8')
        self.send_header('Content-Length', str(len(message)))
        self.send_header('Connection', 'close')
        self.end_headers()
        try:
            self.wfile.write(message)
        except OSError:
            pass

    def do_HEAD(self) -> None:
        self._serve(body=False)

    def do_GET(self) -> None:
        self._serve(body=True)

    def _serve_danmaku(self, body: bool) -> None:
        """本机弹幕路由：/hg_dm?vid=..&sid=..&fmt=xml|json，/hg_dm_debug 自检。"""
        parsed = urlparse(self.path)
        query = parse_qs(parsed.query)
        vid = (query.get('vid') or query.get('id') or [''])[0]
        sid = (query.get('sid') or [''])[0]
        fmt = ((query.get('fmt') or ['xml'])[0] or 'xml').lower()
        did = (query.get('did') or [''])[0]
        iid = (query.get('iid') or [''])[0]
        if not str(vid).isdigit():
            self._fail(400, b'missing vid')
            return
        if not sid:
            sid = HG2_dm_series_of(vid)
        try:
            HG2_DM_HIT[vid] = time.time()
        except Exception:
            pass
        state = HG2_dm_get(vid, sid, did, iid, wait=HG2_DM_WAIT)
        items = state.get('items') or []
        if parsed.path.rstrip('/').endswith('debug'):
            payload = {'vid': vid, 'sid': sid, 'count': len(items), 'error': state.get('error') or '', 'ts': state.get('t') or 0, 'head': items[:3]}
            data = json.dumps(payload, ensure_ascii=False).encode('utf-8')
            ctype = 'application/json; charset=utf-8'
        elif fmt == 'json':
            data = HG2_dm_to_json(items)
            ctype = 'application/json; charset=utf-8'
        else:
            data = HG2_dm_to_xml(vid, items)
            ctype = 'application/xml; charset=utf-8'
        self.send_response(200)
        self.send_header('Content-Type', ctype)
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Connection', 'close')
        self.end_headers()
        if not body:
            return
        try:
            self.wfile.write(data)
        except OSError:
            pass

    def _serve_dash(self, vid: str, kind: str, body: bool) -> None:
        if not str(vid).isdigit():
            self._fail(400, b'missing vid')
            return
        info = _hg_h5_info(vid, '720p')
        if not info:
            self._fail(502, b'play info failed')
            return
        if kind == 'v':
            url = _dump(info.get('main_url'))
        else:
            audio = info.get('audio') if isinstance(info.get('audio'), dict) else {}
            url = _dump(audio.get('main_url'))
        if not url.startswith('http'):
            self._fail(502, b'no stream url')
            return
        req_headers = {'User-Agent': DB_SEARCH_UA, 'Referer': 'https://hongguoduanju.com/'}
        rng = self.headers.get('Range')
        if rng:
            req_headers['Range'] = rng
        try:
            upstream = requests.get(url, headers=req_headers, stream=True, timeout=20)
        except Exception:
            self._fail(502, b'upstream failed')
            return
        self.send_response(upstream.status_code)
        for name in ('Content-Type', 'Content-Length', 'Content-Range', 'Accept-Ranges'):
            value = upstream.headers.get(name)
            if value:
                self.send_header(name, value)
        self.send_header('Connection', 'close')
        self.end_headers()
        if not body:
            upstream.close()
            return
        try:
            for chunk in upstream.iter_content(65536):
                if chunk:
                    self.wfile.write(chunk)
        except OSError:
            pass
        finally:
            upstream.close()

    def _serve(self, body: bool) -> None:
        route = urlparse(self.path).path
        if route.startswith('/hg_dm'):
            self._serve_danmaku(body)
            return
        if route.startswith('/hg_dash_v/') or route.startswith('/hg_dash_a/'):
            vid = route.rstrip('/').rsplit('/', 1)[-1]
            self._serve_dash(vid, 'v' if '/hg_dash_v/' in route else 'a', body)
            return
        if route.endswith('.mpd'):
            parsed = urlparse(self.path)
            vid = (parse_qs(parsed.query).get('vid') or [''])[0]
            q = (parse_qs(parsed.query).get('q') or ['720p'])[0]
            if not str(vid).isdigit():
                self._fail(400, b'missing vid')
                return
            data = _hg_h5_mpd(vid, q)
            if not data:
                self._fail(502, b'mpd build failed')
                return
            self.send_response(200)
            self.send_header('Content-Type', 'application/dash+xml; charset=utf-8')
            self.send_header('Content-Length', str(len(data)))
            self.send_header('Connection', 'close')
            self.end_headers()
            if body:
                try:
                    self.wfile.write(data)
                except OSError:
                    pass
            return
        if not route.endswith('.mp4'):
            self._fail(404, b'not found')
            return
        params = self._params()
        if not params['vid']:
            self._fail(400, b'missing vid')
            return
        try:
            session = HG2_stream_session(params['vid'], {'device_id': params['device_id'], 'install_id': params['install_id']}, params['quality'])
        except Exception:
            self._fail(502, b'media session failed')
            return
        raw_range = self.headers.get('Range') or ''
        requested = HG2_parse_range(raw_range, session.total)
        if requested is HG2_RANGE_UNSATISFIABLE:
            self.send_response(416)
            self.send_header('Content-Type', 'text/plain; charset=utf-8')
            self.send_header('Content-Range', 'bytes */%d' % session.total)
            self.send_header('Content-Length', '0')
            self.send_header('Connection', 'close')
            self.end_headers()
            return
        start, end = requested if requested else (0, session.total - 1)
        self.send_response(206 if requested else 200)
        self.send_header('Content-Type', 'video/mp4')
        self.send_header('Accept-Ranges', 'bytes')
        self.send_header('Content-Length', str(end - start + 1))
        if requested:
            self.send_header('Content-Range', 'bytes %d-%d/%d' % (start, end, session.total))
        self.end_headers()
        if not body:
            return
        try:
            for block in session.iter_range(start, end):
                self.wfile.write(block)
        except (BrokenPipeError, ConnectionResetError):
            self.close_connection = True
        except Exception:
            self.close_connection = True

def HG2_start_stream_server() -> int:
    with HG2_STREAM_LOCK:
        if HG2_STREAM_STATE['port']:
            return int(HG2_STREAM_STATE['port'])
        for port in range(HG2_STREAM_PORT_RANGE[0], HG2_STREAM_PORT_RANGE[1]):
            try:
                server = ThreadingHTTPServer(('127.0.0.1', port), HG2_StreamHandler)
            except OSError:
                continue
            server.daemon_threads = True
            threading.Thread(target=server.serve_forever, daemon=True).start()
            HG2_STREAM_STATE['port'] = port
            HG2_STREAM_STATE['server'] = server
            return port
    return 0

def HG2_b64(value: str) -> bytes:
    text = HG2_text(value)
    text += '=' * (-len(text) % 4)
    try:
        return base64.b64decode(text)
    except (ValueError, binascii.Error):
        return base64.urlsafe_b64decode(text)

def HG2_device_config(config: Mapping[str, Any]) -> dict[str, str]:
    device_id = HG2_text(config.get('device_id'))
    install_id = HG2_text(config.get('install_id'))
    if not device_id or not install_id:
        raise HG2_HongguoPluginError('缺少红果 device_id/install_id 配置')
    return {'device_id': device_id, 'iid': install_id, 'install_id': install_id, 'device_brand': 'Redmi', 'device_model': '25053RT47C', 'device_type': '25053RT47C', 'device_manufacturer': 'Xiaomi', 'os_version': '16', 'version_name': '7.1.3.32', 'x_tt_dt': HG2_text(config.get('x_tt_dt')), 'sec_device_token': HG2_text(config.get('sec_device_token')), 'device_sec_device_token': HG2_text(config.get('device_sec_device_token')), 'ua': HG2_APP_UA}

def HG2_video_model_rotating(video_id: str, config: Mapping[str, Any]) -> dict[str, Any]:
    """红果空包是按时间段成波出现的，不是某个 vid 坏了。
    实测只重试 2 轮经常全空，这里改成 5 轮：每轮两个 host 交替、
    失败就换一台新设备号，退避 0.2~0.6 秒，尽量在 3 秒级抓住空包间隙。"""
    last_err = None
    _deadline = time.time() + 9.0
    for attempt in range(5):
        if time.time() > _deadline:
            break
        try:
            return HG2_video_model(video_id, config, host_first=attempt % 2)
        except Exception as err:
            last_err = err
            if not HG2_is_empty_model_error(err) and not isinstance(
                    err, (requests.ConnectionError, requests.Timeout)):
                # 签名/端点类错误也继续换组合，不要在第一轮就放弃
                pass
        try:
            time.sleep(min(0.2 * (attempt + 1), 0.6))
        except Exception:
            pass
        pair = HG2_rotate_stream_device()
        try:
            config['device_id'] = pair['device_id']
            config['install_id'] = pair['install_id']
        except (TypeError, AttributeError):
            config = dict(pair)
    raise last_err if last_err is not None else HG2_HongguoPluginError('video_model 为空')

def HG2_stream_session(video_id: str, config: Mapping[str, Any], quality: str='1080') -> '_StreamSession':
    quality = quality if quality in HG2_QUALITY_LINE_NAME_TO_Q else '1080'
    cache_key = '%s|%s' % (video_id, quality)
    with HG2_STREAM_LOCK:
        sessions = HG2_STREAM_STATE['sessions']
        for key in [key for key, item in sessions.items() if item.expired()]:
            sessions.pop(key, None)
        session = sessions.get(cache_key)
    if session is not None:
        return session
    with HG2_STREAM_LOCK:
        inflight = HG2_STREAM_STATE.setdefault('inflight', {})
        event = inflight.get(cache_key)
        leader = event is None
        if leader:
            event = threading.Event()
            inflight[cache_key] = event
    if not leader:
        event.wait(HG2_STREAM_INFLIGHT_WAIT)
        with HG2_STREAM_LOCK:
            session = HG2_STREAM_STATE['sessions'].get(cache_key)
        if session is not None:
            return session
    last_err = None
    try:
        for _attempt in range(3):
            try:
                model = HG2_video_model_rotating(video_id, config)
                rows = HG2_video_list_from_model(model)
                key_seed = HG2_key_seed_from_model(model) or ''
                wanted_order = [quality] + [q for q in HG2_QUALITY_ORDER if q != quality]
                seen_urls = set()
                reason = '媒体会话创建失败'
                probed = 0
                for want in wanted_order:
                    _, item = HG2_select_quality(rows, want)
                    raw_url = HG2_media_url(item)
                    spade = HG2_spade_value(item)
                    if not raw_url or not spade:
                        reason = reason if reason != '媒体会话创建失败' else '播放模型缺少地址或密钥材料 q=%s' % want
                        continue
                    if raw_url in seen_urls:
                        continue
                    seen_urls.add(raw_url)
                    url = raw_url
                    if key_seed:
                        try:
                            url = HG2_decrypt_spade_url(raw_url, key_seed) or raw_url
                        except HG2_HongguoPluginError:
                            url = raw_url
                    total, moov_start, moov = HG2_fetch_moov(url)
                    if HG2_moov_has_video_track(moov):
                        session = HG2_StreamSession(url, HG2_derive_content_key(spade), total, moov_start, moov)
                        with HG2_STREAM_LOCK:
                            sessions = HG2_STREAM_STATE['sessions']
                            while len(sessions) >= HG2_STREAM_MAX_SESSIONS:
                                sessions.pop(next(iter(sessions)), None)
                            sessions[cache_key] = session
                        return session
                    reason = '该清晰度没有视轨 q=%s' % want
                    probed += 1
                    if probed >= 2:
                        break
                raise HG2_HongguoPluginError(reason)
            except Exception as err:
                last_err = err
                try:
                    time.sleep(0.4 * (_attempt + 1))
                except Exception:
                    pass
        if last_err is not None:
            raise last_err
        raise HG2_HongguoPluginError('媒体会话创建失败')
    finally:
        if leader:
            with HG2_STREAM_LOCK:
                HG2_STREAM_STATE.get('inflight', {}).pop(cache_key, None)
            event.set()
HG2_RANGE_UNSATISFIABLE = 'unsatisfiable'

def HG2_parse_range(value: str, total: int) -> Any:
    """解析 Range 头。返回 (start, end)、None（忽略）或 _RANGE_UNSATISFIABLE。"""
    text = (value or '').strip().lower()
    if not text.startswith('bytes='):
        return None
    spec = text[6:].split(',')[0].strip()
    if '-' not in spec:
        return None
    left, right = spec.split('-', 1)
    if not left:
        if not right.isdigit():
            return None
        length = min(int(right), total)
        if not length:
            return HG2_RANGE_UNSATISFIABLE
        return (total - length, total - 1)
    if not left.isdigit():
        return None
    start = int(left)
    end = int(right) if right.isdigit() else total - 1
    end = min(end, total - 1)
    if start >= total or start > end:
        return HG2_RANGE_UNSATISFIABLE
    return (start, end)

class HG2_StreamHandler(BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'
    server_version = 'hg-stream'

    def log_message(self, *args: Any) -> None:
        return None

    def _params(self) -> dict[str, str]:
        parsed = urlparse(self.path)
        query = parse_qs(parsed.query)
        video_id = (query.get('vid') or query.get('id') or [''])[0]
        if not video_id:
            video_id = parsed.path.rsplit('/', 1)[-1].split('.')[0]
        return {'vid': video_id if video_id.isdigit() else '', 'quality': (query.get('q') or ['1080'])[0], 'device_id': (query.get('did') or [''])[0], 'install_id': (query.get('iid') or [''])[0]}

    def _fail(self, code: int, message: bytes) -> None:
        self.send_response(code)
        self.send_header('Content-Type', 'text/plain; charset=utf-8')
        self.send_header('Content-Length', str(len(message)))
        self.send_header('Connection', 'close')
        self.end_headers()
        try:
            self.wfile.write(message)
        except OSError:
            pass

    def do_HEAD(self) -> None:
        self._serve(body=False)

    def do_GET(self) -> None:
        self._serve(body=True)

    def _serve_danmaku(self, body: bool) -> None:
        """本机弹幕路由：/hg_dm?vid=..&sid=..&fmt=xml|json，/hg_dm_debug 自检。"""
        parsed = urlparse(self.path)
        query = parse_qs(parsed.query)
        vid = (query.get('vid') or query.get('id') or [''])[0]
        sid = (query.get('sid') or [''])[0]
        fmt = ((query.get('fmt') or ['xml'])[0] or 'xml').lower()
        did = (query.get('did') or [''])[0]
        iid = (query.get('iid') or [''])[0]
        if not str(vid).isdigit():
            self._fail(400, b'missing vid')
            return
        if not sid:
            sid = HG2_dm_series_of(vid)
        try:
            HG2_DM_HIT[vid] = time.time()
        except Exception:
            pass
        state = HG2_dm_get(vid, sid, did, iid, wait=HG2_DM_WAIT)
        items = state.get('items') or []
        if parsed.path.rstrip('/').endswith('debug'):
            payload = {'vid': vid, 'sid': sid, 'count': len(items), 'error': state.get('error') or '', 'ts': state.get('t') or 0, 'head': items[:3]}
            data = json.dumps(payload, ensure_ascii=False).encode('utf-8')
            ctype = 'application/json; charset=utf-8'
        elif fmt == 'json':
            data = HG2_dm_to_json(items)
            ctype = 'application/json; charset=utf-8'
        else:
            data = HG2_dm_to_xml(vid, items)
            ctype = 'application/xml; charset=utf-8'
        self.send_response(200)
        self.send_header('Content-Type', ctype)
        self.send_header('Content-Length', str(len(data)))
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Connection', 'close')
        self.end_headers()
        if not body:
            return
        try:
            self.wfile.write(data)
        except OSError:
            pass

    def _serve_dash(self, vid: str, kind: str, body: bool) -> None:
        if not str(vid).isdigit():
            self._fail(400, b'missing vid')
            return
        info = _hg_h5_info(vid, '720p')
        if not info:
            self._fail(502, b'play info failed')
            return
        if kind == 'v':
            url = _dump(info.get('main_url'))
        else:
            audio = info.get('audio') if isinstance(info.get('audio'), dict) else {}
            url = _dump(audio.get('main_url'))
        if not url.startswith('http'):
            self._fail(502, b'no stream url')
            return
        req_headers = {'User-Agent': DB_SEARCH_UA, 'Referer': 'https://hongguoduanju.com/'}
        rng = self.headers.get('Range')
        if rng:
            req_headers['Range'] = rng
        try:
            upstream = requests.get(url, headers=req_headers, stream=True, timeout=20)
        except Exception:
            self._fail(502, b'upstream failed')
            return
        self.send_response(upstream.status_code)
        for name in ('Content-Type', 'Content-Length', 'Content-Range', 'Accept-Ranges'):
            value = upstream.headers.get(name)
            if value:
                self.send_header(name, value)
        self.send_header('Connection', 'close')
        self.end_headers()
        if not body:
            upstream.close()
            return
        try:
            for chunk in upstream.iter_content(65536):
                if chunk:
                    self.wfile.write(chunk)
        except OSError:
            pass
        finally:
            upstream.close()

    def _serve(self, body: bool) -> None:
        route = urlparse(self.path).path
        if route.startswith('/hg_dm'):
            self._serve_danmaku(body)
            return
        if route.startswith('/hg_dash_v/') or route.startswith('/hg_dash_a/'):
            vid = route.rstrip('/').rsplit('/', 1)[-1]
            self._serve_dash(vid, 'v' if '/hg_dash_v/' in route else 'a', body)
            return
        if route.endswith('.mpd'):
            parsed = urlparse(self.path)
            vid = (parse_qs(parsed.query).get('vid') or [''])[0]
            q = (parse_qs(parsed.query).get('q') or ['720p'])[0]
            if not str(vid).isdigit():
                self._fail(400, b'missing vid')
                return
            data = _hg_h5_mpd(vid, q)
            if not data:
                self._fail(502, b'mpd build failed')
                return
            self.send_response(200)
            self.send_header('Content-Type', 'application/dash+xml; charset=utf-8')
            self.send_header('Content-Length', str(len(data)))
            self.send_header('Connection', 'close')
            self.end_headers()
            if body:
                try:
                    self.wfile.write(data)
                except OSError:
                    pass
            return
        if not route.endswith('.mp4'):
            self._fail(404, b'not found')
            return
        params = self._params()
        if not params['vid']:
            self._fail(400, b'missing vid')
            return
        try:
            session = HG2_stream_session(params['vid'], {'device_id': params['device_id'], 'install_id': params['install_id']}, params['quality'])
        except Exception:
            self._fail(502, b'media session failed')
            return
        raw_range = self.headers.get('Range') or ''
        requested = HG2_parse_range(raw_range, session.total)
        if requested is HG2_RANGE_UNSATISFIABLE:
            self.send_response(416)
            self.send_header('Content-Type', 'text/plain; charset=utf-8')
            self.send_header('Content-Range', 'bytes */%d' % session.total)
            self.send_header('Content-Length', '0')
            self.send_header('Connection', 'close')
            self.end_headers()
            return
        start, end = requested if requested else (0, session.total - 1)
        self.send_response(206 if requested else 200)
        self.send_header('Content-Type', 'video/mp4')
        self.send_header('Accept-Ranges', 'bytes')
        self.send_header('Content-Length', str(end - start + 1))
        if requested:
            self.send_header('Content-Range', 'bytes %d-%d/%d' % (start, end, session.total))
        self.end_headers()
        if not body:
            return
        try:
            for block in session.iter_range(start, end):
                self.wfile.write(block)
        except (BrokenPipeError, ConnectionResetError):
            self.close_connection = True
        except Exception:
            self.close_connection = True

def HG2_start_stream_server() -> int:
    with HG2_STREAM_LOCK:
        if HG2_STREAM_STATE['port']:
            return int(HG2_STREAM_STATE['port'])
        for port in range(HG2_STREAM_PORT_RANGE[0], HG2_STREAM_PORT_RANGE[1]):
            try:
                server = ThreadingHTTPServer(('127.0.0.1', port), HG2_StreamHandler)
            except OSError:
                continue
            server.daemon_threads = True
            threading.Thread(target=server.serve_forever, daemon=True).start()
            HG2_STREAM_STATE['port'] = port
            HG2_STREAM_STATE['server'] = server
            return port
    return 0

def HG2_b64(value: str) -> bytes:
    text = HG2_text(value)
    text += '=' * (-len(text) % 4)
    try:
        return base64.b64decode(text)
    except (ValueError, binascii.Error):
        return base64.urlsafe_b64decode(text)

def HG2_device_config(config: Mapping[str, Any]) -> dict[str, str]:
    device_id = HG2_text(config.get('device_id'))
    install_id = HG2_text(config.get('install_id'))
    if not device_id or not install_id:
        raise HG2_HongguoPluginError('缺少红果 device_id/install_id 配置')
    return {'device_id': device_id, 'iid': install_id, 'install_id': install_id, 'device_brand': 'Redmi', 'device_model': '25053RT47C', 'device_type': '25053RT47C', 'device_manufacturer': 'Xiaomi', 'os_version': '16', 'version_name': '7.1.3.32', 'x_tt_dt': HG2_text(config.get('x_tt_dt')), 'sec_device_token': HG2_text(config.get('sec_device_token')), 'device_sec_device_token': HG2_text(config.get('device_sec_device_token')), 'ua': HG2_APP_UA}

def HG2_video_model(video_id: str, config: Mapping[str, Any], host_first: int=0, skip_multi: bool=False, deadline: float=None) -> dict[str, Any]:
    devices = HG2_device_config(config)
    params = {'iid': devices['install_id'], 'device_id': devices['device_id'], 'ac': 'wifi', 'channel': 'update_64', 'aid': '8662', 'app_name': 'novelread', 'version_code': '71332', 'version_name': '7.1.3.32', 'device_platform': 'android', 'os': 'android', 'ssmix': 'a', 'device_type': '25053RT47C', 'device_brand': 'Redmi', 'language': 'zh', 'os_api': '36', 'os_version': '16', 'manifest_version_code': '71332', 'resolution': '1280*2772', 'dpi': '520', 'update_version_code': '71332', 'host_abi': 'arm64-v8a', 'dragon_device_type': 'phone', 'pv_player': '71332', 'compliance_status': '0', 'need_personal_recommend': '1', 'player_so_load': '1', 'is_android_pad_screen': '0'}
    payload = {'biz_param': {'detail_page_version': 0, 'device_level': 3, 'disable_digg_stat': False, 'need_all_video_definition': True, 'need_mp4_align': False, 'use_os_player': False, 'use_server_dns': False, 'video_platform': 1024}, 'mixed_video_id_map': {'1004': [video_id]}}
    body = json.dumps(payload, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    response_data = None
    last_error = None
    # 2026-11 现行接口是 video_model/v1/（顶层 video_id）；multi_video_model/v1/
    # 已停服，固定回 200 空正文。先打现行接口，拿不到再退回旧的 multi。
    single_payload = {'biz_param': payload['biz_param'], 'video_id': video_id}
    single_body = json.dumps(single_payload, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    single_query = '&'.join('%s=%s' % (k, v) for k, v in params.items())
    _hosts = ('api5-normal-sinfonlineb.fqnovel.com', 'api5-normal-lf.fqnovel.com')
    if host_first % 2:
        _hosts = (_hosts[1], _hosts[0])
    for host in _hosts:
        if deadline and time.time() > deadline:
            raise HG2_HongguoPluginError('video_model 为空')
        _to = max(2, min(8, deadline - time.time())) if deadline else 8
        try:
            request_headers = {
                'User-Agent': HG2_APP_UA,
                'Accept': 'application/json; charset=utf-8,application/x-protobuf',
                'Content-Type': 'application/json', 'x-xs-from-web': '0', 'sdk-version': '2'}
            request_headers.update(HG2_dm_sign_headers(
                single_query, single_body, devices['device_id'], devices['install_id']))
            # 2026-11-16 实测：只发 ladon/argus 会回 200 空体，同一 khronos 下再补 x-medusa。
            try:
                _medusa_ts = int(request_headers.get('x-khronos') or time.time())
                _medusa = _gen_medusa(
                    'https://%s/novel/player/video_model/v1/' % host,
                    params, devices, single_payload, _medusa_ts, 'application/json')
                if _medusa:
                    request_headers['x-medusa'] = _medusa
            except Exception:
                pass
            response = requests.post(
                'https://%s/novel/player/video_model/v1/?%s' % (host, single_query),
                headers=request_headers, data=single_body, timeout=_to)
            response_data = HG2_json_response(response)
            if response_data is not None:
                break
        except Exception as exc:
            last_error = exc
            response_data = None
    if response_data is None:
        if skip_multi:
            raise HG2_HongguoPluginError('video_model 为空')
        response_data = None
        for host in HG2_VIDEO_HOSTS:
            # 2026-11-17 实测：multi_video_model 只认「ladon/argus + x-medusa」，
            # 且 query 必须和 single 用同一套 params；旧版这里换成了 dragon UA + 另一套
            # query 且不补 medusa，正是 200 空包的根因。
            query = single_query
            request_headers = {
                'User-Agent': HG2_APP_UA,
                'Accept': 'application/json; charset=utf-8,application/x-protobuf',
                'Content-Type': 'application/json', 'x-xs-from-web': '0', 'sdk-version': '2'}
            request_headers.update(HG2_dm_sign_headers(
                query, body, devices['device_id'], devices['install_id']))
            try:
                _medusa_ts = int(request_headers.get('x-khronos') or time.time())
                _medusa = _gen_medusa(
                    'https://%s/novel/player/multi_video_model/v1/' % host,
                    params, devices, payload, _medusa_ts, 'application/json')
                if _medusa:
                    request_headers['x-medusa'] = _medusa
            except Exception:
                pass
            signed_url = 'https://%s/novel/player/multi_video_model/v1/?%s' % (host, query)
            try:
                try:
                    response = requests.post(signed_url, headers=request_headers, data=body, timeout=_to)
                except requests.exceptions.SSLError:
                    response = requests.post(signed_url, headers=request_headers, data=body, timeout=_to, verify=False)
                response_data = HG2_json_response(response)
                if response_data is not None:
                    break
            except Exception as exc:
                last_error = exc
                response_data = None
    if response_data is None:
        raise HG2_HongguoPluginError(str(last_error) if last_error else '播放接口无响应')
    data = response_data.get('data') or {}
    if not isinstance(data, Mapping):
        raise HG2_HongguoPluginError('video_model 数据为空')
    entry: Any = data.get(video_id)
    if entry is None:
        for value in data.values():
            if isinstance(value, Mapping):
                entry = value
                break
            if isinstance(value, list) and value and isinstance(value[0], Mapping):
                entry = value[0]
                break
    if not isinstance(entry, Mapping):
        entry = data
    raw_model = entry.get('video_model') if isinstance(entry, Mapping) else None
    if raw_model is None:
        raw_model = data.get('video_model')
    if isinstance(raw_model, str):
        try:
            raw_model = json.loads(raw_model)
        except ValueError as exc:
            raise HG2_HongguoPluginError('video_model JSON 无效') from exc
    if not isinstance(raw_model, Mapping):
        raise HG2_HongguoPluginError('video_model 为空')
    return dict(raw_model)

def HG2_video_list_from_model(model: Mapping[str, Any]) -> Any:
    for key in ('video_list', 'dynamic_video_list'):
        if model.get(key) is not None:
            return model[key]
    dynamic = model.get('dynamic_video')
    if isinstance(dynamic, Mapping):
        for key in ('dynamic_video_list', 'video_list', 'list'):
            if dynamic.get(key) is not None:
                return dynamic[key]
    video_info = model.get('video_info')
    if isinstance(video_info, Mapping):
        data = video_info.get('data')
        if isinstance(data, Mapping):
            return HG2_video_list_from_model(data)
    data = model.get('data')
    if isinstance(data, Mapping):
        return HG2_video_list_from_model(data)
    return None
HG2_QUALITY_ORDER = ('2160', '1440', '1080', '720', '576', '540', '480', '360')

def HG2_int(value: Any) -> int:
    match = re.search('\\d+', HG2_text(value))
    return int(match.group()) if match else 0

def HG2_quality(value: Any) -> str:
    text = HG2_text(value).lower()
    match = re.search('(2160|1440|1080|720|576|540|480|360)', text)
    return match.group(1) if match else '1080'

def HG2_quality_hint(value: Any) -> str:
    """同 _quality，但识别不出时返回空串。
    不能一律兜底 '1080'：否则所有未标注清晰度的条目会合并到同一个 key 并互相覆盖，
    最终只剩最后一条，导致切任何清晰度拿到的都是同一条（甚至是没有视轨的那条）。"""
    text = HG2_text(value).lower()
    match = re.search('(2160|1440|1080|720|576|540|480|360)', text)
    return match.group(1) if match else ''

def HG2_definition_of(item: Mapping[str, Any]) -> str:
    """从一条播放模型条目里提取清晰度，尽量覆盖上游各种字段命名。"""
    if not isinstance(item, Mapping):
        return ''
    meta = item.get('video_meta')
    if not isinstance(meta, Mapping):
        meta = {}
    for value in (item.get('definition'), item.get('definition_code'), item.get('video_definition'), item.get('definition_type'), item.get('vheight'), item.get('height'), item.get('quality'), item.get('gear_name'), item.get('quality_name'), item.get('p'), meta.get('definition'), meta.get('vheight'), meta.get('height'), meta.get('quality')):
        hint = HG2_quality_hint(value)
        if hint:
            return hint
    return ''

def HG2_select_quality(video_list: Any, wanted: str='1080') -> tuple[str, dict[str, Any]]:

    def rows_from(value: Any, hinted_quality: str='') -> list[tuple[str, dict[str, Any]]]:
        if isinstance(value, list):
            result: list[tuple[str, dict[str, Any]]] = []
            for item in value:
                result.extend(rows_from(item, hinted_quality))
            return result
        if not isinstance(value, Mapping):
            return []
        if any((key in value for key in ('main_url', 'backup_url', 'backup_url_1', 'play_addr', 'spade_a', 'encrypt_info'))):
            return [(hinted_quality, dict(value))]
        result = []
        for key, item in value.items():
            if key in {'dynamic_video', 'video_info', 'data'} and isinstance(item, Mapping):
                result.extend(rows_from(item, hinted_quality))
                continue
            if key in {'video_list', 'dynamic_video_list', 'list'}:
                result.extend(rows_from(item, HG2_quality_hint(key)))
                continue
            if isinstance(item, (Mapping, list)):
                result.extend(rows_from(item, HG2_quality_hint(key)))
        return result
    candidates = rows_from(video_list)
    rows: dict[str, dict[str, Any]] = {}
    for index, (hinted_quality, item) in enumerate(candidates):
        definition = HG2_definition_of(item) or HG2_quality_hint(hinted_quality) or 'idx%d' % index
        if definition not in rows:
            rows[definition] = item
    if not rows:
        raise HG2_HongguoPluginError('播放模型没有清晰度')
    requested = HG2_quality(wanted)
    order = [requested] + [item for item in HG2_QUALITY_ORDER if item != requested]
    for definition in order:
        if definition in rows:
            return (definition, rows[definition])

    def _rank(key: str) -> int:
        item = rows[key]
        bitrate = HG2_int(item.get('bitrate') or item.get('bit_rate') or 0)
        size = HG2_int(item.get('size') or item.get('duration_ms') or 0)
        return bitrate * 1000000 + size
    definition = max(rows, key=_rank)
    return (definition, rows[definition])

def HG2_decrypt_spade_url(value: str, key_seed: bytes) -> str:
    raw = HG2_b64(value)
    if len(raw) < 20 or raw[0] != 168 or raw[2:4] != b'\x01\x00':
        raise HG2_HongguoPluginError('spade URL 头无效')
    cipher_data = raw[4:len(raw) - (len(raw) - 4) % 16]
    if not cipher_data:
        raise HG2_HongguoPluginError('spade URL 密文为空')
    constants = bytes.fromhex('4dd4c2e6b83162090e52b3c7a6733ba41cb2462b829ab58a196b39db57177524f49baf7f08e8d68d26a72e37c1a95a2f1f05a51892aef2949732b62a38aadd58')
    first = hashlib.sha512(key_seed).digest()
    second = hashlib.sha512(first + constants).digest()
    plaintext = HG2_aes_cbc_decrypt(second[:16], second[16:32], cipher_data)
    if plaintext:
        padding = plaintext[-1]
        if 1 <= padding <= 16 and padding <= len(plaintext):
            plaintext = plaintext[:-padding]
    return plaintext.rstrip(b'\x00').decode('utf-8', errors='replace')

def HG2_key_seed_from_model(model: Mapping[str, Any]) -> bytes:
    value = HG2_text(model.get('key_seed'))
    if value:
        return HG2_b64(value)
    for key in ('dynamic_video', 'video_info', 'data'):
        nested = model.get(key)
        if isinstance(nested, Mapping):
            result = HG2_key_seed_from_model(nested)
            if result:
                return result
    return b''
