HG2_DM_AES_IV = bytes.fromhex('ea180a0336ed352fcd24e4d50018ae54')
HG2_DM_SIMON_KEY = bytes.fromhex('fc78e0a9657a0c748ce51559903ccf03510e51d3cff232d71343e88a321c5304')
HG2_DM_M551 = bytes.fromhex('f2f7fcfff2f7fcff')
