HG2_DM_PREFIX551 = bytes.fromhex('f281')
HG2_DM_U32 = 4294967295
HG2_DM_SM3_IV = (1937774191, 1226093241, 388252375, 3666478592, 2842636476, 372324522, 3817729613, 2969243214)

def HG2_dm_rotl32(a: int, k: int) -> int:
    k &= 31
    if not k:
        return a & HG2_DM_U32
    return (a << k | a >> 32 - k) & HG2_DM_U32

def HG2_dm_sm3_cf(v: list, bl: bytes, off: int) -> list:
    w = [(bl[off + i * 4] << 24 | bl[off + i * 4 + 1] << 16 | bl[off + i * 4 + 2] << 8 | bl[off + i * 4 + 3]) & HG2_DM_U32 for i in range(16)]
    for j in range(16, 68):
        xj = (w[j - 16] ^ w[j - 9] ^ HG2_dm_rotl32(w[j - 3], 15)) & HG2_DM_U32
        w.append((xj ^ HG2_dm_rotl32(xj, 15) ^ HG2_dm_rotl32(xj, 23) ^ HG2_dm_rotl32(w[j - 13], 7) ^ w[j - 6]) & HG2_DM_U32)
    w1 = [(w[j] ^ w[j + 4]) & HG2_DM_U32 for j in range(64)]
    a, b, c, d, e, f, g, h = v
    for j in range(64):
        t = 2043430169 if j < 16 else 2055708042
        ss1 = HG2_dm_rotl32(HG2_dm_rotl32(a, 12) + e + HG2_dm_rotl32(t, j % 32) & HG2_DM_U32, 7)
        ss2 = ss1 ^ HG2_dm_rotl32(a, 12)
        if j < 16:
            ff = a ^ b ^ c
            gg = e ^ f ^ g
        else:
            ff = a & b | a & c | b & c
            gg = e & f | ~e & g
        tt1 = ff + d + ss2 + w1[j] & HG2_DM_U32
        tt2 = gg + h + ss1 + w[j] & HG2_DM_U32
        d, c, b, a = (c, HG2_dm_rotl32(b, 9), a, tt1)
        h, g, f, e = (g, HG2_dm_rotl32(f, 19), e, (tt2 ^ HG2_dm_rotl32(tt2, 9) ^ HG2_dm_rotl32(tt2, 17)) & HG2_DM_U32)
    return [(a ^ v[0]) & HG2_DM_U32, (b ^ v[1]) & HG2_DM_U32, (c ^ v[2]) & HG2_DM_U32, (d ^ v[3]) & HG2_DM_U32, (e ^ v[4]) & HG2_DM_U32, (f ^ v[5]) & HG2_DM_U32, (g ^ v[6]) & HG2_DM_U32, (h ^ v[7]) & HG2_DM_U32]

def HG2_dm_sm3(data: bytes) -> bytes:
    orig = len(data)
    msg = bytearray(data)
    msg.append(128)
    reserve = orig % 64 + 1
    end = 56
    if end < reserve:
        end += 64
    msg.extend(b'\x00' * (end - reserve))
    msg.extend(struct.pack('>Q', orig * 8))
    v = list(HG2_DM_SM3_IV)
    for i in range(len(msg) // 64):
        v = HG2_dm_sm3_cf(v, msg, i * 64)
    return b''.join((struct.pack('>I', x) for x in v))

def HG2_dm_sm3_prefix6(data: bytes) -> bytes:
    return HG2_dm_sm3(data)[:6]

def HG2_dm_u64le(b: bytes, off: int) -> tuple:
    lo = (b[off] | b[off + 1] << 8 | b[off + 2] << 16 | b[off + 3] << 24) & HG2_DM_U32
    hi = (b[off + 4] | b[off + 5] << 8 | b[off + 6] << 16 | b[off + 7] << 24) & HG2_DM_U32
    return (hi, lo)

def HG2_dm_u64le_write(v: tuple, out: bytearray) -> None:
    for j in range(8):
        out.append((v[1] >> 8 * j if j < 4 else v[0] >> 8 * (j - 4)) & 255)

def HG2_dm_x64(a: tuple, b: tuple) -> tuple:
    return (a[0] ^ b[0], a[1] ^ b[1])

def HG2_dm_add64(a: tuple, b: tuple) -> tuple:
    lo = a[1] + b[1]
    hi = a[0] + b[0] + (1 if lo > HG2_DM_U32 else 0)
    return (hi & HG2_DM_U32, lo & HG2_DM_U32)

def HG2_dm_not64(a: tuple) -> tuple:
    return (~a[0] & HG2_DM_U32, ~a[1] & HG2_DM_U32)

def HG2_dm_rotl64(a: tuple, n: int) -> tuple:
    n = (n % 64 + 64) % 64
    if n == 0:
        return (a[0], a[1])
    if n == 32:
        return (a[1], a[0])
    if n < 32:
        hi = (a[0] << n | a[1] >> 32 - n) & HG2_DM_U32
        lo = (a[1] << n | a[0] >> 32 - n) & HG2_DM_U32
    else:
        m = n - 32
        hi = (a[1] << m | a[0] >> 32 - m) & HG2_DM_U32
        lo = (a[0] << m | a[1] >> 32 - m) & HG2_DM_U32
    return (hi, lo)

def HG2_dm_rotr64(a: tuple, n: int) -> tuple:
    return HG2_dm_rotl64(a, (64 - n % 64) % 64)
HG2_DM_SZ_HI = 1036602426
HG2_DM_SZ_LO = 74278795

def HG2_dm_simon_zbit(k: int) -> int:
    return HG2_DM_SZ_LO >> k & 1 if k < 32 else HG2_DM_SZ_HI >> k - 32 & 1

def HG2_dm_simon_expand(k: list) -> list:
    key = list(k)
    for i in range(4, 72):
        tmp = HG2_dm_rotr64(key[i - 1], 3)
        tmp = HG2_dm_x64(tmp, key[i - 3])
        tmp = HG2_dm_x64(tmp, HG2_dm_rotr64(tmp, 1))
        key.append(HG2_dm_x64(HG2_dm_x64(HG2_dm_not64(key[i - 4]), tmp), (0, (HG2_dm_simon_zbit((i - 4) % 62) ^ 3) & HG2_DM_U32)))
    return key

def HG2_dm_simon_encrypt(pt: tuple, key: list) -> tuple:
    x, x1 = (pt[0], pt[1])
    for i in range(72):
        t = x1
        r1 = HG2_dm_rotl64(x1, 1)
        r8 = HG2_dm_rotl64(x1, 8)
        f = (r1[0] & r8[0], r1[1] & r8[1])
        x1 = HG2_dm_x64(HG2_dm_x64(x, f), HG2_dm_x64(HG2_dm_rotl64(x1, 2), key[i]))
        x = t
    return (x, x1)

def HG2_dm_aes_cbc_encrypt(key: bytes, iv: bytes, data: bytes) -> bytes:
    if not data:
        return b''
    if HG2_AES_BACKEND == 'cryptography':
        enc = HG2_Cipher(HG2_algorithms.AES(key), HG2_modes.CBC(iv)).encryptor()
        return enc.update(data) + enc.finalize()
    if HG2_AES_BACKEND == 'pycryptodome':
        return HG2_CryptoAES.new(key, HG2_CryptoAES.MODE_CBC, iv).encrypt(data)
    if len(data) % 16:
        data = data[:len(data) - len(data) % 16]
    aes = HG2_PureAES128(key)
    prev = iv[:16].ljust(16, b'\x00')
    out = bytearray()
    for i in range(0, len(data), 16):
        block = bytes((a ^ b for a, b in zip(data[i:i + 16], prev)))
        enc = aes.encrypt_block(block)
        out.extend(enc)
        prev = enc
    return bytes(out)

def HG2_dm_pkcs7(data: bytes) -> bytes:
    n = 16 - len(data) % 16
    return data + bytes([n]) * n

class HG2_DmPbuf:
    """最小的 protobuf 编码器：字段顺序即写入顺序（与 JS 版 Pbuf 一致）。"""

    def __init__(self) -> None:
        self._fields: list = []
        self._blobs: list = []

    def v(self, idx: int, val: int) -> '_DmPbuf':
        self._fields.append((idx, 0, int(val), 0))
        return self

    def _blob(self, idx: int, data: bytes) -> '_DmPbuf':
        self._blobs.append(data)
        self._fields.append((idx, 2, 0, len(self._blobs) - 1))
        return self

    def s(self, idx: int, text: Any) -> '_DmPbuf':
        return self._blob(idx, str(text).encode('utf-8'))

    def raw(self, idx: int, data: bytes) -> '_DmPbuf':
        return self._blob(idx, data)

    def pb(self, idx: int, sub: '_DmPbuf') -> '_DmPbuf':
        return self._blob(idx, sub.to_buf())

    def to_buf(self) -> bytes:
        out = bytearray()
        for idx, kind, val, ref in self._fields:
            HG2_dm_varint(out, idx * 8 + (kind & 7))
            if kind == 0:
                HG2_dm_varint(out, val)
            else:
                blob = self._blobs[ref]
                HG2_dm_varint(out, len(blob))
                out.extend(blob)
        return bytes(out)

def HG2_dm_varint(out: bytearray, value: int) -> None:
    value &= 18446744073709551615
    while value >= 128:
        out.append(value % 128 | 128)
        value //= 128
    out.append(value % 128)

def HG2_dm_simon_padded(pb: bytes) -> bytes:
    key = HG2_dm_simon_expand([HG2_dm_u64le(HG2_DM_SIMON_KEY, 0), HG2_dm_u64le(HG2_DM_SIMON_KEY, 8), HG2_dm_u64le(HG2_DM_SIMON_KEY, 16), HG2_dm_u64le(HG2_DM_SIMON_KEY, 24)])
    out = bytearray()
    for i in range(len(pb) // 16):
        off = i * 16
        ct = HG2_dm_simon_encrypt((HG2_dm_u64le(pb, off), HG2_dm_u64le(pb, off + 8)), key)
        HG2_dm_u64le_write(ct[0], out)
        HG2_dm_u64le_write(ct[1], out)
    return bytes(out)

def HG2_dm_argus_encrypt(bean: '_DmPbuf') -> str:
    pb = HG2_dm_pkcs7(bean.to_buf())
    un = HG2_DM_M551 + HG2_dm_simon_padded(pb) + HG2_DM_TAIL551
    buf = bytearray(un[:8])
    for i in range(8, len(un)):
        buf.append((un[i] ^ HG2_DM_M551[i % 8]) & 255)
    buf.reverse()
    body = HG2_dm_pkcs7(bytes(buf) + b'ao')
    return base64.b64encode(HG2_DM_PREFIX551 + HG2_dm_aes_cbc_encrypt(HG2_DM_AES_KEY, HG2_DM_AES_IV, body)).decode()

def HG2_dm_query_param(query: str, name: str) -> str:
    text = str(query or '')
    if text.startswith('?'):
        text = text[1:]
    if '#' in text:
        text = text.split('#', 1)[0]
    for part in text.split('&'):
        if not part:
            continue
        key = part.split('=')
        if key[0] == name:
            return '='.join(key[1:]) if len(key) > 1 else ''
    return ''

def HG2_dm_argus_sign(query: str, stub_hex: str, ts: int, aid: int, license_id: int, device_id: str, install_id: str='', rand_field: int=0) -> str:
    if not rand_field:
        rand_field = random.randint(1, 2147483647)
    body_hash = HG2_dm_sm3_prefix6(bytes.fromhex(stub_hex)) if stub_hex else HG2_dm_sm3_prefix6(b'\x00' * 16)
    query_hash = HG2_dm_sm3_prefix6(query.encode('utf-8')) if query else HG2_dm_sm3_prefix6(b'\x00' * 16)
    bean = HG2_DmPbuf()
    bean.v(1, 1077940818).v(2, 2).v(3, rand_field)
    bean.s(4, aid).s(5, device_id).s(6, license_id)
    bean.s(7, HG2_dm_query_param(query, 'version_name'))
    bean.s(8, 'v04.04.05-ov-android').v(9, 134744640).raw(10, b'\x00' * 8).v(11, 0)
    bean.v(12, ts * 2)
    bean.raw(13, body_hash).raw(14, query_hash)
    bean.pb(15, HG2_DmPbuf().v(1, 1).v(2, 1).v(3, 1).v(7, 3348294860))
    bean.s(16, install_id).s(20, 'none').v(21, 738)
    bean.pb(23, HG2_DmPbuf().s(1, 'NX551J').v(2, 8196).v(4, 2162219008))
    bean.v(25, 2)
    return HG2_dm_argus_encrypt(bean)

def HG2_dm_ladon_expand(md5hex: str) -> bytearray:
    ht = bytearray(288)
    for i in range(min(32, len(md5hex))):
        ht[i] = ord(md5hex[i])

    def load(off: int) -> tuple:
        lo = (ht[off] | ht[off + 1] << 8 | ht[off + 2] << 16 | ht[off + 3] << 24) & HG2_DM_U32
        hi = (ht[off + 4] | ht[off + 5] << 8 | ht[off + 6] << 16 | ht[off + 7] << 24) & HG2_DM_U32
        return (hi, lo)
    temp = [load(0), load(8), load(16), load(24)]
    b0, b8 = (temp[0], temp[1])
    temp = [temp[2], temp[3]]
    for i in range(34):
        x9 = b0
        x8 = HG2_dm_rotr64(b8, 8)
        x8 = HG2_dm_add64(x8, x9)
        x8 = (x8[0], x8[1] ^ i)
        temp.append(x8)
        x8 = HG2_dm_x64(x8, HG2_dm_rotl64(x9, 3))
        for j in range(8):
            ht[(i + 1) * 8 + j] = (x8[1] >> 8 * j if j < 4 else x8[0] >> 8 * (j - 4)) & 255
        b0 = x8
        b8 = temp.pop(0)
    return ht

def HG2_dm_ladon_block(ht: bytearray, src: bytearray, off: int) -> bytes:
    d0 = ((src[off + 4] | src[off + 5] << 8 | src[off + 6] << 16 | src[off + 7] << 24) & HG2_DM_U32, (src[off] | src[off + 1] << 8 | src[off + 2] << 16 | src[off + 3] << 24) & HG2_DM_U32)
    d1 = ((src[off + 12] | src[off + 13] << 8 | src[off + 14] << 16 | src[off + 15] << 24) & HG2_DM_U32, (src[off + 8] | src[off + 9] << 8 | src[off + 10] << 16 | src[off + 11] << 24) & HG2_DM_U32)
    for i in range(34):
        h0 = (ht[i * 8 + 4] | ht[i * 8 + 5] << 8 | ht[i * 8 + 6] << 16 | ht[i * 8 + 7] << 24) & HG2_DM_U32
        h1 = (ht[i * 8] | ht[i * 8 + 1] << 8 | ht[i * 8 + 2] << 16 | ht[i * 8 + 3] << 24) & HG2_DM_U32
        total = HG2_dm_add64(d0, HG2_dm_rotr64(d1, 8))
        d1 = (h0 ^ total[0], h1 ^ total[1])
        d0 = HG2_dm_x64(d1, HG2_dm_rotl64(d0, 3))
    out = bytearray()
    HG2_dm_u64le_write(d0, out)
    HG2_dm_u64le_write(d1, out)
    return bytes(out)

def HG2_dm_ladon_encrypt_raw(md5hex: str, data: bytes) -> bytes:
    ht = HG2_dm_ladon_expand(md5hex)
    pad = 16 - len(data) % 16
    src = bytearray(data) + bytes([pad]) * pad
    out = bytearray()
    for i in range(len(src) // 16):
        out.extend(HG2_dm_ladon_block(ht, src, i * 16))
    return bytes(out)

def HG2_dm_ladon_encrypt(ts: int, license_id: int, aid: int, rand4: bytes) -> str:
    data = ('%d-%d-%d' % (ts, license_id, aid)).encode('utf-8')
    keygen = rand4 + str(aid).encode('utf-8')
    enc = HG2_dm_ladon_encrypt_raw(hashlib.md5(keygen).hexdigest(), data)
    return base64.b64encode(rand4 + enc).decode()

try:
    from cryptography.hazmat.primitives import hashes as _HG3_hashes
except Exception:
    _HG3_hashes = None
hashes = _HG3_hashes

