def _hg_h5_direct(vid, definition="720p"):
    """官网 H5 的 play-info 直接给未加密 MP4 直链。
    App 的 video_model 空包期间，720P 靠这条保持可播；1080 仍优先原生。"""
    vid = _dump(vid)
    sid = HG2_dm_series_of(vid)
    if not vid or not sid:
        return ""
    try:
        body = json.dumps({"series_id": sid, "item_id": vid,
                           "definition": definition}, ensure_ascii=False).encode("utf-8")
        response = requests.post(
            "https://hongguoduanju.com/api/video/protected/play-info?aid=8662",
            data=body, timeout=10,
            headers={"User-Agent": DB_SEARCH_UA,
                     "Content-Type": "application/json; charset=utf-8",
                     "Referer": "https://hongguoduanju.com/player/%s/%s" % (sid, vid)})
        if response.status_code != 200:
            return ""
        data = response.json() or {}
        info = data.get("play_info") if isinstance(data, dict) else None
        if not isinstance(info, dict):
            return ""
        url = _dump(info.get("main_url")) or _dump(info.get("backup_url"))
        return url if url.startswith("http") else ""
    except Exception:
        return ""


def _hg3_fb_url(value):
    """从 video_model 里取备用接口地址（fallback_api 可能套了多层）。"""
    if isinstance(value, str):
        return value if value.startswith("http") else ""
    if isinstance(value, dict):
        for k in ("fallback_api", "fallback_url", "url", "api"):
            u = _hg3_fb_url(value.get(k))
            if u:
                return u
        for v in value.values():
            u = _hg3_fb_url(v)
            if u:
                return u
    if isinstance(value, list):
        for v in value:
            u = _hg3_fb_url(v)
            if u:
                return u
    return ""


_HG3_QT = {"2160": "0", "1440": "2", "1080": "1", "720": "10", "540": "20", "480": "30", "360": "40"}
_HG3_EMPTY_AT = 0.0


_HG3_CACHE = {}
_HG3_WARMING = set()
_HG3_LOCK = threading.Lock()


def _hg3_cached(vid):
    with _HG3_LOCK:
        item = _HG3_CACHE.get(vid)
    if item and item[0] > time.time():
        return item[1]
    return ""


def _hg3_warm_start(vid):
    """1080P 空包是成波出现的：失败后后台每 4 秒重试，命中就缓存，下次点击直接 1080。"""
    with _HG3_LOCK:
        if vid in _HG3_WARMING:
            return
        _HG3_WARMING.add(vid)

    def _run():
        try:
            for _ in range(40):
                time.sleep(4)
                u = _hg3_plain_url(vid, "1080", force=True)
                if u:
                    with _HG3_LOCK:
                        _HG3_CACHE[vid] = (time.time() + 600, u)
                    return
        finally:
            with _HG3_LOCK:
                _HG3_WARMING.discard(vid)

    try:
        threading.Thread(target=_run, daemon=True, name="hg3-warm").start()
    except Exception:
        with _HG3_LOCK:
            _HG3_WARMING.discard(vid)


def _hg3_plain_url(vid, quality="1080", force=False):
    """红果 1080P 直链：video_model 的 fallback_api 里取 codec_type=1 的标准 hvc1/mp4。

    这部分照《红果-合并集数版》的做法：不经过 CENC 解密、不占本机代理，
    直接给播放器上游直链；上游没给 1080 就返回空，由调用方退真实 720P。
    """
    global _HG3_EMPTY_AT, _HG2_EMPTY_AT
    vid = _dump(vid)
    if not vid:
        return ""
    if not force and time.time() - _HG3_EMPTY_AT < 20:
        return ""
    cfg = _hg2_config()
    if not cfg.get("device_id") or not cfg.get("install_id"):
        return ""
    try:
        model = HG2_video_model_rotating(vid, cfg)
    except Exception:
        _HG3_EMPTY_AT = time.time()
        _HG2_EMPTY_AT = time.time()
        return ""
    api = _hg3_fb_url(model.get("fallback_api") if isinstance(model, dict) else None)
    if not api:
        _HG3_EMPTY_AT = time.time()
        _HG2_EMPTY_AT = time.time()
        return ""
    api = re.sub(r"codec_type=\d+", "codec_type=1", api)
    if "codec_type=" not in api:
        api += ("&" if "?" in api else "?") + "codec_type=1"
    payload = None
    for _ in range(2):
        try:
            r = requests.get(api, headers={"User-Agent": HG2_APP_UA}, timeout=8)
            if r.status_code == 200:
                payload = r.json()
                if isinstance(payload, dict):
                    break
        except Exception:
            payload = None
    if not isinstance(payload, dict):
        return ""
    for key in ("video_info", "data"):
        if isinstance(payload.get(key), dict):
            payload = payload[key]
    if isinstance(payload.get("data"), dict):
        payload = payload["data"]
    raw = payload.get("video_list") or {}
    items = list(raw.values()) if isinstance(raw, dict) else [x for x in raw if isinstance(x, dict)]
    want = _HG3_QT.get(str(quality), "1")
    seed = None
    # 密钥材料在备用接口回包的 video_info 里；只看外层 model 会拿不到，main_url 解不开就被判废。
    for _obj in (payload, model):
        try:
            seed = HG2_key_seed_from_model(_obj)
        except Exception:
            seed = None
        if seed:
            break
    for it in items:
        if not isinstance(it, dict):
            continue
        if str(it.get("quality_type") or "") != want:
            continue
        u = _dump(it.get("main_url"))
        if not u:
            continue
        if not u.startswith("http") and seed:
            try:
                u = HG2_decrypt_spade_url(u, seed) or u
            except Exception:
                continue
        if not u.startswith("http"):
            continue
        # 只认“标准 hvc1/avc1 + 有视轨 + 没加密”的直链，别把 CENC 壳丢给播放器。
        try:
            total, _ms, moov = HG2_fetch_moov(u)
            if not total or not moov or not HG2_moov_has_video_track(moov):
                continue
            if b"encv" in moov or b"enca" in moov:
                continue
            mid = max(total // 2, 1024)
            probe = requests.get(u, headers={"User-Agent": HG2_MEDIA_UA,
                                             "Range": "bytes=%d-%d" % (mid, mid + 1023)},
                                 timeout=8)
            if probe.status_code != 206:
                continue
        except Exception:
            continue
        return u
    return ""


def _hg2_play_url(vid, quality="1080"):
    """建红果 1080P 媒体会话并返回本机 Range 流地址；建不起来返回空串。

    做法与《红果短剧.py》一致：先在后台线程把「video_model + moov + 内容密钥」
    这一整条会话建好（冷启动几秒到十几秒），播放器连上来时直接命中缓存，
    首字节 1 秒内；建失败返回空串，由调用方退回官网 360P 直链。
    """
    vid = _dump(vid)
    if not vid:
        return ""
    cfg = _hg2_config()
    if not cfg.get("device_id") or not cfg.get("install_id"):
        return ""
    global _HG2_EMPTY_AT
    if quality == "1080" and time.time() - _HG2_EMPTY_AT < 30:
        return ""
    holder = {}

    def _warm():
        try:
            holder["session"] = HG2_stream_session(vid, cfg, quality)
        except Exception as exc:
            holder["error"] = exc

    worker = threading.Thread(target=_warm)
    worker.daemon = True
    worker.start()
    worker.join(8)
    # join 超时但会话还没建好时不能把 127.0.0.1 地址交出去，
    # 否则播放器会连到一个没有缓存的空服务，一直转圈。
    if holder.get("session") is None:
        _HG2_EMPTY_AT = time.time()
        return ""
    try:
        port = HG2_start_stream_server()
    except Exception:
        port = 0
    if not port:
        return ""
    query = urlencode({"vid": vid, "q": quality,
                       "did": cfg.get("device_id", ""),
                       "iid": cfg.get("install_id", "")})
    return "http://127.0.0.1:%d/hg.mp4?%s" % (port, query)


"""
网盘聚合.py — 17 站聚合版（结构参照 短剧聚合.py）

胶囊行 = 玩偶/木偶/快映/剧透
点胶囊切换站点看分类/海报；搜索一次搜全部站，结果角标带站名；
UC 解析共用一份；UC 播放只走无限免登匿名直链（与 jar 的 ff() 一致），123 云盘免登直链。

JSON 线路写法（配置里只挂这一条聚合线路即可）：
{
  "key": "网盘聚合",
  "name": "网盘",
  "type": 3,
  "api": "./py/网盘聚合.py",
  "searchable": 1,
  "quickSearch": 1,
  "filterable": 1,
  "changeable": 1,
  "ext": {
    "mode": "",
    "夸父cookie": "bbs_sid=xxx; bbs_token=xxx",
    "123cookie": "bbs_sid=xxx; bbs_token=xxx",
    "fast": "1",
    "accel": "1",
    "accel_thread": "96"
  }
}
说明：
- mode："" = 聚合模式；"uc" = UC免登专站；"quark" = 夸克免登专站；
  "uc,quark"（也认 "uc+quark" / "uc quark" / "pan"）= UC+夸克双模式专站。
  双模式验证语义为"或"：UC 或夸克任一能播即保留。
  夸父cookie / 123cookie 是夸父、123 两个【论坛站】的登录 cookie，与夸克网盘无关。
- fast：仅聚合模式"仅UC免登/仅夸克免登"筛选用，1=只查有无链接（快），0=逐条试播（准但慢）。
- accel：夸克游客直链被限速时走本地并发代理（1 开 0 关）；accel_thread 并发数（1-128，默认 96）。
- UC 无限免登 = jar 的 ff() 链路（pc-api/file/download 匿名直链）。
- 123 云盘分享直链免登可用。
"""

