# ---------------------------------------------------------------------------
# 配置中心 Cookie 桥接：csp_Config 会把登录 Cookie 写到 <APP files>/lzxw/ 下
# 仅 baidu.txt。这里在 ext 没填 bd_cookie 时自动读取，
# 夸克/UC 不接任何 Cookie，只走匿名免登。
# ---------------------------------------------------------------------------
def _cfg_cookie(name):
    try:
        bases = []
        here = os.path.dirname(os.path.abspath(globals().get("__file__") or "."))
        for p in (here, os.getcwd()):
            if p and p not in bases:
                bases.append(p)
        cur = here
        for _ in range(8):
            cur = os.path.dirname(cur) or cur
            if cur and cur not in bases:
                bases.append(cur)
        pkg = ""
        for key in ("ANDROID_PACKAGE_NAME", "PKG_NAME"):
            pkg = os.environ.get(key, "") or pkg
        if not pkg:
            try:
                raw = open("/proc/self/cmdline", "rb").read()
                first = raw.split(b"\x00", 1)[0].decode("utf-8", "ignore").strip()
                if "." in first and "/" not in first:
                    pkg = first
            except Exception:
                pass
        if pkg:
            for root in ("/data/user/0", "/data/data"):
                p = os.path.join(root, pkg, "files")
                if p not in bases:
                    bases.append(p)
        bases += ["/sdcard/TVBox", "/storage/emulated/0/TVBox",
                  "/sdcard/lzxw", "/storage/emulated/0/lzxw"]
        # 有些壳拿不到包名，直接扫外部私有目录里的配置
        try:
            for pat in ("/sdcard/Android/data/*/files/lzxw/" + name,
                        "/storage/emulated/0/Android/data/*/files/lzxw/" + name):
                bases += [x for x in glob.glob(pat) if os.path.isfile(x)]
        except Exception:
            pass
        if pkg:
            bases += ["/sdcard/Android/data/%s/files" % pkg,
                      "/storage/emulated/0/Android/data/%s/files" % pkg]
        seen = set()
        for base in bases:
            paths = [base] if os.path.isfile(base) else [
                os.path.join(base, sub, name) if sub else os.path.join(base, name)
                for sub in ("lzxw", "files/lzxw", "files", "")]
            for path in paths:
                path = os.path.abspath(path)
                if path in seen:
                    continue
                seen.add(path)
                try:
                    if not os.path.isfile(path):
                        continue
                    txt = open(path, "r", encoding="utf-8", errors="ignore").read().strip()
                    txt = txt.strip('"').strip("'").strip()
                    if txt:
                        return txt
                except Exception:
                    continue
    except Exception:
        pass
    return ""


def _bd_cookie_norm(raw):
    """兼容配置中心 baidu.txt 的几种写法：整段 Cookie / 只有 BDUSS / JSON。"""
    txt = unquote(_dump(raw)).strip().strip('"').strip("'").strip()
    if not txt:
        return ""
    if txt.startswith("{"):
        try:
            obj = json.loads(txt)
            if isinstance(obj, dict):
                txt = _dump(obj.get("cookie") or obj.get("bd_cookie")
                            or obj.get("BDUSS") or obj.get("bduss") or "").strip()
        except Exception:
            pass
    m = re.search(r"BDUSS=([^;\s]+)", txt, re.I)
    if m:
        out = "BDUSS=" + m.group(1).strip()
        s = re.search(r"STOKEN=([^;\s]+)", txt, re.I)
        if s:
            out += ";STOKEN=" + s.group(1).strip()
        return out
    # 配置中心只存了一串 BDUSS（没有键名）
    if len(txt) >= 80 and ";" not in txt and " " not in txt:
        return "BDUSS=" + txt
    return txt


def _cfg_xunlei():
    """配置中心迅雷扫码登录写出的 xunlei.txt。
    token_type / access_token / refresh_token / deviceid / expires_end。"""
    try:
        raw = _cfg_cookie("xunlei.txt")
        if not raw:
            return {}
        # 有些壳会把 JSON 再 URL 编码一次
        try:
            raw = unquote(raw)
        except Exception:
            pass
        obj = json.loads(raw)
        if not isinstance(obj, dict):
            return {}
        # csp_Config 实际写入的是 {"token_resp":{...}, "deviceid":"...", "username":"..."}
        tr = obj.get("token_resp")
        if not isinstance(tr, dict):
            tr = obj
        tok = _dump(tr.get("access_token") or tr.get("accessToken")
                    or obj.get("access_token") or obj.get("accessToken"))
        if not tok:
            return {}
        dev = _dump(obj.get("deviceid") or obj.get("device_id") or obj.get("deviceId")
                    or tr.get("deviceid") or tr.get("device_id"))
        try:
            end = int(tr.get("expires_end") or obj.get("expires_end") or 0)
        except Exception:
            end = 0
        # 配置中心登录取到的 expires_end 是秒；过期先交给 refresh_token 续期，
        # 没有 refresh_token 才真正判未登录。
        expired = bool(end and end + 60 < int(time.time()))
        return {"token": tok, "device": dev, "type": _dump(tr.get("token_type") or "Bearer"),
                "refresh": _dump(tr.get("refresh_token") or obj.get("refresh_token")),
                "expired": expired, "raw": obj}
    except Exception:
        return {}


