def make_session(ua=MOBILE_UA):
    s = requests.Session()
    s.headers.update({"User-Agent": ua})
    if HTTPAdapter is not None and Retry is not None:
        try:
            retry = Retry(total=1, backoff_factor=0.2, status_forcelist=[429, 500, 502, 503])
            adapter = HTTPAdapter(max_retries=retry, pool_connections=8, pool_maxsize=32)
            s.mount("https://", adapter)
            s.mount("http://", adapter)
        except Exception:
            pass
    return s


def _ensure_url(site):
    """懒探测镜像：首次用到该站时才 HEAD 探测（3s 超时），加载期零网络"""
    if site.get("_url_ok"):
        return
    ok = False
    for u in site["site"]:
        try:
            site["session"].head(u, timeout=1.5, allow_redirects=True)
            site["url"] = u
            ok = True
            break
        except Exception:
            continue
    site["_url_ok"] = True
    if not ok:
        # 全部镜像都连不上：熔断 5 分钟，之后每次加载/搜索直接跳过不再白等
        site["_dead_until"] = time.time() + 300


def http_get(session, url, timeout=8, headers=None, binary=False):
    # 玩偶不再强制 curl_cffi：设备端没有该库会直接返回空，先用普通 requests
    r = None
    _err = None
    try:
        r = session.get(url, timeout=timeout, headers=headers or {})
        r.encoding = 'utf-8'
    except Exception as e:
        _err = e
    _txt = '' if binary else ((r.text or '') if r is not None else '')
    _bad = r is None or (r.status_code in (403, 503) and _wogg_challenge(_txt)) \
        or (r.status_code == 200 and _wogg_challenge(_txt))
    if _bad:
        try:
            from curl_cffi import requests as _cf
            for _try in range(3):
                try:
                    _r2 = _cf.get(url, impersonate='chrome', timeout=max(timeout, 15),
                                  verify=False, headers=headers or {})
                    _r2.encoding = 'utf-8'
                    if _r2.status_code == 200:
                        try:
                            for _c in _r2.cookies:
                                session.cookies.set(_c.name, _c.value,
                                                    domain=_c.domain or '', path=_c.path or '/')
                        except Exception:
                            pass
                        return _r2.content if binary else _r2.text
                except Exception:
                    pass
                time.sleep(1.0)
        except Exception:
            pass
    if r is None:
        # 网络超时不让整站熔断：返回空，下一轮还能再试（玩偶 Cloudflare 会间歇 403/超时）
        return b'' if binary else ''
    return r.content if binary else _txt




# ---------------------------------------------------------------------------
# UC 网盘解析（共用一份，来自原 网盘搜索.py）
# ---------------------------------------------------------------------------
class UCDrive:
    PC_API = "https://pc-api.uc.cn/1/clouddrive"
    OPEN_API = "https://open-api-drive.uc.cn"
    SHARE_RE = re.compile(r"https?://drive\.uc\.cn/s/([0-9a-zA-Z]+)(?:\?pwd=(\w+))?")

    def __init__(self, cookie=""):
            self.cookie = cookie
            self._stoken_cache = {}
            self._machine_code = None

    # ---------- 公共 ----------
    def _headers_common(self):
            return {"Referer": "https://drive.uc.cn", "Cookie": self.cookie or "", "User-Agent": PC_UA}

    def _headers_anon(self):
            return {"User-Agent": PC_UA, "Accept-Encoding": "identity", "Referer": "https://drive.uc.cn"}

    def _post_json(self, url, body, headers=None, timeout=20):
            hdrs = {"User-Agent": PC_UA, "Content-Type": "application/json; charset=utf-8"}
            if headers:
                        hdrs.update(headers)
            resp = requests.post(url, json=body, headers=hdrs, timeout=timeout)
            resp.encoding = "utf-8"
            return resp.text

    def share_token(self, pwd_id, passcode=""):
            url = f"{self.PC_API}/share/sharepage/token?__t={int(time.time() * 1000)}"
            body = {"pwd_id": pwd_id, "passcode": passcode or ""}
            text = self._post_json(url, body, self._headers_common())
            data = json.loads(text)
            stoken = (data.get("data") or {}).get("stoken", "")
            if stoken:
                        self._stoken_cache[pwd_id] = stoken
            return data, stoken

    def _get_stoken(self, pwd_id, passcode=""):
            if pwd_id in self._stoken_cache:
                        return self._stoken_cache[pwd_id]
            _, stoken = self.share_token(pwd_id, passcode)
            return stoken

    def list_videos(self, share_url, passcode="", limit=0):
            """返回 [{'fid','file_name','size','share_fid_token','pwd_id','stoken'}]
            limit>0 时找到 limit 个视频即停（验证场景免整树遍历）"""
            m = self.SHARE_RE.search(share_url or "")
            if not m:
                        return []
            pwd_id, url_pwd = m.group(1), m.group(2)
            pc = passcode or url_pwd or ""
            try:
                        stoken = self._get_stoken(pwd_id, pc)
            except Exception:
                        return []
            if not stoken:
                        return []
            out = []
            self._walk(pwd_id, stoken, "0", out, depth=0, limit=limit)
            return out

    def _walk(self, pwd_id, stoken, pdir_fid, out, depth, limit=0):
            if depth > 12 or (limit and len(out) >= limit):
                        return
            page = 1
            while True:
                        url = (f"{self.PC_API}/share/sharepage/detail?pr=UCBrowser&fr=pc" f"&pwd_id={pwd_id}&stoken={quote(stoken)}&pdir_fid={pdir_fid}" f"&force=0&_page={page}&_size=50&_sort=file_type:asc,file_name:asc")
                        r = requests.get(url, headers=self._headers_common(), timeout=10)
                        r.encoding = "utf-8"
                        data = r.json()
                        items = (data.get("data") or {}).get("list") or []
                        if not items:
                                        break
                        for it in items:
                                        if it.get("dir"):
                                                    self._walk(pwd_id, stoken, it.get("fid", "0"), out, depth + 1, limit)
                                        elif it.get("file") and it.get("category") in (1, 2):
                                                    out.append({"fid": it.get("fid", ""),
                                                                                "file_name": it.get("file_name", "未命名"),
                                                                                "size": it.get("size", 0),
                                                                                "share_fid_token": it.get("share_fid_token", ""),
                                                                                "pwd_id": pwd_id, "stoken": stoken})
                                        if limit and len(out) >= limit:
                                                    return
                        if len(items) < 50:
                                        break
                        page += 1

    # ---------- 播放链 1：匿名直链（无限） ----------
    def download_url_anon(self, pwd_id, fid, fid_token):
            """就是 jar 的 ff()：匿名免登拿 download_url，失败返回空串"""
            try:
                        stoken = self._get_stoken(pwd_id) or ""
            except Exception:
                        stoken = ""
            body = {"fids": [fid], "fids_token": [fid_token], "pwd_id": pwd_id,
                                        "stoken": stoken, "speedup_session": ""}
            url = f"{self.PC_API}/file/download?pr=UCBrowser&fr=pc"
            text = self._post_json(url, body, self._headers_anon())
            data = json.loads(text)
            arr = data.get("data") or []
            if not arr:
                        return ""
            return arr[0].get("download_url", "") or ""

    def play_anonymous(self, pwd_id, fid, fid_token):
            """jar 的 q() 无限分支：裸直链 + f() 头，关键是 Referer = download_url + '\\'（CDN 回调鉴权认它）"""
            dl = self.download_url_anon(pwd_id, fid, fid_token)
            if not dl:
                        return {"parse": 0, "url": "", "header": self._headers_anon()}
            return {"parse": 0, "url": dl,
                                        "header": {"User-Agent": PC_UA, "Accept-Encoding": "identity", "Referer": dl + "\\"}}

    def stream_alive(self, dl, timeout=6):
            """探测 CDN 直链是否真能流出字节（Range 0-0 头探测，与播放同请求头）。
            脚本就跑在播放设备上：这里连不上/被拒，播放器一样缓冲死 → 判不可播"""
            if not dl:
                        return False
            try:
                        r = requests.get(dl, headers={"User-Agent": PC_UA, "Accept-Encoding": "identity",
                                                                                                    "Referer": dl + "\\", "Range": "bytes=0-0"},
                                                                        stream=True, timeout=timeout)
                        ok = r.status_code in (200, 206)
                        r.close()
                        return ok
            except Exception:
                        return False


# ---------------------------------------------------------------------------
class QuarkDrive:
    PC_API = "https://drive-pc.quark.cn/1/clouddrive"
    SHARE_RE = re.compile(r"https?://pan\.quark\.cn/s/([0-9a-zA-Z]+)(?:\?pwd=(\w+))?")
    # 免登直链用 pr=pc（ucpro 会被按游客限制卡 50MiB）
    DL_PR = "pc"

    def __init__(self, cookie=""):
            self.cookie = cookie
            self.session = requests.Session()
            self.session.headers.update({"User-Agent": PC_UA})
            self._stoken_cache = {}

    # ---------- 公共 ----------
    def _headers(self):
            h = {"Referer": "https://pan.quark.cn", "User-Agent": PC_UA}
            if self.cookie:
                        h["Cookie"] = self.cookie
            return h

    def cookie_header(self):
            """当前会话里的 cookie（CDN 拉流必须带）——兼容 CookieJar 与 dict 两种形态"""
            parts = []
            ck = getattr(self.session, "cookies", None)
            try:
                        if isinstance(ck, dict):
                                        parts += ["%s=%s" % (k, v) for k, v in ck.items()]
                        else:
                                        for c in ck:
                                                    parts.append("%s=%s" % (c.name, c.value))
            except Exception:
                        pass
            if self.cookie:
                        parts.append(self.cookie)
            return "; ".join(parts)

    def _post_json(self, url, body, headers=None, timeout=20):
            hdrs = {"User-Agent": PC_UA, "Content-Type": "application/json; charset=utf-8"}
            if headers:
                        hdrs.update(headers)
            resp = self.session.post(url, json=body, headers=hdrs, timeout=timeout)
            resp.encoding = "utf-8"
            return resp.text

    # ---------- 匿名：分享 token / 列目录 ----------
    def share_token(self, pwd_id, passcode=""):
            url = f"{self.PC_API}/share/sharepage/token?__t={int(time.time() * 1000)}"
            body = {"pwd_id": pwd_id, "passcode": passcode or ""}
            try:
                        text = self._post_json(url, body, self._headers())
                        data = json.loads(text)
            except Exception:
                        return {}, ""
            stoken = (data.get("data") or {}).get("stoken", "")
            if stoken:
                        self._stoken_cache[pwd_id] = stoken
            return data, stoken

    def _get_stoken(self, pwd_id, passcode=""):
            if pwd_id in self._stoken_cache:
                        return self._stoken_cache[pwd_id]
            _, stoken = self.share_token(pwd_id, passcode)
            return stoken

    def list_videos(self, share_url, passcode="", limit=0):
            """免登列出分享里的视频：[{'fid','file_name','size','share_fid_token','pwd_id','stoken'}]"""
            m = self.SHARE_RE.search(share_url or "")
            if not m:
                        return []
            pwd_id, url_pwd = m.group(1), m.group(2)
            pc = passcode or url_pwd or ""
            try:
                        stoken = self._get_stoken(pwd_id, pc)
            except Exception:
                        return []
            if not stoken:
                        return []
            out = []
            self._walk(pwd_id, stoken, "0", out, depth=0, limit=limit)
            return out

    def _walk(self, pwd_id, stoken, pdir_fid, out, depth, limit=0):
            if depth > 12 or (limit and len(out) >= limit):
                        return
            page = 1
            while True:
                        url = (f"{self.PC_API}/share/sharepage/detail?pr=ucpro&fr=pc" f"&pwd_id={pwd_id}&stoken={quote(stoken)}&pdir_fid={pdir_fid}" f"&force=0&_page={page}&_size=50&_sort=file_type:asc,file_name:asc")
                        try:
                                        r = self.session.get(url, headers=self._headers(), timeout=10)
                                        r.encoding = "utf-8"
                                        data = r.json()
                        except Exception:
                                        break
                        items = (data.get("data") or {}).get("list") or []
                        if not items:
                                        break
                        for it in items:
                                        if it.get("dir"):
                                                    self._walk(pwd_id, stoken, it.get("fid", "0"), out, depth + 1, limit)
                                        elif it.get("file") and it.get("category") in (1, 2):
                                                    out.append({"fid": it.get("fid", ""),
                                                                                "file_name": it.get("file_name", "未命名"),
                                                                                "size": it.get("size", 0),
                                                                                "share_fid_token": it.get("share_fid_token", ""),
                                                                                "pwd_id": pwd_id, "stoken": stoken})
                                        if limit and len(out) >= limit:
                                                    return
                        if len(items) < 50:
                                        break
                        page += 1

    # ---------- 播放链：匿名直链（免登） ----------
    def _warm_session(self, pwd_id, stoken):
            """匿名会话要 __sdid + __pugs 两个 cookie 才认 file/download；
            没列过目录时先列一次把会话跑热（否则 download 返回空）"""
            names = set()
            ck = getattr(self.session, "cookies", None)
            try:
                        if isinstance(ck, dict):
                                        names = set(ck.keys())
                        else:
                                        names = {c.name for c in ck}
            except Exception:
                        pass
            if "__pugs" in names:
                        return
            try:
                        self._walk(pwd_id, stoken, "0", [], depth=0, limit=1)
            except Exception:
                        pass

    def download_info(self, pwd_id, fid, fid_token):
            """匿名免登拿直链信息：{"url","size","name"}（pr=pc 绕开 50MiB 游客限制）"""
            try:
                        stoken = self._get_stoken(pwd_id) or ""
            except Exception:
                        stoken = ""
            self._warm_session(pwd_id, stoken)
            body = {"fids": [fid], "fids_token": [fid_token], "pwd_id": pwd_id, "stoken": stoken}
            url = f"{self.PC_API}/file/download?pr={self.DL_PR}&fr=pc"
            try:
                        text = self._post_json(url, body, self._headers())
                        data = json.loads(text)
            except Exception:
                        return {}
            arr = data.get("data") or []
            if not arr:
                        return {}
            it = arr[0]
            return {"url": it.get("download_url", "") or "",
                                        "size": int(it.get("size") or 0),
                                        "name": it.get("file_name", "")}

    def download_url_anon(self, pwd_id, fid, fid_token):
            """匿名免登拿 download_url（pr=pc 绕开 50MiB 游客限制）"""
            return self.download_info(pwd_id, fid, fid_token).get("url", "") or ""

    def play_anonymous(self, pwd_id, fid, fid_token):
            """裸直链 + 会话 cookie（夸克 CDN 认 cookie；不带会被 412）"""
            dl = self.download_url_anon(pwd_id, fid, fid_token)
            if not dl:
                        return {"parse": 0, "url": "", "header": self._headers()}
            h = {"User-Agent": PC_UA, "Accept-Encoding": "identity", "Referer": "https://pan.quark.cn"}
            ck = self.cookie_header()
            if ck:
                        h["Cookie"] = ck
            return {"parse": 0, "url": dl, "header": h}

    def stream_alive(self, dl, timeout=6):
            """探测 CDN 直链是否真能流出字节（Range 0-0 头探测，与播放同请求头）"""
            if not dl:
                        return False
            h = {"User-Agent": PC_UA, "Accept-Encoding": "identity",
                            "Referer": "https://pan.quark.cn", "Range": "bytes=0-0"}
            ck = self.cookie_header()
            if ck:
                        h["Cookie"] = ck
            try:
                        try:
                                        r = self.session.get(dl, headers=h, stream=True, timeout=timeout)
                        except TypeError:
                                        # 环境不支持 stream 参数时退回普通 GET（只看状态码）
                                        r = self.session.get(dl, headers=h, timeout=timeout)
                        ok = r.status_code in (200, 206)
                        try:
                                        r.close()
                        except Exception:
                                        pass
                        return ok
            except Exception:
                        return False


# ---------------------------------------------------------------------------
class LocalStreamProxy:
    _inst = None

    @classmethod
    def instance(cls):
        if cls._inst is None:
            cls._inst = cls()
        return cls._inst

    def __init__(self):
        self._srv = None
        self._port = 0
        self._items = {}
        self._seq = 0
        self._lock = threading.Lock()
        self.thread = 6         # 并发连接数（夸克 CDN 对多连接敏感，64 会被中途掐断）（夸克每连接约 0.1MB/s ⇒ 64 连接≈5.4MB/s）
        self.block = 262144     # 单连接每块的字节数（长连接上顺序 Range 请求）

    # ---------- 服务端 ----------
    def _ensure_server(self):
        if self._srv is not None:
            return True
        try:
            import http.server as _hs
            import socketserver as _ss
            outer = self

            class _Handler(_hs.BaseHTTPRequestHandler):
                # ★ 用 HTTP/1.0：HTTP/1.1 下本类既不发 Content-Encoding: chunked、
                #   又不对每个响应精确对账连接生命周期，播放器复用 keep-alive 连接时
                #   极易读到半截 / 一直等下一个 chunk，表现就是"卡不动、不出画面"。
                #   HTTP/1.0 + Connection: close 每次请求独立，最稳。
                protocol_version = "HTTP/1.0"

                def log_message(self, *a):
                    pass

                def do_HEAD(self):
                    self.do_GET()

                def do_GET(self):
                    outer._handle(self)

            class _Server(_ss.ThreadingMixIn, _hs.HTTPServer):
                daemon_threads = True
                allow_reuse_address = True

            self._srv = _Server(("127.0.0.1", 0), _Handler)
            self._port = self._srv.server_address[1]
            threading.Thread(target=self._srv.serve_forever,
                             kwargs={"poll_interval": 0.3}, daemon=True).start()
            return True
        except Exception:
            self._srv = None
            return False

    def base_url(self):
        return "http://127.0.0.1:%d" % self._port

    def register(self, url, headers=None, size=0, refresh=None):
        """refresh：可选回调 () -> (new_url, new_headers)；夸克匿名会话 cookie 会过期（CDN 412），
        拉块失败时靠它换一条新直链续命"""
        if not url or not self._ensure_server():
            return ""
        with self._lock:
            self._seq += 1
            sid = "%08x" % ((self._seq * 2654435761) & 0xFFFFFFFF)
            self._items[sid] = {"url": url, "headers": dict(headers or {}),
                                "size": int(size or 0), "refresh": refresh}
            if len(self._items) > 96:      # 只保留最近的，防长时间运行内存涨
                for k in list(self._items.keys())[:48]:
                    self._items.pop(k, None)
        return sid

    def drop(self, sid):
        """摘掉一条已注册的流：后台校验判定不通时调用，
        让正在等数据的播放器请求立刻拿到 502 而不是一直挂到超时"""
        try:
            with self._lock:
                self._items.pop(sid, None)
        except Exception:
            pass

    def _total_size(self, it):
        """上游总长：从 Range: bytes=0-0 的 Content-Range 里取"""
        if it.get("size"):
            return it["size"]
        try:
            h = dict(it["headers"])
            h["Range"] = "bytes=0-0"
            r = requests.get(it["url"], headers=h, stream=True, timeout=(8, 12))
            m = re.search(r"/(\d+)\s*$", r.headers.get("Content-Range") or "")
            if m:
                it["size"] = int(m.group(1))
            ct = r.headers.get("Content-Type")
            if ct:
                it["ctype"] = ct
            try:
                r.close()
            except Exception:
                pass
        except Exception:
            pass
        return it.get("size") or 0

    @staticmethod
    def _parse_range(hdr, total):
        start, end = 0, (total - 1 if total else 0)
        if hdr:
            m = re.search(r"bytes=(\d*)-(\d*)", hdr)
            if m:
                s, e = m.group(1), m.group(2)
                if s == "" and e:
                    n = int(e)
                    start = max(0, total - n)
                    end = total - 1
                else:
                    start = int(s or 0)
                    end = int(e) if e else (total - 1 if total else start)
        if total and end >= total:
            end = total - 1
        if end < start:
            end = start
        return start, end

    # ---------- 上游拉流 ----------
    def _maybe_refresh(self, it):
        """直链/cookie 失效时调用 refresh 回调换新的。并发拉块线程共用一把锁：
        一个线程刷新期间其余线程等它刷完直接用新链，避免 96 个线程同时回源刷新"""
        if not it.get("refresh"):
            return False
        lock = it.setdefault("_rlock", threading.Lock())
        with lock:
            if time.time() - it.get("_refreshed_at", 0) < 15:   # 刚刷新过（或别的线程刚试过）
                return bool(it.get("url"))
            it["_refreshed_at"] = time.time()
            try:
                url, headers = it["refresh"]() or ("", {})
                if url:
                    it["url"] = url
                    it["headers"] = dict(headers or {})
                    return True
            except Exception:
                pass
            return False

    def _fetch_block(self, sess, it, start, end):
        """用【长连接】按 Range 拉一块（夸克限速是每连接 0.1MB/s，长连接可连续取块）。
        必须恰好取满 want 字节：短读/断流直接写出去会让后续块全部错位损坏；
        多写又会超过响应 Content-Length、污染 keep-alive 上的下一个响应——不够就重拉。
        ★ 403/410/412 = 匿名会话 cookie 过期：先刷新直链再试，别把错误页当数据写出去"""
        sh = int(it.get("shift") or 0)      # PNG 伪装头：上游取流整体右移 sh 字节
        want = end - start + 1
        for attempt in range(3):
            try:
                h = dict(it["headers"])
                h["Range"] = "bytes=%d-%d" % (start + sh, end + sh)
                r = sess.get(it["url"], headers=h, stream=True, timeout=(10, 30))
                if r.status_code not in (200, 206):
                    try:
                        r.close()
                    except Exception:
                        pass
                    if self._maybe_refresh(it):
                        continue          # 拿到新直链，重试这一块
                    return b""
                buf, got = [], 0
                for c in r.iter_content(65536):
                    if not c:
                        continue
                    buf.append(c)
                    got += len(c)
                    if got >= want:
                        break
                try:
                    r.close()
                except Exception:
                    pass
                if got >= want:
                    return b"".join(buf)[:want]
            except Exception:
                pass
        return b""

    def _sniff(self, it):
        """拉文件头 512 字节嗅探【真实】格式，结果缓存进 item。
        ★ 分享文件扩展名完全不可信（实测一个 29 集分享里同时存在：
          .mkv→MP4、.mp4/.mp3→MKV，以及 PNG 伪装头+MP4 和 PNG 伪装头+MKV 两种防和谐文件）；
          伪装头不剥掉，播放器按错位字节解封装，51 分钟的视频只显示 15 秒。
        产出 it["shift"]（上游取流右移字节数）和 it["ctype"]（真实 Content-Type）"""
        if "_sniffed" in it:
            return
        it["_sniffed"] = True
        head = b""
        try:
            head = self._fetch_range(it, 0, 511) or b""
        except Exception:
            pass
        it["shift"], it["ctype"] = self._sniff_head(head, it.get("url") or "")

    @staticmethod
    def _sniff_head(head, url):
        """在文件头前 48 字节内定位真实容器签名（伪装头会顶掉 offset 0），
        返回 (shift, ctype)：shift = 伪装头长度；靠前出现的签名优先"""
        shift, ctype = 0, ""
        if head:
            i = head.find(b"\x1a\x45\xdf\xa3", 0, 48)          # EBML → MKV
            j = head.find(b"ftyp", 0, 48)                     # MP4 box 类型（前 4 字节是 box size）
            if j >= 4 and not (8 <= int.from_bytes(head[j - 4:j], "big") <= 64):
                j = -1                                        # 伪 ftyp（box size 不合理）
            if i >= 0 and (j < 4 or i <= j - 4):
                shift, ctype = i, "video/x-matroska"
            elif j >= 4:
                shift = j - 4
                ctype = "video/quicktime" if head[j + 4:j + 6] == b"qt" else "video/mp4"
            elif head[:3] == b"FLV":
                ctype = "video/x-flv"
            elif len(head) >= 377 and head[0] == 0x47 and head[188] == 0x47 and head[376] == 0x47:
                ctype = "video/mp2t"
            elif head[:3] == b"ID3" or head[:2] in (b"\xff\xfb", b"\xff\xf3", b"\xff\xf2"):
                ctype = "audio/mpeg"
        if not ctype:
            ctype = LocalStreamProxy._ext_mime(url)
        return shift, ctype

    @staticmethod
    def _ext_mime(url):
        """扩展名兜底（仅在 magic 嗅不出来时用）"""
        ext = os.path.splitext((url or "").split("?")[0].lower())[1]
        return {".mp4": "video/mp4", ".mkv": "video/x-matroska", ".flv": "video/x-flv",
                ".ts": "video/mp2t", ".m3u8": "application/vnd.apple.mpegurl",
                ".avi": "video/x-msvideo", ".mov": "video/quicktime"}.get(ext, "video/mp4")

    def _fetch_range(self, it, start, end):
        """单连接拉一段（探测用）"""
        sess = requests.Session()
        try:
            sess.trust_env = False
        except Exception:
            pass
        try:
            return self._fetch_block(sess, it, start, end)
        finally:
            try:
                sess.close()
            except Exception:
                pass

    def _stream_seg(self, it, s0, e0, wfile, wlock, state):
        """一条连接负责一个【固定区间】，边收边写，不再二次缓冲、不等别的块。
        ★ 这才是并发能叠加的关键：每个连接各拉各的一段，收多少立刻写多少，
          彼此不阻塞。原来的"轮转小块 + 按序写"里写端要求严格按块序输出，
          快的连接必须等最慢那条，96 条连接实际退化成 1 条在干活。"""
        import socket as _sock
        sh = int(it.get("shift") or 0)
        want = e0 - s0 + 1
        parsed = urllib.parse.urlparse(it["url"])
        host = parsed.netloc
        path = parsed.path or "/"
        if parsed.query:
            path = path + "?" + parsed.query
        got = 0
        for attempt in range(3):
            if state["stop"] or got >= want:
                break
            s = None
            try:
                h = dict(it["headers"])
                h["Range"] = "bytes=%d-%d" % (s0 + sh, s0 + sh + want - got - 1)
                h["Host"] = host
                h["Connection"] = "close"
                h.setdefault("Accept-Encoding", "identity")
                s = _sock.create_connection((host, 443 if parsed.scheme == "https" else 80),
                                            timeout=12)
                s.settimeout(30)
                if parsed.scheme == "https":
                    try:
                        import ssl as _ssl
                        s = _ssl.create_default_context().wrap_socket(
                            s, server_hostname=host.split(":")[0])
                    except Exception:
                        pass
                req = ("GET %s HTTP/1.1\r\n" % path) + "".join(
                    "%s: %s\r\n" % (k, v) for k, v in h.items()) + "\r\n"
                s.sendall(req.encode("utf-8"))
                # 读响应头
                hdr = b""
                while b"\r\n\r\n" not in hdr:
                    c = s.recv(4096)
                    if not c:
                        break
                    hdr += c
                    if len(hdr) > 32768:
                        break
                head, _, rest = hdr.partition(b"\r\n\r\n")
                try:
                    code = int(head.split(b"\r")[0].split()[1])
                except Exception:
                    code = 0
                if code not in (200, 206):
                    # 403/412 = 匿名会话过期，换条新直链再试
                    if code in (403, 410, 412) and self._maybe_refresh(it):
                        parsed = urllib.parse.urlparse(it["url"])
                        host = parsed.netloc
                        path = parsed.path or "/"
                        if parsed.query:
                            path = path + "?" + parsed.query
                    try:
                        s.close()
                    except Exception:
                        pass
                    time.sleep(0.4 * (attempt + 1))
                    continue
                # 流式写：先吐掉响应头里带过来的那截 body
                if rest:
                    with wlock:
                        wfile.write(rest)
                        wfile.flush()
                    got += len(rest)
                while got < want and not state["stop"]:
                    c = s.recv(262144)
                    if not c:
                        break
                    with wlock:
                        wfile.write(c)
                        wfile.flush()
                    got += len(c)
            except Exception:
                pass
            finally:
                try:
                    if s is not None:
                        s.close()
                except Exception:
                    pass
            if got < want:
                time.sleep(0.3)
        if got < want:
            state["stop"] = True

    def _pump(self, it, wfile, start, end):
        """单连接顺序透传：直接从夸克 CDN 拉 [start,end] 边收边写。
        多连接分段拼接会让播放器收到顺序错乱的 MP4 字节（有速度但不出画面），
        所以这里改成一条连接顺序流，宁慢不错。"""
        total = end - start + 1
        if total <= 0:
            return
        sh = int(it.get("shift") or 0)
        import requests as _rq
        for attempt in range(2):
            h = dict(it["headers"] or {})
            h["Range"] = "bytes=%d-%d" % (start + sh, end + sh)
            h.setdefault("Accept-Encoding", "identity")
            try:
                r = _rq.get(it["url"], headers=h, stream=True, timeout=(8, 30))
                code = r.status_code
                if code >= 400:
                    try:
                        r.close()
                    except Exception:
                        pass
                    if attempt == 0 and it.get("refresh"):
                        try:
                            nu, nh = it["refresh"]()
                            if nu:
                                it["url"] = nu
                                if nh:
                                    it["headers"] = dict(nh)
                                continue
                        except Exception:
                            pass
                    return
                sent = 0
                for chunk in r.iter_content(65536):
                    if not chunk:
                        continue
                    wfile.write(chunk)
                    sent += len(chunk)
                    if sent >= total:
                        break
                try:
                    r.close()
                except Exception:
                    pass
                return
            except Exception:
                continue

    # ---------- 请求处理 ----------
    def _handle(self, handler):
        try:
            path = handler.path.split("?")[0].strip("/")
            parts = path.split("/")
            if len(parts) not in (2, 3) or parts[0] not in ("s", "probe"):
                handler.send_response(404)
                handler.send_header("Content-Length", "0")
                handler.end_headers()
                return
            mode, sid = parts[0], parts[1]
            with self._lock:
                it = self._items.get(sid)
            if not it:
                handler.send_response(404)
                handler.send_header("Content-Length", "0")
                handler.end_headers()
                return
            if mode == "probe":
                # 连通性自检：★ 一次性拉 512B，同时把 size/ctype/shift 都填上，
                # 这样后面真正 /s/ 请求不必再回源跑 _total_size + _sniff 两次串行探测
                # （原来那两次是起播卡顿的主因：游客直链单次就要 ~5-10s）
                body = self._fetch_range(it, 0, 511) or b""
                if body:
                    it["_sniffed"] = True
                    it["shift"], it["ctype"] = self._sniff_head(body, it.get("url") or "")
                    if not it.get("size"):
                        try:
                            h = dict(it["headers"])
                            h["Range"] = "bytes=0-0"
                            r = requests.get(it["url"], headers=h, stream=True, timeout=(6, 10))
                            m = re.search(r"/(\d+)\s*$", r.headers.get("Content-Range") or "")
                            if m:
                                it["size"] = int(m.group(1))
                            if not it.get("ctype"):
                                ct = r.headers.get("Content-Type")
                                if ct:
                                    it["ctype"] = ct
                            try:
                                r.close()
                            except Exception:
                                pass
                        except Exception:
                            pass
                handler.send_response(200 if body else 502)
                handler.send_header("Content-Type", "application/octet-stream")
                handler.send_header("Content-Length", str(len(body)))
                handler.end_headers()
                if body:
                    handler.wfile.write(body)
                return
            self._sniff(it)      # 真实格式 + PNG 伪装头偏移（扩展名不可信）
            total = self._total_size(it) - int(it.get("shift") or 0)
            if total <= 0:
                handler.send_response(502)
                handler.send_header("Content-Length", "0")
                handler.end_headers()
                return
            start, end = self._parse_range(handler.headers.get("Range"), total)
            length = end - start + 1
            has_range = bool(handler.headers.get("Range"))
            handler.send_response(206 if has_range else 200)
            handler.send_header("Content-Type", it.get("ctype") or self._ext_mime(it.get("url") or ""))
            handler.send_header("Accept-Ranges", "bytes")
            handler.send_header("Content-Length", str(length))
            if has_range:
                handler.send_header("Content-Range", "bytes %d-%d/%d" % (start, end, total))
            handler.send_header("Connection", "close")
            handler.end_headers()
            self._pump(it, handler.wfile, start, end)
        except Exception:
            try:
                import traceback as _tb; _tb.print_exc()
            except Exception:
                pass
            try:
                handler.send_response(500)
                handler.send_header("Content-Length", "0")
                handler.end_headers()
            except Exception:
                pass


# ---------------------------------------------------------------------------
# 123 云盘解析（免登直链，来自 jar merge/b/m.java 移植）
# ---------------------------------------------------------------------------
class Pan123:
    SHARE_RE = re.compile(r"https?://(?:www\.)?(?:123pan|123684|123865|123912|123592)\.(?:com|cn)/s/([\w\-]+)")

    def _headers(self):
        return {"referer": "https://www.123pan.com", "origin": "https://www.123pan.com",
                "platform": "open_platform", "user-agent": DART_UA, "app-version": "3"}

    def _parse(self, share_url):
        m = self.SHARE_RE.search(share_url or "")
        if not m:
            return "", ""
        key = m.group(1)
        if key.endswith(".html"):
            key = key[:-5]
        pwd = ""
        pm = re.search(r"[?&](?:pwd|SharePwd)=(\w+)", share_url or "")
        if pm:
            pwd = pm.group(1)
        return key, pwd

    def list_videos(self, share_url):
        """递归拿分享内视频：返回 [{'file_id','file_name','size','etag','s3key','download_url'}]"""
        key, pwd = self._parse(share_url)
        if not key:
            return []
        out = []
        self._walk(key, pwd, 0, out, depth=0)
        return out

    def _walk(self, key, pwd, parent_id, out, depth):
        if depth > 12:
            return
        page = 1
        while True:
            url = (f"https://www.123pan.cn/b/api/share/get?limit=100&Page={page}&next=-1"
                   f"&orderBy=file_name&orderDirection=asc&parentFileId={parent_id}"
                   f"&shareKey={key}&SharePwd={pwd}")
            r = requests.get(url, headers=self._headers(), timeout=15)
            r.encoding = "utf-8"
            try:
                data = r.json()
            except Exception:
                break
            items = ((data.get("data") or {}).get("InfoList")) or []
            if not items:
                break
            for it in items:
                cat = it.get("Category", -1)
                name = it.get("FileName", "")
                if cat == 2 or name.lower().endswith(VIDEO_EXT):
                    out.append({"file_id": it.get("FileId", ""),
                                "file_name": name or "未命名",
                                "size": it.get("Size", 0),
                                "etag": it.get("Etag", ""),
                                "s3key": it.get("S3KeyFlag", ""),
                                "download_url": it.get("DownloadUrl", "")})
                elif it.get("Type") == 1 or it.get("Type") == 0 and not it.get("DownloadUrl"):
                    self._walk(key, pwd, it.get("FileId", 0), out, depth + 1)
            if len(items) < 100:
                break
            page += 1

    @staticmethod
    def play_direct(download_url):
        u = (download_url or "").replace("_24_24", "")
        u = u.replace("&cache_type=1&w=24&h=24&trade_key=123pan-thumbnail&type=video", "")
        return {"parse": 0, "url": u,
                "header": {"referer": "https://www.123pan.com", "origin": "https://www.123pan.com",
                           "platform": "android", "user-agent": DART_UA, "app-version": "3"}}


# ---------------------------------------------------------------------------
# 百度网盘（分享页匿名列目录；直链需要 BDUSS/Cookie）
# ---------------------------------------------------------------------------
BD_CLEAN_TEMP = True
BD_COOKIE = 'BDUSS=hTd0sxblBmY3hZZjd1MTVtN0dVenJVb1llZ2N6NEhzUlpSOURtdG5uQnhoeUpwSVFBQUFBJCQAAAAAAAAAAAEAAAAcq2wzZ2FvMjMzNDUAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAHH6-mhx-vpoTm;STOKEN=f39e38007dc616d08439a9700fa4bb1e165d7e1eba9bee5f6cc759874e3453e3'
DEFAULT_BD_COOKIE = BD_COOKIE
BD_TRANSFER_CACHE = {}
BD_TRANSFER_FID = {}
_BD_BDS_TOKEN = {"v": ""}
_BD_PROXY = {"port": 0}
_PROXY_PROBE_CACHE = {}
_QUARK_LINK_CACHE = {}


def _bd_proxy_start():
    """起一个本机 HTTP 代理，播放器只连 127.0.0.1，由代理带 Cookie 去拉百度直链。"""
    if _BD_PROXY.get("port"):
        return _BD_PROXY["port"]

    class _H(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.0"
        CHUNK = 2 * 1024 * 1024
        WORKERS = 8

        def log_message(self, *a):
            pass

        def _headers_for(self):
            site = getattr(self, "_site", "baidu")
            ck = getattr(self, "_ck", "") or BD_COOKIE
            if site == "quark":
                h = {"User-Agent": PC_UA, "Cookie": ck,
                     "Referer": "https://pan.quark.cn", "Accept-Encoding": "identity"}
            elif site == "xunlei":
                # 按本地包 X.r() 的播放头：直链 CDN 没有这些头会 403 或一直转圈
                h = {"User-Agent": XL_UA,
                     "Referer": "https://pan.xunlei.com/",
                     "Origin": "https://pan.xunlei.com",
                     "X-Client-Id": XL_CLIENT_ID,
                     "X-Device-Id": _xl_device(),
                     "Accept-Encoding": "identity"}
            else:
                h = {"User-Agent": "netdisk;12.11.9;V2238A;android-android;12;JSbridge4.4.0;jointBridge;1.1.0;",
                     "Cookie": ck, "Accept-Encoding": "identity"}
            rng = self.headers.get("Range")
            if rng:
                h["Range"] = rng
            return h

        def _up(self, u, h, method=None):
            req = urllib.request.Request(u, headers=h, method=method)
            try:
                return urllib.request.urlopen(req, timeout=30)
            except urllib.error.HTTPError as e:
                return e

        def _probe(self, u, pth, h):
            """取总大小+是否真的支持 Range；不支持就回退单流，避免分片全下错。"""
            _pkey = (u, getattr(self, "_site", "baidu"))
            _ph = _PROXY_PROBE_CACHE.get(_pkey)
            if _ph and _ph[0] > time.time():
                return _ph[1], _ph[2], _ph[3], _ph[4], _ph[5]
            total, ctype, code, ranged = 0, "", 0, False
            for attempt in (0, 1):
                hh = dict(h)
                hh["Range"] = "bytes=0-0"
                r = self._up(u, hh)
                code = getattr(r, "status", getattr(r, "code", 0))
                if code in (401, 403, 404, 503) and pth and attempt == 0:
                    try:
                        nu = BaiduDrive(BD_COOKIE)._direct(pth)
                        if nu:
                            try:
                                r.close()
                            except Exception:
                                pass
                            u = nu
                            continue
                    except Exception:
                        pass
                cr = r.headers.get("Content-Range") or ""
                if "/" in cr:
                    try:
                        total = int(cr.rsplit("/", 1)[1])
                        ranged = True
                    except Exception:
                        total = 0
                        ranged = False
                if not total:
                    cl = r.headers.get("Content-Length") or ""
                    if cl.isdigit():
                        total = int(cl)
                ctype = r.headers.get("Content-Type") or ""
                try:
                    r.read(1)
                except Exception:
                    pass
                try:
                    r.close()
                except Exception:
                    pass
                _PROXY_PROBE_CACHE[_pkey] = (time.time() + 120, u, total, ctype, code, ranged)
                while len(_PROXY_PROBE_CACHE) > 120:
                    _PROXY_PROBE_CACHE.pop(next(iter(_PROXY_PROBE_CACHE)), None)
                return u, total, ctype, code, ranged
            return u, 0, "", code, False

        def _fetch(self, u, h, s, e):
            hh = dict(h)
            hh["Range"] = "bytes=%d-%d" % (s, e)
            r = self._up(u, hh)
            code = getattr(r, "status", getattr(r, "code", 0))
            if code not in (200, 206):
                try:
                    r.close()
                except Exception:
                    pass
                return b""
            try:
                _need = e - s + 1
                _buf = bytearray()
                while len(_buf) < _need:
                    _c = r.read(_need - len(_buf))
                    if not _c:
                        break
                    _buf.extend(_c)
                data = bytes(_buf)
            except Exception:
                data = b""
            try:
                r.close()
            except Exception:
                pass
            return data

        def _send_common(self, code, ctype, length, total, start, end, ranged_request):
            self.send_response(code)
            self.send_header("Content-Type", ctype or "video/mp4")
            self.send_header("Content-Length", str(length))
            if ranged_request and total:
                self.send_header("Content-Range", "bytes %d-%d/%d" % (start, end, total))
            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Connection", "close")
            self.end_headers()

        def _fetch_sess(self, sess, u, h, s0, e0):
            """一条长连接上顺序拉一块；短读/断流重试，403 重试。"""
            import requests as _rq
            need = e0 - s0 + 1
            for _ in range(3):
                hh = dict(h)
                hh["Range"] = "bytes=%d-%d" % (s0, e0)
                try:
                    r = (sess or _rq).get(u, headers=hh, stream=True,
                                             timeout=(10, 30), verify=False)
                    if r.status_code not in (200, 206):
                        try:
                            r.close()
                        except Exception:
                            pass
                        continue
                    buf = bytearray()
                    for c in r.iter_content(65536):
                        if not c:
                            continue
                        buf.extend(c)
                        if len(buf) >= need:
                            break
                    try:
                        r.close()
                    except Exception:
                        pass
                    if len(buf) >= need:
                        return bytes(buf[:need])
                except Exception:
                    continue
            return b""

        def _serve_quark_pump(self, u, h, start, end, total, ctype):
            """夸克专用：64 条长连接、64KB/块、轮转取块、按序写。
            单连接约 0.1MB/s，64 路叠加 ≈ 5MB/s；小范围也能立刻叠起来。"""
            import threading as _th
            import requests as _rq
            need = end - start + 1
            B = 65536
            nblocks = (need + B - 1) // B
            first = self._fetch_sess(None, u, h, start, min(end, start + B - 1))
            if not first:
                first = self._fetch_sess(None, u, h, start, min(end, start + B - 1))
            if not first:
                return False
            ranged_req = bool(self.headers.get("Range"))
            self._send_common(206 if ranged_req else 200, ctype, need, total,
                              start, end, ranged_req)
            self.wfile.write(first)
            self.wfile.flush()
            if nblocks <= 1:
                return True
            W = min(64, nblocks - 1)
            cond = _th.Condition()
            ready = {}
            state = {"next": 1, "stop": False}

            def worker(w):
                sess = _rq.Session()
                try:
                    sess.trust_env = False
                    sess.verify = False
                except Exception:
                    pass
                idx = 1 + w
                while True:
                    with cond:
                        while (not state["stop"] and idx < nblocks
                               and idx >= state["next"] + W):
                            cond.wait(0.3)
                        if state["stop"] or idx >= nblocks:
                            break
                    s0 = start + idx * B
                    e0 = min(end, s0 + B - 1)
                    data = self._fetch_sess(sess, u, h, s0, e0)
                    with cond:
                        ready[idx] = data
                        cond.notify_all()
                    idx += W
                try:
                    sess.close()
                except Exception:
                    pass

            for w in range(W):
                _th.Thread(target=worker, args=(w,), daemon=True).start()
            try:
                while state["next"] < nblocks:
                    with cond:
                        while (state["next"] < nblocks
                               and state["next"] not in ready
                               and not state["stop"]):
                            cond.wait(0.3)
                        if state["stop"] or state["next"] >= nblocks:
                            break
                        idx = state["next"]
                        data = ready.pop(idx)
                        state["next"] = idx + 1
                        cond.notify_all()
                    if not data:
                        break
                    self.wfile.write(data)
                    self.wfile.flush()
            except (BrokenPipeError, ConnectionResetError):
                pass
            finally:
                with cond:
                    state["stop"] = True
                    cond.notify_all()
            return True

        def _serve_parallel(self, u, h, start, end, total, ctype):
            need = end - start + 1
            # 小范围（起播 2-4MB）用长连接泵，首屏快；大范围用分片池，吞吐更高
            if (getattr(self, "_site", "") == "quark"
                    and 2 * 1024 * 1024 <= need <= 4 * 1024 * 1024):
                if self._serve_quark_pump(u, h, start, end, total, ctype):
                    return True
            chunks = []
            cur = start
            # 首片小一点先发出去（夸克单连接只有 ~0.1MB/s，512K 首片要等 5 秒才出画面）
            _first = 128 * 1024 if getattr(self, "_site", "") == "quark" else self.CHUNK
            chunks.append((cur, min(cur + _first - 1, end)))
            cur = chunks[-1][1] + 1
            while cur <= end:
                chunks.append((cur, min(cur + self.CHUNK - 1, end)))
                cur += self.CHUNK
            # 先拉第一片，失败就退回单流（此时还没发响应头）
            first = self._fetch(u, h, chunks[0][0], chunks[0][1])
            if not first:
                first = self._fetch(u, h, chunks[0][0], chunks[0][1])
            if not first:
                return False
            ranged_req = bool(self.headers.get("Range"))
            self._send_common(206 if ranged_req else 200, ctype, need, total,
                              start, end, ranged_req)
            self.wfile.write(first)
            written = len(first)
            from concurrent.futures import ThreadPoolExecutor
            pending = []
            idx = 1
            try:
                with ThreadPoolExecutor(max_workers=self.WORKERS) as pool:
                    while idx < len(chunks) or pending:
                        while idx < len(chunks) and len(pending) <= self.WORKERS * 2:
                            _rng = chunks[idx]
                            pending.append((pool.submit(self._fetch, u, h,
                                                        _rng[0], _rng[1]), _rng))
                            idx += 1
                        fut, _rng = pending.pop(0)
                        try:
                            data = fut.result()
                        except Exception:
                            data = b""
                        # 夸克 CDN 偶发 403/断流：同一片重试两次，别让播放器拿到半截流一直转圈
                        if not data:
                            for _ in range(2):
                                data = self._fetch(u, h, _rng[0], _rng[1])
                                if data:
                                    break
                        if not data:
                            break
                        self.wfile.write(data)
                        written += len(data)
                        if written >= need:
                            break
            except (BrokenPipeError, ConnectionResetError):
                pass
            return True

        def do_HEAD(self):
            q = parse_qs(urlparse(self.path).query)
            u = (q.get("u") or [""])[0]
            pth = (q.get("p") or [""])[0]
            self._site = (q.get("site") or ["baidu"])[0]
            self._ck = (q.get("ck") or [""])[0]
            if self._site == "quark":
                self.CHUNK = 256 * 1024
                self.WORKERS = 48
            if not u:
                self.send_error(404)
                return
            h = self._headers_for()
            u, total, ctype, code, ranged = self._probe(u, pth, h)
            self.send_response(code or 502)
            if ctype:
                self.send_header("Content-Type", ctype)
            if total:
                self.send_header("Content-Length", str(total))
            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Connection", "close")
            self.end_headers()

        def do_GET(self):
            q = parse_qs(urlparse(self.path).query)
            u = (q.get("u") or [""])[0]
            pth = (q.get("p") or [""])[0]
            self._site = (q.get("site") or ["baidu"])[0]
            self._ck = (q.get("ck") or [""])[0]
            if self._site == "quark":
                self.CHUNK = 256 * 1024
                self.WORKERS = 48
            if not u:
                self.send_error(404)
                return
            h = self._headers_for()
            u, total, ctype, code, ranged = self._probe(u, pth, h)
            if code == 0:
                self.send_error(502)
                return
            if code >= 400:
                try:
                    self.send_error(code)
                except Exception:
                    pass
                return

            rng = self.headers.get("Range")
            start, end = 0, (total - 1 if total else 0)
            if rng:
                m = re.match(r"bytes=(\d*)-(\d*)", rng)
                if m:
                    start = int(m.group(1) or 0)
                    end = int(m.group(2)) if m.group(2) else (total - 1 if total else start)
            if total:
                if start >= total:
                    self.send_response(416)
                    self.send_header("Content-Range", "bytes */%d" % total)
                    self.end_headers()
                    return
                end = min(end, total - 1)

            # 只有上游确实支持 Range、且请求范围够大时才分片
            _is_q = getattr(self, "_site", "") == "quark"
            if total and (_is_q or ranged) and (end - start + 1) >= (256 * 1024 if _is_q else 4 * 1024 * 1024):
                if self._serve_parallel(u, h, start, end, total, ctype):
                    return

            # 单流回退
            hh = dict(h)
            if rng:
                hh["Range"] = "bytes=%d-%d" % (start, end) if total else rng
            r = self._up(u, hh)
            code = getattr(r, "status", getattr(r, "code", 0))
            if code in (401, 403, 404, 503) and pth:
                try:
                    nu = BaiduDrive(BD_COOKIE)._direct(pth)
                    if nu:
                        r.close()
                        r = self._up(nu, hh)
                        code = getattr(r, "status", getattr(r, "code", 0))
                except Exception:
                    pass
            if code >= 400:
                try:
                    self.send_error(code)
                except Exception:
                    pass
                return
            length = int(r.headers.get("Content-Length") or 0) or (end - start + 1 if total else 0)
            self.send_response(206 if rng else 200)
            self.send_header("Content-Type", r.headers.get("Content-Type") or ctype or "video/mp4")
            if length:
                self.send_header("Content-Length", str(length))
            for k in ("Content-Range", "Accept-Ranges"):
                v = r.headers.get(k)
                if v:
                    self.send_header(k, v)
            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Connection", "close")
            self.end_headers()
            try:
                while True:
                    chunk = r.read(1048576)
                    if not chunk:
                        break
                    self.wfile.write(chunk)
            except (BrokenPipeError, ConnectionResetError):
                pass
            finally:
                try:
                    r.close()
                except Exception:
                    pass

    try:
        srv = ThreadingHTTPServer(("127.0.0.1", 0), _H)
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        _BD_PROXY["port"] = srv.server_address[1]
    except Exception:
        _BD_PROXY["port"] = 0
    return _BD_PROXY["port"]


class BaiduDrive:
    BASE = "https://pan.baidu.com"
    VIDEO_EXT = (".mp4", ".mkv", ".avi", ".mov", ".wmv", ".flv", ".ts", ".m2ts",
                 ".rmvb", ".webm", ".m4v", ".iso")

    def __init__(self, cookie=""):
        # 分享页/目录用匿名会话：带失效 Cookie 反而会“提取码验证失败”
        self.pub = requests.Session()
        self.pub.headers.update({
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                          "(KHTML, like Gecko) Chrome/120.0 Safari/537.36",
            "Referer": "https://pan.baidu.com/",
        })
        # 直链接口才用登录 Cookie
        self.s = requests.Session()
        self.s.headers.update(dict(self.pub.headers))
        if cookie:
            self.s.headers["Cookie"] = cookie

    def parse_share(self, share_url):
        """返回 (uk, shareid, surl, pwd)；匿名也能读目录，直链才要 Cookie。"""
        m = re.search(r"/s/([^?]+)", share_url or "")
        if not m:
            return "", "", "", ""
        surl = m.group(1)
        pwd = ""
        pm = re.search(r"[?&]pwd=([\w]+)", share_url or "")
        if pm:
            pwd = pm.group(1)
        try:
            r = self.pub.get(share_url, timeout=15, allow_redirects=True)
        except Exception:
            return "", "", surl, pwd
        html = r.text or ""
        uk = ""
        sid = ""
        mu = re.search(r'"share_uk"\s*:\s*"?([0-9]+)', html) or re.search(r"share_uk\s*:\s*['\"]?([0-9]+)", html)
        ms = re.search(r'"shareid"\s*:\s*"?([0-9]+)', html) or re.search(r"shareid\s*:\s*['\"]?([0-9]+)", html)
        if mu:
            uk = mu.group(1)
        if ms:
            sid = ms.group(1)
        mm = re.search(r"sur[" + "l]=(.+?)(?:&|$)", r.url or "")
        if mm:
            surl = mm.group(1)
        if pwd and surl:
            try:
                self.pub.post(self.BASE + "/share/verify",
                            params={"surl": surl, "t": str(int(time.time() * 1000)),
                                    "channel": "chunlei", "web": "1",
                                    "app_id": "250528", "clienttype": "0"},
                            data={"pwd": pwd, "vcode": "", "vcode_str": ""}, timeout=15)
            except Exception:
                pass
        return uk, sid, surl, pwd

    def _list(self, uk, sid, path="/", root=False):
        params = {"uk": uk, "shareid": sid, "order": "other", "desc": "1",
                  "showempty": "0", "web": "1", "page": "1", "num": "200",
                  "dir": path}
        params["root"] = "1" if root else "0"
        try:
            r = self.pub.get(self.BASE + "/share/list", params=params, timeout=15)
            return r.json() or {}
        except Exception:
            return {}

    def walk(self, share_url, limit=500):
        """递归列出分享里的视频文件，返回 [{file_name,path,size}]。"""
        uk, sid, surl, pwd = self.parse_share(share_url)
        if not uk or not sid:
            return []
        out = []

        def rec(path, depth, root=False):
            if len(out) >= limit or depth > 5:
                return
            data = self._list(uk, sid, path, root=root)
            for it in (data.get("list") or []):
                if len(out) >= limit:
                    break
                name = _dump(it.get("server_filename"))
                p = _dump(it.get("path"))
                isdir = str(it.get("isdir") or "0") in ("1", "true", "True")
                if isdir:
                    if p and p != path:
                        rec(p, depth + 1)
                elif name.lower().endswith(self.VIDEO_EXT):
                    out.append({"file_name": name or "未命名",
                                "path": p,
                                "fs_id": str(it.get("fs_id") or ""),
                                "size": it.get("size", 0)})

        # 根目录必须带 root=1；子目录不能带 root，否则只回根文件夹
        rec("/", 0, root=True)
        return out

    def ensure_dir(self, path="/我的资源/豆瓣临时"):
        try:
            self.s.post(self.BASE + "/api/create",
                        params={"a": "commit", "channel": "chunlei", "web": "1",
                                "app_id": "250528", "clienttype": "0"},
                        data={"path": path, "isdir": "1", "block_list": "[]", "size": "0"},
                        timeout=15)
        except Exception:
            pass

    def transfer(self, share_url, share_path, share_fid=""):
        """把分享里的单个文件转存到自己的临时目录，返回自己的路径。"""
        uk, sid, surl, pwd = self.parse_share(share_url)
        if not uk or not sid:
            return ""
        self.ensure_dir()
        sekey = unquote(self.pub.cookies.get_dict().get("BDCLND", ""))
        try:
            r = self.s.post(self.BASE + "/share/transfer",
                            params={"shareid": sid, "from": uk, "sekey": sekey,
                                    "ondup": "overwrite", "async": "1",
                                    "channel": "chunlei", "web": "1",
                                    "app_id": "250528", "clienttype": "0"},
                            data={"fsidlist": json.dumps([share_fid or share_path], ensure_ascii=False),
                                  "path": "/我的资源/豆瓣临时"}, timeout=30)
            data = r.json() or {}
            if data.get("errno") == 0:
                own = "/我的资源/豆瓣临时/" + os.path.basename(share_path)
                try:
                    extra = (data.get("extra") or {}).get("list") or []
                    if extra:
                        fid = str(extra[0].get("to_fs_id") or "")
                        if fid:
                            BD_TRANSFER_FID[own] = fid
                except Exception:
                    pass
                return own
        except Exception:
            pass
        return ""

    def _bdstoken(self):
        if _BD_BDS_TOKEN.get("v"):
            return _BD_BDS_TOKEN["v"]
        try:
            r = self.s.get(self.BASE + "/api/gettemplatevariable",
                           params={"fields": json.dumps(["bdstoken"], ensure_ascii=False)},
                           timeout=15)
            v = ((r.json() or {}).get("result") or {}).get("bdstoken") or ""
            if v:
                _BD_BDS_TOKEN["v"] = v
            return v
        except Exception:
            return ""

    def delete_file(self, fs_id):
        """只删自己转存的临时文件；本地包也是播完 3 秒后删。"""
        if not fs_id or not BD_COOKIE:
            return False
        token = self._bdstoken()
        try:
            h = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                              "(KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36",
                 "Accept": "application/json;charset=UTF-8",
                 "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
                 "Referer": "https://pan.baidu.com",
                 "Cookie": BD_COOKIE}
            r = self.s.post(self.BASE + "/api/filemanager",
                            params={"async": "2", "onnest": "fail", "opera": "delete",
                                    "bdstoken": token},
                            data={"filelist": json.dumps([str(fs_id)], ensure_ascii=False)},
                            headers=h, timeout=20)
            data = r.json() or {}
            return data.get("errno") == 0
        except Exception:
            return False

    def clean_temp(self, path="/我的资源/豆瓣临时"):
        """清空临时目录里的文件（开了 bd_clean_temp 才调用）。"""
        token = self._bdstoken()
        h = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                              "(KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36",
             "Accept": "application/json;charset=UTF-8",
             "Cookie": BD_COOKIE,
             "Referer": "https://pan.baidu.com"}
        total = 0
        start = 0
        while start < 10000:
            try:
                r = self.s.get(self.BASE + "/api/list",
                               params={"dir": path, "order": "time", "desc": "1",
                                       "web": "1", "app_id": "250528", "clienttype": "0",
                                       "bdstoken": token, "channel": "chunlei",
                                       "start": str(start), "limit": "1000"},
                               headers=h, timeout=20)
                data = r.json() or {}
                items = data.get("list") or []
            except Exception:
                break
            for it in items:
                if it.get("isdir"):
                    continue
                fid = it.get("fs_id")
                if fid and self.delete_file(fid):
                    total += 1
            if len(items) < 1000:
                break
            start += 1000
        return total

    def find_fid(self, path):
        """按文件路径查 fs_id；找不到返回空。"""
        parent = os.path.dirname(path) or "/"
        name = os.path.basename(path)
        token = self._bdstoken()
        try:
            r = self.s.get(self.BASE + "/api/list",
                           params={"dir": parent, "order": "name", "desc": "0",
                                   "web": "1", "app_id": "250528", "clienttype": "0",
                                   "bdstoken": token, "channel": "chunlei",
                                   "start": "0", "limit": "1000", "key": name},
                           headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                                                  "AppleWebKit/537.36 (KHTML, like Gecko) "
                                                  "Chrome/151.0.0.0 Safari/537.36",
                                    "Accept": "application/json;charset=UTF-8",
                                    "Cookie": BD_COOKIE, "Referer": "https://pan.baidu.com"},
                           timeout=20)
            for it in (r.json() or {}).get("list") or []:
                if it.get("server_filename") == name and not it.get("isdir"):
                    return str(it.get("fs_id") or "")
        except Exception:
            pass
        return ""

    def _schedule_delete(self, own):
        def _run():
            fid = BD_TRANSFER_FID.get(own, "") or self.find_fid(own)
            if not fid:
                return
            time.sleep(3.0)
            self.delete_file(fid)
        t = threading.Thread(target=_run, daemon=True)
        t.start()

    def play_share(self, share_url, share_path, share_fid=""):
        if not share_url or not share_path:
            return {"parse": 0, "url": "", "msg": "百度线路参数不完整"}
        own = BD_TRANSFER_CACHE.get(share_path, "")
        # 之前已经转存过：先直接取直链，避免重复转存
        if own:
            res = self.play(own)
            if res.get("url"):
                self._schedule_delete(own)
                return res
        own = "/我的资源/豆瓣临时/" + os.path.basename(share_path)
        res = self.play(own)
        if res.get("url"):
            BD_TRANSFER_CACHE[share_path] = own
            self._schedule_delete(own)
            return res
        own = self.transfer(share_url, share_path, share_fid)
        if not own:
            return {"parse": 0, "url": "", "msg": "百度转存失败，请重试或换线路"}
        BD_TRANSFER_CACHE[share_path] = own
        # 刚转存的文件百度索引有延迟，errno 12 时重试几秒
        for _ in range(4):
            res = self.play(own)
            if res.get("url"):
                self._schedule_delete(own)
                return res
            time.sleep(1.0)
        return {"parse": 0, "url": "", "msg": "百度转存后索引超时，请再点一次"}

    def _direct(self, path):
        if not path or not BD_COOKIE:
            return ""
        # 优先用本地包同款 mediainfo（origin=dlna），它的 dlink 不会像 filemetas 那样 503
        try:
            h = {"User-Agent": "netdisk;12.11.9;V2238A;android-android;12;JSbridge4.4.0;jointBridge;1.1.0;", "Cookie": BD_COOKIE}
            r = self.s.get(self.BASE + "/api/mediainfo",
                           params={"type": "M3U8_FLV_264_480", "path": path,
                                   "clienttype": "80", "origin": "dlna"},
                           headers=h, timeout=20)
            data = r.json() or {}
            info = data.get("info") or {}
            u = _dump(info.get("dlink")) if isinstance(info, dict) else ""
            if u:
                return u
        except Exception:
            pass
        # 兜底再走 filemetas
        try:
            r = self.s.get(self.BASE + "/api/filemetas",
                           params={"target": json.dumps([path], ensure_ascii=False),
                                   "dlink": "1", "web": "1", "channel": "chunlei",
                                   "app_id": "250528", "clienttype": "0"}, timeout=20)
            data = r.json() or {}
            info = data.get("info") or []
            if data.get("errno") == 0 and info:
                return _dump(info[0].get("dlink"))
        except Exception:
            pass
        return ""

    def play(self, path):
        if not path or not BD_COOKIE:
            return {"parse": 0, "url": "", "msg": "百度网盘未配置 BDUSS，无法取直链"}
        u = self._direct(path)
        if not u:
            return {"parse": 0, "url": "", "msg": "百度直链获取失败，请重试"}
        # 本地包 bdPlay 的做法：直链 + 播放头，不再套本机代理，少一层转发。
        return {"parse": 0, "url": u,
                "header": {"Referer": "https://pan.baidu.com",
                           "Cookie": BD_COOKIE,
                           "User-Agent": "netdisk;12.11.9;V2238A;android-android;12;JSbridge4.4.0;jointBridge;1.1.0;"}}


