def shuangxing_search(site, key, pg):
    html = http_get(site["session"], f"{site['url']}/search/?keyword={quote(key)}&page={pg}")
    return _star2_parse(site, html)


def shuangxing_category(site, tid, pg, extend):
    html = http_get(site["session"], f"{site['url']}/?page={pg}")
    return _star2_parse(site, html)


def _star2_parse(site, html):
    """剧透社列表只认 class=main 的链接，避免导航/搜索框被当成视频"""
    if BeautifulSoup is None:
        return []
    soup = BeautifulSoup(html, "html.parser")
    vods, seen = [], set()
    anchors = soup.select("a.main[href]")
    if not anchors:
        anchors = [a for a in soup.find_all("a", href=True)
                   if any("main" in str(c) for c in (a.get("class") or []))]
    for a in anchors:
        href = _dump(a.get("href"))
        if not href or href.startswith(("javascript", "#", "mailto")):
            continue
        title = a.get_text(" ", strip=True)
        if not title:
            img = a.find("img")
            title = _dump((img.get("alt") or img.get("title")) if img else "")
        title = re.sub(r"^【[^】]*】", "", title).strip()
        if not title:
            continue
        full = _abs(site["url"], href)
        if full in seen or full.rstrip("/") == site["url"].rstrip("/"):
            continue
        seen.add(full)
        img = a.find("img")
        vods.append({"vod_id": full, "vod_name": title[:80],
                     "vod_pic": _dump((img.get("src") or img.get("data-src")) if img else ""),
                     "vod_remarks": ""})
    return vods[:60] if vods else _html_link_parse(site, html)


def _html_link_parse(site, html):
    if BeautifulSoup is None:
        return []
    soup = BeautifulSoup(html, "html.parser")
    vods, seen = [], set()
    for a in soup.find_all("a", href=True):
        href = a["href"]
        if href.startswith(("javascript", "#", "mailto")):
            continue
        title = a.get_text(strip=True)
        if not title or len(title) < 4:
            img = a.find("img")
            title = (img.get("alt") or "") if img else ""
        if not title or len(title) < 4:
            continue
        full = _abs(site["url"], href)
        if full in seen or full.rstrip("/") == site["url"]:
            continue
        seen.add(full)
        img = a.find("img")
        vods.append({"vod_id": full, "vod_name": title[:80],
                     "vod_pic": (img.get("src") or img.get("data-src")) if img else "",
                     "vod_remarks": ""})
    return vods[:60]


# ----- Xiuno BBS 论坛站（夸父 / 123分享，移植自 PanWebShareKF/PanWebShare123） -----
BBS_REPLY_TEXTS = ["感谢楼主分享！", "这个资源太棒了！", "已收藏，谢谢！",
                   "不错的资源，支持一下", "楼主辛苦了！", "内容很有用，感谢分享"]
ALERT_SEL = ("div.message > div > div.alert, div.message > div.alert, "
             "div.message > section > div.alert, div.message > h5 > div.alert")


def _bbs_headers(site):
    h = {"Referer": site["url"], "Accept-Language": "zh-CN,zh;q=0.9"}
    h.update(site.get("extra_headers") or {})
    return h


def bbs_category(site, tid, pg, extend):
    cat = (extend or {}).get("cateId") or site["cats"][0]["v"]
    html = http_get(site["session"], f"{site['url']}/forum-{cat}-{pg}.htm",
                    headers=_bbs_headers(site))
    return _bbs_parse(site, html)


def bbs_search(site, key, pg):
    if site.get("search_style") == "path":
        url = f"{site['url']}/search-{quote(key)}-{pg}.htm"
    else:
        url = f"{site['url']}/search.htm?keyword={quote(key)}&page={pg}"
    html = http_get(site["session"], url, headers=_bbs_headers(site))
    return _bbs_parse(site, html)


def _bbs_parse(site, html):
    if BeautifulSoup is None:
        return []
    soup = BeautifulSoup(html, "html.parser")
    vods = []
    for li in soup.select("ul.threadlist > li"):
        if (li.select_one("i") or {}).get("data-placement", "") == "top" if li.select_one("i") else False:
            continue
        a = li.select_one("div > div.subject > a, div > div.style3_subject > a")
        if not a:
            continue
        title = a.get_text(strip=True)
        if not title or "福利" in title:
            continue
        img = li.select_one("a > img")
        pic = img.get("src", "") if img else ""
        if pic and not pic.startswith("http"):
            pic = site["url"] + "/" + pic.lstrip("/")
        vods.append({"vod_id": _abs(site["url"], a.get("href", "")),
                     "vod_name": title, "vod_pic": pic, "vod_remarks": ""})
    return vods[:60]


def _bbs_unlock_and_fetch(site, page_url):
    """回复解锁隐藏内容后返回页面 HTML（无 cookie 时直接返回原页）"""
    html = http_get(site["session"], page_url, timeout=15, headers=_bbs_headers(site))
    if not site.get("extra_headers") or "<立即回复>" not in html:
        return html
    m = re.search(r"thread-(\d+)", page_url)
    if not m:
        return html
    import random
    body = {"doctype": "1", "return_html": "0", "quotepid": "",
            "message": random.choice(BBS_REPLY_TEXTS), "quick_reply_message": "4"}
    h = _bbs_headers(site)
    h["X-Requested-With"] = "XMLHttpRequest"
    try:
        site["session"].post(f"{site['url']}/post-create-{m.group(1)}-1.htm",
                             data=body, headers=h, timeout=15)
        html = http_get(site["session"], page_url, timeout=15, headers=_bbs_headers(site))
    except Exception:
        pass
    return html


def page_detail_pans(site, page_url):
    html = _bbs_unlock_and_fetch(site, page_url)
    text = html
    if BeautifulSoup is not None:
        soup = BeautifulSoup(html, "html.parser")
        alerts = soup.select(ALERT_SEL)
        if alerts:
            parts = []
            for al in alerts:
                for a in al.select("a[href]"):
                    href = a.get("href", "")
                    if "/s/" in href or "/t/" in href:
                        parts.append(href + " " + al.get_text(" ", strip=True))
                parts.append(al.get_text(" ", strip=True))
            text = "\n".join(parts) or html
    # 链接+提取码合并为 ?pwd=
    text = re.sub(r"(https?://[^\s\"'<>]+)[\s\S]{0,30}?提取码[\s:：]*([a-zA-Z0-9]{4})",
                  lambda mm: mm.group(1) + "?pwd=" + mm.group(2), text)
    return _extract_pans(text), html


# ---------------------------------------------------------------------------
_SITE_QUARK_COOKIE = ""


def _site_quark_cookie():
    """站点 ext 里手填的夸克 Cookie（全局共享，聚合客户端也要用）。"""
    return _SITE_QUARK_COOKIE


def _local_quark_cookie():
    """读取本地配置中心写入的夸克登录 Cookie（csp_Config 会落到 app files/quark_cookie.txt）。
    找不到就回退空串，快映仍按原来的匿名方式走，不影响其他网盘。
    """
    global _SITE_QUARK_COOKIE
    if _SITE_QUARK_COOKIE:
        return _SITE_QUARK_COOKIE
    cands = []
    for base in (os.getcwd(), os.path.dirname(os.getcwd())):
        cands.append(os.path.join(base, "quark_cookie.txt"))
        cands.append(os.path.join(base, "files", "quark_cookie.txt"))
        # 本地包的配置中心实际写在 filesDir/lzxw/quark_cookie.txt（jar 内 QuarkPan 读的就是这个路径）
        cands.append(os.path.join(base, "lzxw", "quark_cookie.txt"))
        cands.append(os.path.join(base, "files", "lzxw", "quark_cookie.txt"))
    # 本地包配置中心落盘文件名不止一种，全部覆盖（都在同一目录下）
    for _n in ("quark_cookie.txt", "quark.txt", "quark_cookie", "pan_quark.txt",
               "csp_quark_cookie.txt"):
        cands.append(os.path.join(os.getcwd(), "lzxw", _n))
        cands.append(os.path.join(os.getcwd(), "files", "lzxw", _n))
        cands.append(os.path.join(os.path.dirname(os.getcwd()), "files", "lzxw", _n))
    cands += ["/quark_cookie.txt", "/sdcard/quark_cookie.txt",
              "/storage/emulated/0/quark_cookie.txt"]
    # Android 上 /data/user/0 对普通应用不可 listdir，glob 永远拿不到自己的包；
    # 改从 /proc/self 里反推当前包名（本地包的 filesDir 一定能读）
    _pkg_dirs = []
    for _probe in ("/proc/self/cmdline", "/proc/self/maps"):
        try:
            _raw = open(_probe, "rb").read(1024 * 512).decode("utf-8", "ignore")
            for _m in re.finditer(r"/data/(?:user|data)/0/[A-Za-z0-9_.]+", _raw):
                _pkg_dirs.append(_m.group(0))
        except Exception:
            pass
    for _v in ("ANDROID_APP_PATH", "HOME", "ANDROID_DATA"):
        _v = os.environ.get(_v, "")
        if _v:
            _pkg_dirs.append(_v)
    for _pd in sys.path:
        _i = _pd.find("/files/")
        if _i > 0:
            _pkg_dirs.append(_pd[:_i])
    _seen = set()
    for _pd in _pkg_dirs:
        _pd = _pd.rstrip("/")
        if not _pd or _pd in _seen:
            continue
        _seen.add(_pd)
        try:
            cands += glob.glob(_pd + "/files/lzxw/*.json")
            cands += glob.glob(_pd + "/files/*.json")
        except Exception:
            pass
        for _sub in ("/files/lzxw/quark_cookie.txt", "/files/quark_cookie.txt",
                     "/lzxw/quark_cookie.txt", "/quark_cookie.txt"):
            cands.append(_pd + _sub)
    # 常见壳包名兜底（读不到 /data/user/0 目录时也能直接命中自己的私有目录）
    for _pkg in ("com.github.catvod.spider", "com.fongmi.android.tv",
                 "com.fongmi.android.tv.debug", "com.catvod", "com.tvbox"):
        for _root in ("/data/user/0", "/data/data"):
            cands.append(_root + "/" + _pkg + "/files/lzxw/quark_cookie.txt")
            cands.append(_root + "/" + _pkg + "/files/quark_cookie.txt")
        # 配置中心走外部存储时，cookie 常在 Android/data/<包名>/files/lzxw 下
        for _root in ("/sdcard/Android/data", "/storage/emulated/0/Android/data"):
            cands.append(_root + "/" + _pkg + "/files/lzxw/quark_cookie.txt")
            cands.append(_root + "/" + _pkg + "/files/quark_cookie.txt")
    cands += ["/sdcard/lzxw/quark_cookie.txt", "/sdcard/Download/lzxw/quark_cookie.txt",
              "/storage/emulated/0/lzxw/quark_cookie.txt",
              # 跨 App 沙箱读不到本地包私有目录时，用户把 Cookie 放公共目录即可：
              "/sdcard/quark_cookie.txt", "/sdcard/Download/quark_cookie.txt",
              "/sdcard/Documents/quark_cookie.txt", "/sdcard/夸克cookie.txt",
              "/storage/emulated/0/Download/quark_cookie.txt",
              "/storage/emulated/0/Documents/quark_cookie.txt"]
    try:
        cands += glob.glob("/sdcard/Android/data/*/files/lzxw/quark_cookie.txt")
        cands += glob.glob("/storage/emulated/0/Android/data/*/files/lzxw/quark_cookie.txt")
        cands += glob.glob("/sdcard/Android/data/*/files/quark_cookie.txt")
        cands += glob.glob("/sdcard/Android/data/*/files/*/quark_cookie.txt")
        cands += glob.glob("/sdcard/lzxw/*cookie*")
        cands += glob.glob("/sdcard/Download/*quark*cookie*")
        cands += glob.glob("/sdcard/Documents/*quark*cookie*")
    except Exception:
        pass
    try:
        for root in ("/data/user/0", "/data/data"):
            cands += glob.glob(root + "/*/files/lzxw/quark_cookie.txt")
            cands += glob.glob(root + "/*/files/quark_cookie.txt")
    except Exception:
        pass
    # 配置中心也可能把登录态写进 SharedPreferences（XML），最后再扫一遍 quark 相关键
    try:
        for _pd in _pkg_dirs:
            for _xml in glob.glob(_pd.rstrip("/") + "/shared_prefs/*.xml"):
                try:
                    _raw = open(_xml, "r", encoding="utf-8", errors="ignore").read()
                    for _m in re.finditer(r'name="([^"]*quark[^"]*)"[^>]*>([^<]+)<', _raw, re.I):
                        _val = html_lib.unescape(_m.group(2) or "").strip()
                        if "=" in _val and len(_val) >= 20:
                            return _val
                except Exception:
                    continue
    except Exception:
        pass
    for pth in cands:
        try:
            if not pth or not os.path.isfile(pth):
                continue
            txt = open(pth, "r", encoding="utf-8", errors="ignore").read().strip()
            if not txt:
                continue
            try:
                _j = json.loads(txt)
                if isinstance(_j, dict):
                    txt = _dump(_j.get("quark_cookie") or _j.get("cookie") or _j.get("quark") or "")
            except Exception:
                pass
            txt = txt.strip().strip('"').strip("'")
            # 用户用记事本/文件管理器粘贴时经常换行成多行，HTTP Cookie 头不允许换行，
            # 这里统一压成一行：k=v; k=v。同时去掉误粘的 "Cookie:" 前缀和行尾分号。
            try:
                if "\n" in txt or "\r" in txt:
                    _parts = []
                    for _ln in re.split(r"\r?\n", txt):
                        _ln = _ln.strip().strip(";").strip()
                        _ln = re.sub(r"^\s*cookie\s*:\s*", "", _ln, flags=re.I)
                        if _ln and "=" in _ln:
                            _parts.append(_ln)
                    if _parts:
                        txt = "; ".join(_parts)
                txt = re.sub(r"\s*;\s*", "; ", txt).strip(" ;")
            except Exception:
                pass
            if "=" in txt and len(txt) >= 20:
                return txt
        except Exception:
            continue
    return ""


# 聚合 Spider
# ---------------------------------------------------------------------------
class _AggSpider(BaseSpider):
    def getDependence(self):
        return []

    def init(self, extend=""):
        try:
            ext = json.loads(extend) if isinstance(extend, str) and extend else (extend or {})
        except Exception:
            ext = {}
        # 夸克/UC 默认仍走匿名免登；只有「快映」这条线读本地配置中心的夸克登录态
        try:
            globals()["_GLM_KEY"] = str(ext.get("glm_key") or "").strip()
        except Exception:
            pass
        self.uc = UCDrive("")
        self.quark = QuarkDrive("")
        self.quark80 = QuarkDrive(_local_quark_cookie())
        self.pan123 = Pan123()
        # mode："" = 聚合模式；"uc" = UC免登专站；"quark" = 夸克免登专站；
        #        "uc,quark"（也认 "uc+quark" / "uc quark" / "pan"）= UC+夸克双模式专站
        # 按分隔符切成独立词再精确匹配，避免子串误命中（如 "uck" 误开 UC）
        tokens = {x for x in str(ext.get("mode", "")).lower()
                  .replace("+", ",").replace("，", ",").replace(" ", ",").split(",") if x}
        self.mode_pans = set()
        if tokens & {"uc", "pan"}:
            self.mode_pans.add("UC")
        if tokens & {"quark", "pan"}:
            self.mode_pans.add("夸克")
        self.pan_only = bool(self.mode_pans)           # 免登专站（UC 或 UC+夸克）
        self.fast_filter = str(ext.get("fast", "1")) == "1"  # 仅聚合模式"仅UC免登"筛选用；免登专站搜索/推荐恒为强检测
        # 夸克游客直链被服务端按"单连接"限速（实测恒定 0.10MB/s；并发线性叠加：
        # 16→1.2、32→2.4、64→4.6、96→6.5、128→9.2 MB/s），所以用本地并发代理把
        # 单连接限速叠成多连接。accel=0 完全走裸直链；accel_thread 调并发数。
        self.accel_on = str(ext.get("accel", "1")).strip().lower() not in ("0", "false", "no", "off")
        self.proxy = LocalStreamProxy.instance()
        try:
            self.proxy.thread = max(1, min(128, int(ext.get("accel_thread", "96") or 96)))
        except Exception:
            self.proxy.thread = 96
        self._play_cache = {}  # UC/夸克链接有效性缓存 {url: (可播, 时间戳, TTL)}
        self._slow_cache = {}  # 直链"是否被限速"判定缓存 {url: (slow, 时间戳)}
        self._link_cache = {}  # 详情页UC/夸克链接缓存 {real_id: ({kind: [url,...]}, 时间戳)}
        self.sites = {}
        for s in SITES:
            inst = dict(s)
            inst["session"] = make_session()
            ck = ext.get(f"{s['id']}cookie", "")
            if s["type"] == "bbs" and ck:
                inst["extra_headers"] = {"Cookie": ck}
            inst["url"] = s["site"][0]  # 先用首个镜像，真正请求时才懒探测
            self.sites[s["id"]] = inst

    def getName(self):
        if self.mode_pans == {"UC"}:
            return "UC免登"
        if self.mode_pans == {"夸克"}:
            return "夸克免登"
        if self.mode_pans:
            return "UC+夸克免登"
        return "网盘"

    # ---------- UC免登专站：有效性验证 ----------
    UC_SRC = ["木偶", "玩偶", "快映", "剧透"]
    SEARCH_TIMEOUT = 10  # 搜索/分类取候选总时限（秒），慢站直接放弃不再拖全局
    VERIFY_TIMEOUT = 12  # 统一验播时限（秒），时限内验出多少算多少

    @staticmethod
    def _site_dead(site):
        """熔断：探测/请求失败过的站，5 分钟内直接跳过（防止死站每次都拖满超时）"""
        return time.time() < site.get("_dead_until", 0)

    @staticmethod
    def _mark_dead(site, secs=300):
        site["_dead_until"] = time.time() + secs

    def _uc_playable(self, url):
        """强检测：分享未过期 + 能匿名展开出视频 + 匿名直链可取 + CDN 头探测可连。
        可播缓存 6h；不可播只缓存 10 分钟（防网络抖动误杀后长期消失）"""
        ent = self._play_cache.get(url)
        if ent and time.time() - ent[1] < (ent[2] if len(ent) > 2 else 6 * 3600):
            return ent[0]
        ok = False
        try:
            items = self.uc.list_videos(url, limit=1)
            if items:
                it = items[0]
                dl = self.uc.download_url_anon(it["pwd_id"], it["fid"], it["share_fid_token"])
                ok = bool(dl) and self.uc.stream_alive(dl)
        except Exception:
            ok = False
        self._play_cache[url] = (ok, time.time(), 6 * 3600 if ok else 600)
        return ok

    def _quark_playable(self, url):
        """夸克强检测（与 UC 完全对称）：分享未过期 + 匿名展开出视频 + 匿名直链可取 + CDN 头探测可连。
        可播缓存 6h；不可播只缓存 10 分钟（防网络抖动误杀后长期消失）"""
        ent = self._play_cache.get(url)
        if ent and time.time() - ent[1] < (ent[2] if len(ent) > 2 else 6 * 3600):
            return ent[0]
        ok = False
        try:
            items = self.quark.list_videos(url, limit=1)
            if items:
                it = items[0]
                dl = self.quark.download_url_anon(it["pwd_id"], it["fid"], it["share_fid_token"])
                # 不再多跑一次 CDN 头探测：播放时代理有 412 自愈刷新兜底，这里省 ~0.5-1s/候选
                ok = bool(dl)
        except Exception:
            ok = False
        self._play_cache[url] = (ok, time.time(), 6 * 3600 if ok else 600)
        return ok

    def _playable(self, url, kind):
        """按网盘类型走对应的强检测"""
        return self._quark_playable(url) if kind == "夸克" else self._uc_playable(url)

    def _vod_pan_links(self, site, real_id):
        """取某条目的 UC / 夸克 分享链接（30 分钟缓存）=> {"UC":[...], "夸克":[...]}"""
        ent = self._link_cache.get(real_id)
        if ent and time.time() - ent[1] < 1800:
            return ent[0]
        try:
            t = site["type"]
            if t in ("pansou", "mipan", "qupan", "jike"):
                # 链接型站点：vod_id 本身就是分享链接，直接判类型即可，别再当网页去抓
                links = {"UC": [], "夸克": []}
                for kind, rx in PAN_RES:
                    if kind in ("UC", "夸克") and rx.search(real_id):
                        links[kind].append(real_id)
            elif t == "kkpan":
                pans, _ = kkpan_detail(site, real_id)
                links = {"UC": pans.get("UC") or [], "夸克": pans.get("夸克") or []}
            elif t in ("webshare", "wogg"):
                pans, _ = maccms_detail_pans(site, real_id)
                links = {"UC": pans.get("UC") or [], "夸克": pans.get("夸克") or []}
            elif t == "aipan":
                pans, _ = aipan_detail(site, real_id)
                links = {"UC": pans.get("UC") or [], "夸克": pans.get("夸克") or []}
            else:
                pans, _ = page_detail_pans(site, real_id)
                links = {"UC": pans.get("UC") or [], "夸克": pans.get("夸克") or []}
        except Exception:
            links = {"UC": [], "夸克": []}
        self._link_cache[real_id] = (links, time.time())
        return links

    def _verify_pan(self, site, vods, check_play=True, kinds=("UC",)):
        """只留带（UC/夸克）免登链接的条目；check_play 时进一步验证分享未过期能播"""
        def work(v):
            all_links = self._vod_pan_links(site, v["vod_id"])
            links = []
            for k in kinds:
                links += all_links.get(k) or []
            if not links:
                return False
            if not check_play:
                return True
            # 逐网盘类型试：任一类型能播即算可播
            for k in kinds:
                for u in (all_links.get(k) or [])[:2]:
                    if self._playable(u, k):
                        return True
            return False
        with ThreadPoolExecutor(max_workers=16) as ex:
            keep = list(ex.map(work, vods))
        return [v for v, k in zip(vods, keep) if k]

    def _verify_uc(self, site, vods, check_play=True):
        """只留带 UC 链接的条目；check_play 时进一步验证分享未过期能播"""
        return self._verify_pan(site, vods, check_play=check_play, kinds=("UC",))

    def _verify_mixed(self, vods, check_play=True, timeout=VERIFY_TIMEOUT, workers=16):
        """跨站统一验 UC（vods 需带 _sid0 标记站源）。
        旧做法是每个站各自起一个线程池顺序验，慢站会把整轮拖满；
        这里全候选共享一个池 + 全局时限，as_completed 先验完先出，超时直接收尾"""
        out = []
        kinds = tuple(sorted(self.mode_pans)) if self.mode_pans else ("UC",)
        # 每条候选的强检测次数随网盘类型数线性增长（每类型最多试 2 条链接），
        # 双模式时限同步放大，避免验不完被整体超时砍掉、结果偏少
        timeout = timeout * max(1, len(kinds))
        def work(v):
            site = self.sites.get(v.get("_sid0", ""))
            if not site:
                return None
            try:
                all_links = self._vod_pan_links(site, v["vod_id"])
                links = []
                for k in kinds:
                    links += all_links.get(k) or []
                if not links:
                    return None
                if not check_play:
                    return v
                for k in kinds:
                    for u in (all_links.get(k) or [])[:2]:
                        if self._playable(u, k):
                            return v
                return None
            except Exception:
                return None
        ex = ThreadPoolExecutor(max_workers=workers)
        try:
            futs = [ex.submit(work, v) for v in vods]
            for f in as_completed(futs, timeout=timeout):
                try:
                    r = f.result()
                    if r is not None:
                        out.append(r)
                except Exception:
                    pass
        except Exception:
            pass  # as_completed 超时抛 TimeoutError，已验出的照出
        finally:
            ex.shutdown(wait=False)
        return out

    def isVideoFormat(self, url):
        return url.lower().endswith(VIDEO_EXT)

