def _nd_norm(s):
    s = re.sub(r"[\s:：·\-—_（）()\[\]【】《》]+", "", _dump(s)).lower()
    s = re.sub(r"(19|20)\d{2}", "", s)
    s = re.sub(r"第[0-9一二三四五六七八九十]+[季部]", "", s)
    s = re.sub(r"(全|共)?\d+集", "", s)
    s = re.sub(r"(更新至|更|完结|全集|高清|4k|60帧)+", "", s)
    return s


def _nd_groups(d):
    """把聚合详情拆成可播线路；过滤 kk 令牌和虚假直链，直连页改嗅探。"""
    out = []
    for f, u in zip(_dump(d.get("vod_play_from")).split("$$$"),
                    _dump(d.get("vod_play_url")).split("$$$")):
        f, u = _dump(f), _dump(u)
        if not f or not u or "提示" in f:
            continue
        eps = [e for e in u.split("#") if e]
        toks = [e.split("$")[-1] for e in eps]
        if not eps:
            continue
        for t in toks:
            _raw = re.sub(r"agg:(?:直连|嗅探|解析)\|", "", t)
            if not (_raw.startswith("http") or _raw.startswith("Q~") or _raw.startswith("BD~") or "+" in _raw):
                eps = []
                break
        if not eps:
            continue
        # 有 UC/夸克/123 多集令牌的线路优先；只有站点详情页的也保留，交给壳解析/嗅探
        _real = any(t.startswith("Q~") or t.startswith("BD~") or ("+" in t and not t.startswith("http")) for t in toks)
        if not _real:
            if not all(t.startswith("http") for t in toks):
                continue
            if "百度" not in f:
                if "直连" in f:
                    f = f.replace("直连", "解析")
                elif not ("解析" in f or "嗅探" in f):
                    f = "解析"
                if len(eps) == 1:
                    f = "单视频·解析"
        score = 3 if _real else 1
        tag = ("嗅探" if "嗅探" in f else
               "解析" if "解析" in f else
               "直连" if "直连" in f else "")
        if tag:
            # Q~/BD~ 是自家代理能直接处理的令牌，别再包成 agg:解析| 让壳当外链去解析
            eps = [e.partition("$")[0] + "$" + "agg:%s|%s" % (tag, e.partition("$")[2])
                   if e.partition("$")[1] and not e.partition("$")[2].startswith(("agg:", "Q~", "BD~")) else e
                   for e in eps]
        u = "#".join(eps)
        out.append((score, len(eps), f, u))
    return out


def _nd_pan(f):
    """从网盘线名识别夸克/百度/UC/阿里/迅雷，用于同站多盘线路并出。"""
    s = _dump(f).lower()
    for k in ("夸克", "百度", "uc", "阿里", "迅雷", "123", "天翼", "移动", "联通"):
        if k in s:
            return {"uc": "UC"}.get(k, k)
    return "网盘"


def _nd_norm_line(f, u):
    """清洗胶囊网盘线的 “线名#1 / 1$令牌” 格式，并合并成一条正常线。"""
    # 只清线名里的 “#1”；URL 里每集的 “1$令牌” 是选集标签，必须保留
    base = (f or "").split("#")[0].strip()
    eps = [e for e in (u or "").split("#") if e.strip()]
    return base, "#".join(eps)


def _nd_key(s):
    """网盘候选匹配用的宽松片名：去括号内容、年份、季集后缀。"""
    s = _dump(s)
    s = re.sub(r"[（(\[【][^）)\]】]*[）)\]】]", " ", s)
    s = re.sub(r"(?:19|20)\d{2}", " ", s)
    s = re.sub(r"[ 　]*(全季|全集|完结|年番\d*|第[一二三四五六七八九十0-9]+季|S\d+.*)$",
               "", s, flags=re.I)
    return _nd_norm(s)


def _nd_search_budget(key, seconds=5.0):
    """网盘白名单站一个个按顺序搜：木偶 → 玩偶 → 剧透 → 快映，
    不再同时并发；白名单以外的站已全部删除。"""
    ob = _agg_client()
    if not ob:
        return []
    ids = ("玩偶", "木偶", "快映", "剧透")
    targets = [s for s in ob.sites.values()
               if s.get("id") in ids and not ob._site_dead(s)]
    if not targets:
        return []
    def do(site):
        _ensure_url(site)
        try:
            vods = ob._site_search(site, key, "1")
        except Exception:
            if site.get("id") != "玩偶":
                ob._mark_dead(site)
            return []
        for v in vods:
            v["vod_id"] = f"{site['id']}@{v['vod_id']}"
            v["vod_remarks"] = f"{site['id']} | {v.get('vod_remarks', '')}".strip(" |")
        return vods[:12]
    deadline = time.time() + max(1.0, seconds)
    out = []
    for i, site in enumerate(targets):
        _rem = deadline - time.time()
        if _rem < 0.6:
            break
        # 每个站单独一轮，单站最多 5.5 秒；不再“首个站命中就停”，
        # 否则快映永远排不到，详情里就只剩木偶一条网盘线
        if _nd_site_down(site.get("id")):
            continue
        _got = ob._run_parallel([site], do, min(4.5, _rem))
        if _got:
            _ND_EMPTY[site.get("id")] = 0
            _ND_DOWN.pop(site.get("id"), None)
        else:
            _sid = site.get("id")
            _ND_EMPTY[_sid] = _ND_EMPTY.get(_sid, 0) + 1
            # 连续两次整站空响应，先冷却 10 分钟，别每次都拖 4.5 秒
            # 玩偶走 Cloudflare，偶发 403 很常见，不能因为两次空响应就冷却 10 分钟，
            # 否则用户等一会儿再搜，玩偶已经被整站跳过，看起来就是“搜不了”。
            if _ND_EMPTY[_sid] >= 2 and _sid == "剧透":
                _ND_DOWN[_sid] = time.time() + 600
        out.extend(_got)
    return out


_ND_WARMING = set()
_ND_EMPTY = {}
_ND_DOWN = {}

def _nd_site_down(sid):
    try:
        return _ND_DOWN.get(_dump(sid), 0) > time.time()
    except Exception:
        return False

