def _qw_clean(s):
    return re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "",
                                    html_lib.unescape(_dump(s)))).strip()


def _qw_text(path, timeout=9):
    """七味站点单域名经常 503/半截页；多域名并发，先拿到完整页的直接用。"""
    def one(h):
        u = "https://%s%s" % (h, path)
        try:
            t = _dump(_http_text(u, {"User-Agent": UA, "Referer": "https://%s/" % h}, timeout))
            if not t:
                return ""
            if t.startswith("{"):
                return t
            if len(t) >= 4000 and (t.rstrip().endswith("</html>") or "<ul class=\"player\">" in t):
                return t
        except Exception:
            pass
        return ""

    from concurrent.futures import ThreadPoolExecutor as _TPE, as_completed as _asc
    ex = _TPE(max_workers=len(QW_HOSTS))
    futs = [ex.submit(one, h) for h in QW_HOSTS]
    try:
        for f in _asc(futs, timeout=max(2.0, min(float(timeout), 20.0) + 1.0)):
            try:
                t = f.result()
            except Exception:
                continue
            if t:
                return t
    except Exception:
        pass
    finally:
        try:
            ex.shutdown(wait=False, cancel_futures=True)
        except TypeError:
            ex.shutdown(wait=False)
    return ""

