def _xl_refresh(auth):
    """用配置中心 xunlei.txt 里的 refresh_token 续期，避免 2 小时后掉登录。"""
    rt = _dump((auth or {}).get("refresh"))
    if not rt:
        return {}
    try:
        body = json.dumps({"client_id": XL_CLIENT_ID, "grant_type": "refresh_token",
                           "refresh_token": rt}, ensure_ascii=False, separators=(",", ":"))
        txt = _http_post("https://xluser-ssl.xunlei.com/v1/auth/token", body, timeout=12,
                         headers={"User-Agent": XL_UA, "Referer": "https://pan.xunlei.com/",
                                  "Origin": "https://pan.xunlei.com",
                                  "x-client-id": XL_CLIENT_ID,
                                  "x-client-version": XL_CLIENT_VER,
                                  "x-device-id": _xl_device()})
        obj = json.loads(txt or "{}")
        if not isinstance(obj, dict) or obj.get("error"):
            return {}
        tok = _dump(obj.get("access_token"))
        if not tok:
            return {}
        out = dict(auth or {})
        out.update({"token": tok, "type": _dump(obj.get("token_type") or "Bearer"),
                    "refresh": _dump(obj.get("refresh_token") or rt),
                    "expired": False})
        return out
    except Exception:
        return {}


XL_LAST_ERR = [""]


def _xl_user_ok(auth):
    """校验配置里的 access_token 是否还有效；过期 token 会让转存/取址直接 401。"""
    tok = _dump((auth or {}).get("token"))
    if not tok:
        return False
    try:
        _http_text("https://xluser-ssl.xunlei.com/v1/user/me",
                   headers={"Authorization": (_dump(auth.get("type")) or "Bearer") + " " + tok,
                            "User-Agent": XL_UA}, timeout=8)
        return True
    except urllib.error.HTTPError as e:
        return False if getattr(e, "code", 0) in (401, 403) else None
    except Exception as e:
        # 宿主 net 抛出来的错误没有 code，无法判断就先放行，让转存自己报
        return False if "401" in str(e) or "403" in str(e) else None


def _xl_auth():
    """惰性读取配置中心 xunlei.txt；换号后最多一分钟生效。"""
    global XL_AUTH
    try:
        if time.time() - XL_AUTH_AT[0] < 60 and XL_AUTH is not None:
            return XL_AUTH
        auth = _cfg_xunlei() or {}
        if auth.get("expired"):
            auth = _xl_refresh(auth) or {}
        XL_AUTH = auth
        # 取到 token 缓存一分钟；没取到只缓存 5 秒，用户刚登录完重点一次就能生效
        XL_AUTH_AT[0] = time.time() if auth.get("token") else time.time() - 55
    except Exception:
        XL_AUTH = {}
    return XL_AUTH


def _xl_device():
    auth = _xl_auth()
    dev = _dump((auth or {}).get("device"))
    if re.fullmatch(r"[0-9a-zA-Z]{16,64}", dev or ""):
        return dev
    # 没登录时也要一个稳定设备号，否则每次详情都换新设备会触发风控
    return hashlib.md5(("douban-xunlei-" + _dump((auth or {}).get("token"))[-12:]).encode()).hexdigest()


def _xl_captcha(action, force=False):
    """迅雷盾 captcha token。当前公开客户端算法，匿名也能取。"""
    key = "XL_CAP:%s" % action
    now = int(time.time())
    with XL_CAP_LOCK:
        hit = XL_CAP.get(action)
        if not force and hit and hit[0] > now + 5:
            return hit[1]
    ts = str(int(time.time() * 1000))
    dev = _xl_device()
    s = XL_CLIENT_ID + XL_CLIENT_VER + XL_PKG + dev + ts
    for alg in XL_ALGS:
        s = hashlib.md5((s + alg).encode("utf-8")).hexdigest()
    body = json.dumps({
        "action": action, "captcha_token": "", "client_id": XL_CLIENT_ID,
        "device_id": dev,
        "meta": {"client_version": XL_CLIENT_VER, "package_name": XL_PKG,
                 "user_id": "", "timestamp": ts, "captcha_sign": "1." + s},
        "redirect_uri": "xlaccsdk01://xunlei.com/callback?state=harbor",
    }, ensure_ascii=False, separators=(",", ":"))
    head = {"user-agent": XL_UA, "accept": "application/json;charset=UTF-8",
            "x-device-id": dev, "x-client-id": XL_CLIENT_ID,
            "x-client-version": XL_CLIENT_VER,
            "content-type": "application/json", "referer": "https://pan.xunlei.com/",
            "origin": "https://pan.xunlei.com"}
    auth = _xl_auth()
    if auth.get("token"):
        head["authorization"] = "Bearer " + auth["token"]
    try:
        txt = _http_post("https://xluser-ssl.xunlei.com/v1/shield/captcha/init",
                         body, timeout=12, headers=head)
        obj = json.loads(txt)
        tok = _dump(obj.get("captcha_token"))
        if tok:
            try:
                ttl = int(obj.get("expires_in") or 300)
            except Exception:
                ttl = 300
            with XL_CAP_LOCK:
                XL_CAP[action] = (now + max(30, ttl - 20), tok)
            return tok
    except Exception:
        pass
    return ""


