_APP_PROXY = {"base": ""}
_GO5266 = {"ok": None, "at": 0.0}


def _go5266_ok():
    """本地包的 5266 Go 代理；Java F.a.a() 能播时就是走这条。"""
    now = time.time()
    if _GO5266["ok"] is not None and now - _GO5266["at"] < 60:
        return _GO5266["ok"]
    ok = False
    try:
        import urllib.request
        with urllib.request.urlopen("http://127.0.0.1:5266/api/ping", timeout=1.2) as r:
            ok = (r.read() or b"").decode("utf-8", "ignore").strip().lower() == "ok"
    except Exception:
        ok = False
    _GO5266["ok"], _GO5266["at"] = ok, now
    return ok


def _app_proxy_base():
    """复用本地包运行中的 /proxy 服务（9978~9999）。
    本地包的迅雷线路能播，说明它自己的 X.q()+Pan.proxy 链路是通的；
    直接把播放交给它，比我们在 py 里再实现一遍可靠。"""
    if _APP_PROXY["base"]:
        return _APP_PROXY["base"]
    # 端口扫描必须并发且短超时：串行扫 22 个端口会把播放请求拖到 20 秒以上，
    # 播放器先超时，表现就是“一点就播放失败”。
    import urllib.request
    import concurrent.futures as _cf

    def _ck(port):
        try:
            u = "http://127.0.0.1:%d/proxy?do=ck" % port
            with urllib.request.urlopen(u, timeout=0.6) as r:
                if (r.read() or b"").decode("utf-8", "ignore").strip().lower() == "ok":
                    return "http://127.0.0.1:%d/proxy" % port
        except Exception:
            return ""
        return ""

    _ex = _cf.ThreadPoolExecutor(max_workers=22)
    try:
        _futs = [_ex.submit(_ck, p) for p in range(9978, 10000)]
        for _f in _cf.as_completed(_futs, timeout=2.5):
            try:
                _b = _f.result()
            except Exception:
                _b = ""
            if _b:
                _APP_PROXY["base"] = _b
                return _b
    finally:
        _ex.shutdown(wait=False)
    return ""


class XunleiDrive:
    """迅雷分享：匿名列目录；配置中心登录后转存到临时目录，取逐集直链。"""
    BASE = "https://api-pan.xunlei.com"
    VIDEO_EXT = tuple(x.lower() for x in VIDEO_EXT)
    CLEAN_DELAY = 3

    def parse(self, share_url):
        u = _dump(share_url)
        m = re.search(r"pan\.xunlei\.com/s/([\w\-]+)", u)
        if not m:
            return "", ""
        sid = m.group(1)
        pm = re.search(r"[?&]pwd=([\w]+)", u)
        return sid, (pm.group(1) if pm else "")

    def _headers(self, action):
        auth = _xl_auth()
        h = {"user-agent": XL_UA, "accept": "application/json;charset=UTF-8",
             "x-device-id": _xl_device(), "x-client-id": XL_CLIENT_ID,
             "x-client-version": XL_CLIENT_VER,
             "referer": "https://pan.xunlei.com/", "origin": "https://pan.xunlei.com"}
        tok = _xl_captcha(action)
        if tok:
            h["x-captcha-token"] = tok
        if auth.get("token"):
            h["authorization"] = (_dump(auth.get("type")) or "Bearer") + " " + auth["token"]
        return h

    def _json(self, method, path, action, query=None, body=None):
        url = self.BASE + path
        if query:
            url += ("&" if "?" in url else "?") + urlencode(query)
        headers = self._headers(action)
        if method == "POST":
            txt = _http_post(url, json.dumps(body or {}, ensure_ascii=False,
                                            separators=(",", ":")), timeout=15,
                             headers=headers)
        else:
            txt = _http_text(url, headers=headers, timeout=15)
        try:
            return json.loads(txt or "{}")
        except Exception:
            return {}

    def _detail(self, sid, parent_id, pass_token, page=""):
        j = self._json("GET", "/drive/v1/share/detail",
                       "GET:/drive/v1/share/detail",
                       {"share_id": sid, "parent_id": parent_id,
                        "pass_code_token": pass_token, "limit": "100",
                        "page_token": page, "thumbnail_size": "SIZE_SMALL"})
        return j

    def open_share(self, share_url, limit=500):
        sid, pwd = self.parse(share_url)
        if not sid:
            return {"items": [], "root_ids": [], "pass_token": ""}
        j = self._json("GET", "/drive/v1/share", "GET:/drive/v1/share",
                       {"share_id": sid, "pass_code": pwd, "limit": "100",
                        "pass_code_token": "", "page_token": "",
                        "thumbnail_size": "SIZE_SMALL"})
        if _dump(j.get("share_status")) != "OK":
            return {"items": [], "root_ids": [], "pass_token": ""}
        pass_token = _dump(j.get("pass_code_token"))
        items = []
        root_ids = []

        def walk(pid, depth, token, page=""):
            if depth > 5 or len(items) >= limit:
                return
            k = self._detail(sid, pid, token, page)
            files = k.get("files") or []
            for it in files:
                if len(items) >= limit:
                    break
                name = _dump(it.get("name"))
                isdir = _dump(it.get("kind")) == "drive#folder"
                if isdir:
                    root_ids.append(_dump(it.get("id"))) if depth == 0 else None
                    walk(_dump(it.get("id")), depth + 1, token)
                elif name.lower().endswith(self.VIDEO_EXT):
                    items.append({"file_name": name, "id": _dump(it.get("id")),
                                  "size": int(it.get("size") or 0),
                                  "web_content_link": _dump(it.get("web_content_link"))})
            nxt = _dump(k.get("next_page_token"))
            if nxt and len(items) < limit:
                walk(pid, depth, token, nxt)

        files = j.get("files") or []
        for it in files:
            name = _dump(it.get("name"))
            isdir = _dump(it.get("kind")) == "drive#folder"
            if isdir:
                root_ids.append(_dump(it.get("id")))
                walk(_dump(it.get("id")), 1, pass_token)
            elif name.lower().endswith(self.VIDEO_EXT):
                items.append({"file_name": name, "id": _dump(it.get("id")),
                              "size": int(it.get("size") or 0),
                              "web_content_link": _dump(it.get("web_content_link"))})
        return {"items": items, "root_ids": root_ids, "pass_token": pass_token,
                "share_id": sid}

    def _mkdir(self, name):
        j = self._json("POST", "/drive/v1/files", "POST:/drive/v1/files", body={
            "kind": "drive#folder", "name": name, "parent_id": "", "space": ""})
        data = j.get("data")
        for obj in (j.get("file"), data.get("file") if isinstance(data, dict) else None, j):
            if isinstance(obj, dict) and _dump(obj.get("id")):
                return _dump(obj.get("id"))
        return ""

    def _restore(self, sid, pass_token, root_ids, parent_id):
        j = self._json("POST", "/drive/v1/share/restore",
                       "POST:/drive/v1/share/restore", body={
                           "parent_id": parent_id, "share_id": sid,
                           "pass_code_token": pass_token, "ancestor_ids": [],
                           "file_ids": root_ids, "specify_parent_id": True,
                           "params": {"trace_file_ids": (root_ids[0] if root_ids else "")}})
        err = j.get("error") if isinstance(j, dict) else None
        if err:
            XL_LAST_ERR[0] = "转存接口报错：" + _dump(err)[:90]
            return []
        tid = _dump(j.get("restore_task_id") or j.get("task_id"))
        if not tid:
            XL_LAST_ERR[0] = "转存没返回任务ID：" + _dump(j)[:90]
            return []
        for _ in range(30):
            k = self._json("GET", "/drive/v1/tasks/" + tid,
                           "GET:/drive/v1/tasks/" + tid)
            if _dump(k.get("phase")).upper() == "PHASE_TYPE_COMPLETE":
                break
            try:
                if int(k.get("progress") or 0) >= 100:
                    break
            except Exception:
                pass
            time.sleep(0.4)
        ids = []
        params = k.get("params") if isinstance(k, dict) else {}
        raw = _dump((params or {}).get("trace_file_ids"))
        if raw:
            try:
                v = json.loads(raw)
                if isinstance(v, list):
                    ids = [_dump(x) for x in v if _dump(x)]
                elif isinstance(v, dict):
                    ids = [_dump(x) for x in v.values() if _dump(x)]
            except Exception:
                pass
        if not ids:
            for key in ("file_ids", "trace_file_ids"):
                v = (params or {}).get(key)
                if isinstance(v, list):
                    ids = [_dump(x) for x in v if _dump(x)]
                elif _dump(v) and not _dump(v).startswith(("[", "{")):
                    ids = [_dump(v)]
        if not ids:
            ids = [_dump(k.get("file_id"))] if _dump(k.get("file_id")) else []
        if not ids:
            XL_LAST_ERR[0] = "任务完成但没有文件ID：" + _dump(k)[:90]
        return ids

    def _children(self, parent_id):
        j = self._json("GET", "/drive/v1/files", "GET:/drive/v1/files",
                       {"parent_id": parent_id, "limit": "100",
                        "thumbnail_size": "SIZE_SMALL"})
        return j.get("files") or []

    def _link(self, fid):
        # 本地包 X.F() 的取址参数：_magic=2021，且不带 space
        j = self._json("GET", "/drive/v1/files/" + fid,
                       "GET:/drive/v1/files/" + fid,
                       {"_magic": "2021", "usage": "PLAY", "thumbnail_size": "SIZE_LARGE"})
        link = _dump(j.get("web_content_link"))
        if link:
            return link
        for md in (j.get("medias") or []):
            for k in ("link", "url"):
                v = md.get(k) if isinstance(md, dict) else None
                if isinstance(v, dict):
                    v = v.get("url")
                if _dump(v):
                    return _dump(v)
        XL_LAST_ERR[0] = "取直链为空：" + _dump(j)[:90]
        for v in (j.get("links") or {}).values():
            if isinstance(v, list) and v:
                v = v[0]
            if isinstance(v, dict):
                v = v.get("url")
            if _dump(v):
                return _dump(v)
        return ""

    def _clean(self, ids):
        try:
            self._json("POST", "/drive/v1/files:batchDelete",
                       "POST:/drive/v1/files:batchDelete",
                       body={"ids": ids, "space": ""})
        except Exception:
            pass

    def _clean_later(self, temp_id, restored):
        ids = [temp_id] if temp_id else restored
        if not ids:
            return
        try:
            t = threading.Timer(self.CLEAN_DELAY, self._clean, args=(ids,))
            t.daemon = True
            t.start()
        except Exception:
            pass

    def split(self, share_url):
        """按本地包的做法：只匿名列出分享里的逐集文件，播放时再单集转存。
        这样详情页不需要把整剧转存进账号，也不会生成临时目录。"""
        info = self.open_share(share_url)
        items = info.get("items") or []
        if len(items) < 2:
            return []
        out = []
        for it in items:
            fid = _dump(it.get("id"))
            name = _dump(it.get("file_name") or it.get("name"))
            if not fid or not name:
                continue
            out.append({"file_name": name, "size": int(it.get("size") or 0),
                        "_xlmeta": {"s": info.get("share_id"), "t": info.get("pass_token"),
                                    "f": fid, "n": name, "u": share_url}})
        return out

    def play_episode(self, meta):
        """本地包 proxy 确认可用时优先交给它；否则走 py 自己的单集转存。"""
        share = _dump((meta or {}).get("u"))
        sid0 = _dump((meta or {}).get("s"))
        fid0 = _dump((meta or {}).get("f"))
        base = _app_proxy_base()

        def local_proxy():
            if not (base and sid0 and fid0):
                return ""
            pm = re.search(r"[?&]pwd=([\w]+)", share)
            pwd = pm.group(1) if pm else ""
            return (base + "?do=pan&site=xunlei&shareId=" + quote(sid0, safe="")
                    + "&fileId=" + quote(fid0, safe="") + "&fileToken=" + quote(pwd, safe=""))

        # 本地包自己能播，且 do=ck 已确认是它的 proxy：直接复用它的完整链路。
        if base:
            return local_proxy()

        auth = _xl_auth()
        if not auth.get("token"):
            XL_LAST_ERR[0] = "配置中心未读到迅雷 token"
            return local_proxy()
        if _xl_user_ok(auth) is False:
            auth = _xl_refresh(auth) or {}
            if not auth.get("token") or _xl_user_ok(auth) is False:
                global XL_AUTH, XL_AUTH_AT
                XL_AUTH = {}
                XL_AUTH_AT[0] = 0
                XL_LAST_ERR[0] = "迅雷登录已失效，请重新登录"
                return local_proxy()
            XL_AUTH = auth
            XL_AUTH_AT[0] = time.time()
        sid = sid0
        pt = _dump((meta or {}).get("t"))
        fid = fid0
        if not sid or not fid:
            return local_proxy()
        # 本地包 X.q() 播放时会用 pwd 重新换一次 pass_code_token。
        # 详情页缓存的旧 token 可能已经过期，直接拿去 restore 会失败。
        if share:
            try:
                fresh = self.open_share(share)
                sid = _dump(fresh.get("share_id")) or sid
                pt = _dump(fresh.get("pass_token")) or pt
            except Exception as e:
                XL_LAST_ERR[0] = "刷新分享令牌失败：" + str(e)[:60]
                return local_proxy()
        try:
            restored = self._restore(sid, pt, [fid], "")
        except Exception as e:
            restored = []
            XL_LAST_ERR[0] = "转存异常：" + str(e)[:80]
        if not restored:
            XL_LAST_ERR[0] = XL_LAST_ERR[0] or "转存任务未完成"
            return local_proxy()
        for rid in restored:
            link = self._link(rid)
            if link:
                self._clean_later(None, [rid])
                # 本地包 F.a.a()：5266 活着时直接交给它的 Go 代理，播放头由它补。
                if _go5266_ok():
                    return "http://127.0.0.1:5266?url=%s&thread=10" % quote(link, safe="")
                # 部分壳会丢掉 play_content 返回的 header，直链就会 403/转圈。
                # 这里走本机代理，把迅雷播放头在代理里补上，播放器只连 127.0.0.1。
                try:
                    port = _bd_proxy_start()
                    if port:
                        return "http://127.0.0.1:%d/x.mp4?site=xunlei&u=%s" % (
                            port, quote(link, safe=""))
                except Exception:
                    pass
                return link
        XL_LAST_ERR[0] = "转存后取直链为空"
        return local_proxy()

def _qw_ep_numbers(items):
    """从文件名里提取集号，判断分享是不是从第 1 集开始的连续整剧。"""
    nums = []
    for it in items or []:
        base = re.sub(r"\.[a-zA-Z0-9]{2,4}$", "",
                      _dump(it.get("file_name") or it.get("name"))).strip()
        n = None
        for rx in (r"[Ss]\d{1,2}[Ee](\d{1,3})", r"\b[Ee][Pp]?(\d{1,3})\b",
                   r"第\s*(\d{1,3})\s*[集期话回]", r"^0*(\d{1,3})\s*(?:[^0-9A-Za-z]|$)",
                   r"\[(\d{1,3})\]") :
            mm = re.search(rx, base)
            if mm:
                try:
                    n = int(mm.group(1))
                    break
                except Exception:
                    pass
        if n is not None:
            nums.append(n)
    return nums


def _qw_complete_share(items):
    """至少两集；有集号时必须从 1 开始且中间不缺集，才当作完整剧展开。"""
    if len(items or []) < 2:
        return False
    nums = _qw_ep_numbers(items)
    if not nums:
        return True
    uniq = sorted(set(nums))
    if not uniq or uniq[0] > 1:
        return False
    return uniq[-1] - uniq[0] + 1 == len(uniq)


def _qw_split_share(share_url):
    """把一个整剧网盘分享展开成逐集播放串；列不出目录的网盘返回 []。"""
    u = _dump(share_url)
    if not u:
        return []
    kind = ""
    items = []
    drive = None
    try:
        if re.search(r"https?://pan\.quark\.cn/s/", u):
            kind = "quark"
            items = QuarkDrive("").list_videos(u, limit=500)
        elif re.search(r"https?://drive\.uc\.cn/s/", u):
            kind = "uc"
            drive = UCDrive("")
            items = drive.list_videos(u, limit=500)
        elif re.search(r"https?://pan\.baidu\.com/s/", u):
            kind = "baidu"
            items = BaiduDrive(BD_COOKIE or "").walk(u, limit=500)
        elif re.search(r"https?://(?:www\.)?(?:123pan|123684|123865|123912|123592)\.(?:com|cn)/s/", u):
            kind = "123"
            items = Pan123().list_videos(u)
        elif re.search(r"https?://pan\.xunlei\.com/s/", u):
            kind = "xunlei"
            items = XunleiDrive().split(u)
    except Exception:
        return []
    if not items:
        return []
    # 只有“能确认是完整剧”的分享才拆集；单文件、缺集、从第 11 集开始
    # 这类都不硬拆，让上层回退成整剧，避免出现 20 集/1 集假线路。
    if not _qw_complete_share(items):
        return []
    if kind == "uc" and drive:
        # UC 每条直链都要单独请求一次，串行 30 集要 9 秒；并发取完再拼
        try:
            from concurrent.futures import ThreadPoolExecutor as _TPE
            with _TPE(max_workers=8) as _ex:
                _dls = list(_ex.map(
                    lambda x: drive.download_url_anon(x.get("pwd_id", ""), x.get("fid", ""),
                                                      x.get("share_fid_token", "")), items))
            for _it, _dl in zip(items, _dls):
                _it["_qwd"] = _dl
        except Exception:
            pass

    # 同一集常同时存在 4K/高码/重复副本：按集号去重，优先体积大的那份
    def _num(fname):
        base = re.sub(r"\.[a-zA-Z0-9]{2,4}$", "", fname or "").strip()
        for rx in (r"[Ss]\d{1,2}[Ee](\d{1,3})", r"\b[Ee][Pp]?(\d{1,3})\b",
                   r"第\s*(\d{1,3})\s*[集期话回]", r"^0*(\d{1,3})\s*(?:[^0-9A-Za-z]|$)",
                   r"\[(\d{1,3})\]"):
            mm = re.search(rx, base)
            if mm:
                try:
                    return int(mm.group(1))
                except Exception:
                    pass
        return None
    rows = []
    for i, it in enumerate(items):
        fname = _dump(it.get("file_name") or it.get("name"))
        if not fname:
            continue
        rows.append((_num(fname), i, int(it.get("size") or 0), fname, it))
    best = {}
    unknown = []
    for num, i, size, fname, it in rows:
        if num is None:
            unknown.append((i, size, fname, it))
            continue
        old = best.get(num)
        if old is None or size > old[0] or (size == old[0] and len(fname) < len(old[2])):
            best[num] = (size, fname, it)
    final = [best[k] for k in sorted(best)]
    for _, size, fname, it in sorted(unknown, key=lambda x: x[0]):
        final.append((size, fname, it))
    rows = final

    eps = []
    for i, (size, fname, it) in enumerate(rows):
        label = str(i + 1)
        if kind == "quark":
            tok = "Q~%s__%s+%s+%s" % (fname, it.get("fid", ""), it.get("pwd_id", ""),
                                      it.get("share_fid_token", ""))
        elif kind == "uc":
            # UC 的匿名 download 只在同一实例列完目录后有效，这里直接固化成直链；
            # 用 UW~ 前缀单独走带 Referer 的直连分支，避免播放时新进程重新握手拿不到链接。
            dl = _dump(it.get("_qwd"))
            if not dl:
                continue
            tok = "UW~" + base64.urlsafe_b64encode(dl.encode("utf-8")).decode("ascii").rstrip("=")
        elif kind == "baidu":
            tok = "BD~" + quote(json.dumps({"u": u, "p": it.get("path", ""),
                                            "f": it.get("fs_id", "")}, ensure_ascii=False), safe="")
        elif kind == "123":
            dl = _dump(it.get("download_url"))
            if not dl:
                continue
            tok = "%s__%s+%s+%s+%s+%s" % (fname, it.get("file_id", ""), it.get("etag", ""),
                                          it.get("s3key", ""), size, quote(dl, safe=""))
        elif kind == "xunlei":
            meta = it.get("_xlmeta")
            if not isinstance(meta, dict) or not _dump(meta.get("f")):
                continue
            raw = json.dumps(meta, ensure_ascii=False, separators=(",", ":"))
            tok = "XU~" + base64.urlsafe_b64encode(raw.encode("utf-8")).decode("ascii").rstrip("=")
        else:
            continue
        eps.append("%s$%s" % (label, tok))
    return eps


def _qw_pan_lines(name):
    """按片名去七味取网盘下载区块，每家网盘只保留一个最优整剧分享。
    七味同一家网盘往往挂几十条重复的“整剧分享”，逐条当集会撑出 60~90 个假集数。"""
    key = _nd_norm(name)
    if not key:
        return []
    q = re.sub(r"\s*\([12][0-9]{3}\)$", "", _dump(name)).strip() or _dump(name)
    q = re.sub(r"\s*[ 　]*(全季|全集|完结|年番[0-9]*)$", "", q, flags=re.I).strip() or q
    js = _qw_text("/index.php/Ajax/Suggest?mid=1&wd=%s&limit=40" % quote(q), 10)
    if not js:
        return []
    try:
        data = json.loads(js)
    except Exception:
        return []
    cand = None
    for v in (data.get("list") or [])[:20]:
        nm = _dump(v.get("name") or v.get("vod_name"))
        vid = _dump(v.get("id") or v.get("vod_id"))
        if not nm or not vid:
            continue
        nk = _nd_norm(nm)
        if not nk or not (key in nk or nk in key):
            continue
        cand = vid
        break
    if not cand:
        return []
    html = _qw_text("/mv/%s.html" % cand, 18)
    if not html:
        return []
    titles = [_dump(x) for x in re.findall(r'<li class="title" id="tab-\d+">\s*([^<]+)', html)]
    blocks = re.findall(r'<ul class="gdt content"[\s\S]*?</ul>', html)

    def _score(nm):
        up = nm.upper()
        sc = 0
        if "4K" in up or "2160" in up:
            sc += 100
        elif "1080" in up:
            sc += 40
        if "高码" in nm or "HDR" in up:
            sc += 12
        if "纯净" in nm:
            sc += 6
        if re.search(r"(全集|完结|全\s*[0-9]+\s*集|全[0-9]+集)", nm):
            sc += 20
        if re.search(r"(更至|更新至|更新到)", nm):
            sc -= 8
        if re.search(r"(预告|花絮|抢先)", nm):
            sc -= 120
        return sc

    out = []
    for title, b in zip(titles, blocks):
        title = title.strip()
        if "网盘" not in title:
            continue
        # 豆瓣胶囊不再显示 123/阿里/光鸭；只保留百度、夸克、迅雷、UC。
        if re.search(r"123|阿里|光鸭", title):
            continue
        cands = []
        for mm in re.finditer(r'<a href="([^"]+)"[^>]*title="([^"]*)"', b):
            u = html_lib.unescape(mm.group(1)).strip()
            if not u or not re.match(r"https?://(?:pan\.baidu\.com|pan\.quark\.cn|pan\.xunlei\.com|"
                                     r"www\.alipan\.com|alipan\.com|drive\.uc\.cn|.*123pan\.cn|"
                                     r"www\.guangyapan\.com)", u):
                continue
            nm = _qw_clean(mm.group(2))
            cands.append((_score(nm), nm, u))
        if not cands:
            continue
        cands.sort(key=lambda x: -x[0])
        # 七味同一家网盘挂几十条整剧分享，质量最高的那条未必还能列目录；
        # 按质量从高到低多试几条，哪条能展开真实文件就用哪条。
        eps = []
        chosen = cands[0]
        xl_tried = False
        for sc, nm, u in cands[:4]:
            # 迅雷转存会写用户网盘，只挑第一条能匿名列出视频的分享试一次；
            # 失败就回退整剧，避免连续转存出多份临时目录。
            if "pan.xunlei.com" in u:
                if xl_tried or not _xl_auth().get("token"):
                    continue
                try:
                    _info = XunleiDrive().open_share(u)
                except Exception:
                    continue
                # 先匿名列目录：不是从第 1 集起的连续整剧就不转存，
                # 避免把“只有 11~30 集”的残缺分享硬拆成 20 集。
                if not _qw_complete_share(_info.get("items") or []):
                    continue
                xl_tried = True
            eps = _qw_split_share(u)
            if eps:
                chosen = (sc, nm, u)
                break
        nm, u = chosen[1], chosen[2]
        up = nm.upper()
        tag = "4K" if ("4K" in up or "2160" in up) else ("1080P" if "1080" in up else "分享")
        if "迅雷" in title:
            # 临时诊断：配置中心“已登录”不等于 py 读到了 token，先把状态挂在线路名上
            title += "·已登录" if _xl_auth().get("token") else "·未登录"
            if XL_LAST_ERR[0]:
                _e = XL_LAST_ERR[0]
                title += "·登录失效" if "登录" in _e else ("·" + re.sub(r"\s+", "", _e)[:14])
        if eps and len(eps) >= 2:
            out.append(("七味·%s·%d集" % (title, len(eps)), "#".join(eps)))
        else:
            tok = QW_PREFIX + base64.urlsafe_b64encode(u.encode("utf-8")).decode("ascii").rstrip("=")
            out.append(("七味·%s·整剧" % title, "%s$%s" % (tag, tok)))
    return out

def _qw_cache_key(name):
    # 版本前缀：换源后旧进程缓存（含已删的光鸭/123/阿里）立即失效
    return "ps2|" + _nd_norm(name)


def _qw_warm(name):
    key = _qw_cache_key(name)
    if not key or key in QW_WARMING:
        return
    QW_WARMING.add(key)
    ev = QW_EVENTS.setdefault(key, threading.Event())

    def run():
        try:
            lines = _qw_pan_lines(name)
            # 成功缓存 30 分钟；空结果只缓存 60 秒，七味偶发超时后下次详情会重试，
            # 避免一次网络抖动导致半小时都没有七味网盘。
            QW_PAN_CACHE[key] = (time.time() + (1800 if lines else 60), lines or [])
        except Exception:
            QW_PAN_CACHE[key] = (time.time() + 60, [])
        finally:
            QW_WARMING.discard(key)
            ev.set()
            QW_EVENTS.pop(key, None)

    threading.Thread(target=run, daemon=True).start()


def _qw_lines(name, budget=4.0):
    key = _qw_cache_key(name)
    if not key:
        return []
    hit = QW_PAN_CACHE.get(key)
    if hit and hit[0] > time.time():
        return hit[1]
    _qw_warm(name)
    deadline = time.time() + max(0.5, budget)
    while time.time() < deadline:
        hit = QW_PAN_CACHE.get(key)
        if hit and hit[0] > time.time():
            return hit[1]
        time.sleep(0.3)
    hit = QW_PAN_CACHE.get(key)
    return hit[1] if hit and hit[0] > time.time() else []




MIPAN_LOCK = threading.Lock()
MIPAN_WARMING = set()


def _main_eps(v):
    """取全片主集数：优先用详情备注里的「第N集/全N集」，没有才用线路众数。"""
    try:
        _rem = _dump(v.get("vod_remarks"))
        _rm = re.search(r"第\s*(\d{1,4})\s*集", _rem) or re.search(r"(\d{1,4})\s*集", _rem)
        if _rm:
            return int(_rm.group(1))
        counts = [len([e for e in _dump(u).split("#") if e])
                  for f, u in zip(_dump(v.get("vod_play_from")).split("$$$"),
                                  _dump(v.get("vod_play_url")).split("$$$"))
                  if "网盘·" not in _dump(f)]
        counts = [n for n in counts if n >= 2]
        if not counts:
            counts = [len([e for e in _dump(u).split("#") if e])
                      for u in _dump(v.get("vod_play_url")).split("$$$")]
            counts = [n for n in counts if n >= 2]
        if not counts:
            return 0
        return max(set(counts), key=lambda n: (counts.count(n), n))
    except Exception:
        return 0


def _nd_target_eps(v):
    """网盘线对齐用的目标集数：电影/正片只有 1 个正片文件，
    不能拿官方线路的 2 个视频（正片+花絮）去要求网盘也 2 集。"""
    try:
        _m = _main_eps(v)
        _rem = _dump(v.get("vod_remarks")) + _dump(v.get("type_name"))
        if _m <= 3 and ("正片" in _rem or "电影" in _rem):
            return 1
        return _m
    except Exception:
        return 0


def _unify_nd_eps(v):
    """用户要求：网盘线路集数必须和官方/正片主线一致。
    少于主线集数的网盘线直接不显示；多于主线的裁到主线集数，标签也改成同一集数。"""
    try:
        _main = _main_eps(v)
        _nd_main = _nd_target_eps(v)
        if not _main:
            return
        _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
        _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
        _keep = []
        _pos = {}
        for f, u in zip(_ff, _uu):
            # 官方平台线不动：优酷 115 集、腾讯 173 集是平台自己的集数，
            # 不能因为别的平台集数多就把它删掉
            if "网盘" not in _dump(f):
                _keep.append((_dump(f), _dump(u)))
                continue
            _eps = [e for e in _dump(u).split("#") if e]
            _target = _nd_main
            if not _target:
                _keep.append((_dump(f), _dump(u)))
                continue
            if len(_eps) < _target:
                # 用户要求：网盘线再少也要先显示出来，不能整条消失；
                # 真实集数写进线名（如 ·9集），不做补齐、不重复令牌
                _f = re.sub(r"(\d{1,4})\s*集", "%d集" % len(_eps), _dump(f))
                if not re.search(r"\d{1,4}\s*集", _f):
                    _f = "%s·%d集" % (_f, len(_eps))
                _u = "#".join(_eps)
                if _f in _pos:
                    _i = _pos[_f]
                    if len(_u) > len(_keep[_i][1]):
                        _keep[_i] = (_f, _u)
                    continue
                _pos[_f] = len(_keep)
                _keep.append((_f, _u))
                continue
            if len(_eps) > _target:
                _eps = _eps[:_target]
            _f = re.sub(r"(\d{1,4})\s*集", "%d集" % _target, _dump(f))
            _u = "#".join(_eps)
            if _f in _pos:
                _i = _pos[_f]
                if len(_u) > len(_keep[_i][1]):
                    _keep[_i] = (_f, _u)
                continue
            _pos[_f] = len(_keep)
            _keep.append((_f, _u))
        # 网盘线内部统一顺序：快映 → 木偶 → 剧透；同站内 夸克 → 百度 → UC
        _official = [x for x in _keep if "网盘" not in _dump(x[0])]
        _nets = [x for x in _keep if "网盘" in _dump(x[0])]
        def _nd_rank(_p):
            _f = _dump(_p[0])
            _site = 0 if "快映" in _f else 1 if "木偶" in _f else 2 if "剧透" in _f else 3
            _pan = 0 if "夸克" in _f else 1 if "百度" in _f else 2 if "UC" in _f else 3
            return (_site, _pan)
        _nets.sort(key=_nd_rank)
        _keep = _official + _nets
        v["vod_play_from"] = "$$$".join(f for f, _ in _keep)
        v["vod_play_url"] = "$$$".join(u for _, u in _keep)
    except Exception:
        pass


def _mipan_append(v):
    """用户要求彻底去掉觅盘线：保留函数名防止旧调用报错，但不再补任何觅盘。"""
    return
    try:
        if not MIPAN_LOCK.acquire(timeout=22):
            return
        try:
            _mipan_append_unlocked(v)
        finally:
            MIPAN_LOCK.release()
    except Exception:
        pass


def _warm_bl80(name, eps=0):
    """搜索结果阶段就后台预热快映，用户点进详情时尽量直接命中缓存。"""
    try:
        key = _nd_key(name)
        if not key or key in BL80_WARMING:
            return
        BL80_WARMING.add(key)
        def run():
            try:
                v = {"vod_name": name, "vod_play_from": "预热",
                     "vod_play_url": "#".join("%d$x" % i for i in range(1, max(1, int(eps or 1)) + 1))}
                _bl80_append(v, True)
            except Exception:
                pass
            finally:
                BL80_WARMING.discard(key)
        import threading as _th
        _th.Thread(target=run, daemon=True).start()
    except Exception:
        pass


def _warm_mipan(name, eps=0):
    """搜索返回后立刻后台预热觅盘：详情打开时直接命中线路缓存，不再现场搜。"""
    try:
        key = _nd_key(name)
        if not key or not eps:
            return
        _hit = MIPAN_LINE_CACHE.get(key)
        if _hit and _hit[0] > time.time():
            return
        if key in MIPAN_WARMING:
            return
        MIPAN_WARMING.add(key)

        def run():
            try:
                _v = {"vod_name": name, "vod_play_from": "预热",
                      "vod_play_url": "#".join("%d$x" % i for i in range(1, int(eps) + 1))}
                _mipan_append(_v)
            except Exception:
                pass
            finally:
                MIPAN_WARMING.discard(key)

        import threading as _th
        _th.Thread(target=run, daemon=True).start()
    except Exception:
        pass


def _warm_netdisk(name):
    """搜索返回后在后台预取该片的网盘线路：慢站也给它时间，预热好后详情直接读缓存。"""
    # 七味线已删除，不再后台预热，避免拖慢详情和全局搜索
    key = _nd_key(name)
    if not key:
        return
    if key in _ND_WARMING:
        return
    _lc = NETDISK_LINES_CACHE.get(key)
    if _lc and _lc[0] > time.time():
        return
    _ND_WARMING.add(key)
    def run():
        try:
            q = _nd_key(name) or name
            found = []
            for av in _nd_search_budget(q, 6.0):
                avn = _nd_key(av.get("vod_name"))
                if not avn or not (key in avn or avn in key):
                    continue
                aid = _dump(av.get("vod_id"))
                if not aid:
                    continue
                site = aid.split("@", 1)[0]
                if site not in ("木偶", "玩偶", "剧透", "快映"):
                    continue
                found.append({"id": aid, "site": site, "name": _dump(av.get("vod_name"))})
            if found:
                NETDISK_LINE_CACHE[key] = (time.time() + 1800, found[:20])
        except Exception:
            pass
        finally:
            _ND_WARMING.discard(key)
    import threading as _th
    _th.Thread(target=run, daemon=True).start()


def _qw_append(v, name):
    """把七味网盘线挂到豆瓣详情；缓存没热好时最多等十几秒，避免直接空手。"""
    return  # 用户要求删除七味线，保留代码便于以后恢复
    lines = _qw_lines(name, 18.0)
    if not lines:
        return
    ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
    uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
    for lab, u in lines:
        if re.search(r"七味·(123|阿里|光鸭)", lab):
            continue
        if lab in ff or not u:
            continue
        ff.append(lab)
        uu.append(u)
    if ff:
        v["vod_play_from"] = "$$$".join(ff)
        v["vod_play_url"] = "$$$".join(uu)


def _enrich_netdisk(vods):
    """豆瓣详情补全所有网盘站点线路：每个站挑最能播的一条详情。"""
    if not isinstance(vods, list) or not vods:
        return
    import concurrent.futures as _cf
    _t_start = time.time()
    _budget = 7.0         # 网盘补全总预算（秒），搜索和详情都改成逐个走
    for v in vods:
        try:
            vid = _dump(v.get("vod_id"))
            if vid.startswith("agg:"):
                try:
                    _qw_append(v, _dump(v.get("vod_name")))
                except Exception:
                    pass
                continue
            name = _dump(v.get("vod_name"))
            _eps0 = _main_eps(v) or max([len([e for e in _dump(x).split("#") if e])
                         for x in _dump(v.get("vod_play_url")).split("$$$")] or [0])
            key = _nd_key(name)
            if not key:
                continue
            # 最终线路缓存：重复打开详情直接拼，不再等任何网盘站
            _lc = NETDISK_LINES_CACHE.get(key)
            if _lc and _lc[0] > time.time():
                _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
                _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
                _have = set()
                for _g in _uu:
                    _eps = [e for e in _g.split("#") if e]
                    _have.add((_eps[0].split("$")[-1][:60] if _eps else "",
                               _eps[-1].split("$")[-1][:60] if _eps else ""))
                for _f, _u in _lc[1]:
                    _eps = [e for e in _u.split("#") if e]
                    _sig = (_eps[0].split("$")[-1][:60] if _eps else "",
                            _eps[-1].split("$")[-1][:60] if _eps else "")
                    if _sig in _have:
                        continue
                    _have.add(_sig)
                    _ff.append(_f)
                    _uu.append(_u)
                v["vod_play_from"] = "$$$".join(_ff)
                v["vod_play_url"] = "$$$".join(_uu)
                try:
                    _qw_append(v, name)
                except Exception:
                    pass
                continue
            hit = NETDISK_LINE_CACHE.get(key)
            if hit and hit[0] > time.time():
                # 预热缓存里可能混进趣盘/卡卡等站，进详情前再按白名单过滤一遍
                cands = [dict(x) for x in hit[1]
                         if any(k in _dump(x.get("site")) for k in ("木偶", "玩偶", "剧透", "快映"))]
            else:
                cands = []
                _left = max(1.0, _budget - (time.time() - _t_start))
                _qname = _nd_key(name) or name
                for av in _nd_search_budget(_qname, min(4.0, _left)):
                    avn = _nd_key(av.get("vod_name"))
                    if not avn or not (key in avn or avn in key):
                        continue
                    aid = _dump(av.get("vod_id"))
                    if aid:
                        cands.append({"id": aid, "site": aid.split("@", 1)[0],
                                      "name": _dump(av.get("vod_name"))})
                # 每站最多两条候选；按“整季文件夹更可能出片”的站优先
                _by_site = {}
                for c in cands:
                    # 网盘搜索只保留木偶 / 玩偶 / 儿歌，其它站一律不要
                    if not any(k in _dump(c.get("site")) for k in ("木偶", "玩偶", "剧透", "快映")):
                        continue
                    _by_site.setdefault(c["site"], []).append(c)
                for _s in _by_site:
                    _by_site[_s].sort(key=lambda c: (
                        0 if re.search(r"全\s*\d+\s*集|全集|完结", _dump(c.get("name"))) else 1,
                        0 if re.search(r"4K|高码|HQ|HDR", _dump(c.get("name")), re.I) else 1,
                        len(_dump(c.get("name")))))
                    _by_site[_s] = _by_site[_s][:2]
                _pri = ["木偶", "玩偶", "剧透", "快映"]
                _sites = sorted(_by_site, key=lambda x: (_pri.index(x) if x in _pri else 99, x))[:12]
                cands = [c for _s in _sites for c in _by_site[_s]][:20]
                NETDISK_LINE_CACHE[key] = (time.time() + 1800, [dict(x) for x in cands])
            if not cands:
                continue
            def _one(c):
                try:
                    return c, _agg_detail(c["id"])
                except Exception:
                    return c, None
            _long = ("全季" in name) or (_eps0 >= 100)
            if _long:
                cands = cands[:6]
            # 详情也一个一个取，不再同时打多个网盘站
            got = []
            for c in cands:
                _left2 = _budget - (time.time() - _t_start)
                if _left2 <= 0:
                    break
                got.append(_one(c))
            # 完整集数优先：同站同盘型只留最优一条，但夸克/百度/UC 等不同盘型全部保留
            _best = {}
            for c, d in got:
                if not d:
                    continue
                gs = _nd_groups(d)
                if not gs:
                    continue
                if _eps0 and max(x[1] for x in gs) < max(3, _eps0 // 3):
                    continue
                _full = 1 if re.search(r"全\s*\d+\s*集|全集|完结", _dump(c.get("name"))) else 0
                for _g in gs:
                    _cnt = _g[1]
                    # 只要完整集数；没有正片集数时才退回最优一条
                    if _eps0 and _cnt < _eps0:
                        continue
                    _pan = _nd_pan(_g[2])
                    _key2 = (c["site"], _pan)
                    _sc = (_full, -abs(_cnt - _eps0) if _eps0 else 0,
                           1 if "解析" in _dump(_g[2]) else 0, _cnt)
                    if _key2 not in _best or _sc > _best[_key2][0]:
                        _best[_key2] = (_sc, [_g])
            _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
            _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
            _have = set()
            for _g in _uu:
                _eps = [e for e in _g.split("#") if e]
                _have.add((_eps[0].split("$")[-1][:60] if _eps else "",
                           _eps[-1].split("$")[-1][:60] if _eps else ""))
            _order = ["木偶", "玩偶", "剧透", "快映"]
            _new_pairs = []
            for _key2 in sorted(_best, key=lambda x: (_order.index(x[0]) if x[0] in _order else 99, x[0], x[1])):
                site = _key2[0]
                _sc, gs = _best[_key2]
                # 同一个站点同一个详情页，只留一条：优先「解析」，其次「嗅探」
                _by_url = {}
                for _g in gs:
                    _url = re.sub(r"agg:(?:直连|嗅探|解析)\|", "", _g[3])
                    if _url not in _by_url or ("解析" in _g[2] and "解析" not in _by_url[_url][2]):
                        _by_url[_url] = _g
                gs = list(_by_url.values())
                gs.sort(key=lambda x: (1 if "解析" in x[2] else 0, x[0]), reverse=True)
                for _s, _n, f, u in gs:
                    if _eps0 >= 6 and _n < 3:
                        continue
                    _eps = [e for e in u.split("#") if e]
                    _sig = (_eps[0].split("$")[-1][:60] if _eps else "",
                            _eps[-1].split("$")[-1][:60] if _eps else "")
                    if _sig in _have:
                        continue
                    _have.add(_sig)
                    _lab, _u2 = _nd_norm_line("网盘·%s·%s" % (site, f), u)
                    _ff.append(_lab)
                    _uu.append(_u2)
                    _new_pairs.append((_lab, _u2))
            v["vod_play_from"] = "$$$".join(_ff)
            v["vod_play_url"] = "$$$".join(_uu)
            if _new_pairs:
                NETDISK_LINES_CACHE[key] = (time.time() + 1800, _new_pairs)
                while len(NETDISK_LINES_CACHE) > 60:
                    NETDISK_LINES_CACHE.pop(next(iter(NETDISK_LINES_CACHE)), None)
            try:
                _qw_append(v, name)
            except Exception:
                pass
        except Exception:
            pass


MIPAN_SKIP_CACHE = {}
MIPAN_GOOD_CACHE = {}
MIPAN_LINE_CACHE = {}
BL80_LINE_CACHE = {}
BL80_WARMING = set()
# 觅盘搜索索引会抽风（整页返回 0 条）；这里记已验证可解析的分享，优先直连解析
MIPAN_KNOWN = {"沉默的荣耀": "https://pan.quark.cn/s/25784a97c768",
               "蒸蒸日上": "https://drive.uc.cn/s/f554f79ee5274"}


def _mipan_append_unlocked(v):
    """详情兜底追加觅盘线路：只查觅盘，只保留夸克/UC，选集数最接近的一条。"""
    try:
        name = _dump(v.get("vod_name"))
        key = _nd_key(name)
        if not key:
            return
        _eps0 = _main_eps(v)
        # 已经有觅盘线时：集数够就不重复查；不够（比如只有 35 集）继续找 39 集的替换
        _old_mp = 0
        for _f0, _u0 in zip(_dump(v.get("vod_play_from")).split("$$$"),
                            _dump(v.get("vod_play_url")).split("$$$")):
            if "网盘·觅盘" in _f0:
                _old_mp = max(_old_mp, len([e for e in _u0.split("#") if e]))
        if _old_mp and (not _eps0 or _old_mp >= _eps0):
            return
        # 上次已经成功挂过的觅盘线直接复用，不再受这次搜索空响应影响
        _hit = MIPAN_LINE_CACHE.get(key)
        if _hit and _hit[0] > time.time():
            # 旧缓存也要复核集数，残缺的不复用，免得 35 集线一直被翻出来
            _hit_eps = [e for e in _dump(_hit[2]).split("#") if e]
            _bad = bool(_eps0 and abs(len(_hit_eps) - _eps0) > 1)
            if not _bad and _eps0 and len(_hit) > 3 and abs(int(_hit[3] or 0) - _eps0) > 1:
                _bad = True
            if _bad:
                MIPAN_LINE_CACHE.pop(key, None)
            elif not _old_mp:
                _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
                _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
                _ff.append(_hit[1]); _uu.append(_hit[2])
                v["vod_play_from"] = "$$$".join(_ff)
                v["vod_play_url"] = "$$$".join(_uu)
                return
        ob = _agg_client()
        if not ob:
            return
        site = next((x for x in ob.sites.values() if _dump(x.get("id")) == "觅盘"), None)
        if not site:
            return
        _ensure_url(site)
        def _pick(q):
            return [x for x in (ob._site_search(site, q, "1") or [])
                    if (lambda xn: xn and (q in xn or xn in q))(_nd_key(x.get("vod_name")))]
        cand = _pick(key)
        if not cand:
            # 觅盘偶发整页空响应，稍等重试一次再判无资源
            time.sleep(0.4)
            cand = _pick(key)
        _seed = MIPAN_KNOWN.get(key) or MIPAN_GOOD_CACHE.get(key)
        if _seed:
            _seen = set(_dump(x.get("vod_id")) for x in cand)
            if _seed not in _seen:
                # 给种子补上集数，排序时才会排在 39 集最前，而不是被一堆失效候选拖到超时
                cand.insert(0, {"vod_id": _seed,
                                "vod_name": (name + (" 全%d集" % _eps0)) if _eps0 else name})
        short = _nd_key(re.split(r"[：:·\-（(\[ ]", name)[0].strip())[:6]
        if short and short != key:
            # 全名搜到的可能只有 35 集版本，再用短名补一次，合并后按集数贴近度排
            _seen = set(_dump(x.get("vod_id")) for x in cand)
            for x in _pick(short):
                if _dump(x.get("vod_id")) not in _seen:
                    _seen.add(_dump(x.get("vod_id"))); cand.append(x)
        if not cand:
            return
        def _cand_eps(x):
            _m = re.search(r"(\d{1,4})\s*集", _dump(x.get("vod_name")))
            return int(_m.group(1)) if _m else 0
        # 集数优先对齐豆瓣总集数，再排夸克/全集/4K；别让 35 集抢先占掉唯一名额
        cand.sort(key=lambda x: (
            0 if (_eps0 and _cand_eps(x) == _eps0) else (abs(_cand_eps(x) - _eps0) if (_eps0 and _cand_eps(x)) else 999),
            0 if "quark" in _dump(x.get("vod_id")).lower() else (1 if "uc.cn" in _dump(x.get("vod_id")).lower() else (2 if "xunlei" in _dump(x.get("vod_id")).lower() else 3)),
            0 if re.search(r"全\s*\d+\s*集|全集|完结", _dump(x.get("vod_name"))) else 1,
            0 if re.search(r"4K|高码|HQ|HDR", _dump(x.get("vod_name")), re.I) else 1))
        def _one(x):
            try:
                d = _agg_detail("觅盘@" + _dump(x.get("vod_id")))
                return _nd_groups(d) if d else []
            except Exception:
                return []
        best = None
        # 觅盘同一个会话不能并发解析：并发会让一部分分享直接返回空，39 集的好源反被漏掉。
        # 按“名称里写的集数”排序后串行试，一命中豆瓣总集数就停，通常 1-3 次就够。
        _dl = time.time() + 8.0
        for _x in cand[:20]:
            if time.time() > _dl:
                break
            _gs = _one(_x)
            # 只留夸克/UC，百度等需登录的不挂
            _gs = [g for g in _gs if any(k in _dump(g[2]) for k in ("夸克", "UC"))]
            if not _gs:
                continue
            _cnt = max(g[1] for g in _gs)
            _diff = abs(_cnt - _eps0) if _eps0 else 0
            _sc = (-_diff, max(g[0] for g in _gs), _cnt)
            if best is None or _sc > best[0]:
                best = (_sc, _gs)
            if _eps0 and _cnt == _eps0:
                if "pan.quark.cn" in _dump(_x.get("vod_id")):
                    MIPAN_GOOD_CACHE[key] = _dump(_x.get("vod_id"))
                break
        # 第一页候选全是失效分享时，往后翻页找；集数不对时也继续翻，找最贴近的
        if _eps0 and (best is None or abs(max(g[1] for g in best[1]) - _eps0) >= 2):
            _tried = set(_dump(x.get("vod_id")) for x in cand[:20])
            _extra = []
            for _pg in range(2, 6):
                try:
                    _pv = ob._site_search(site, key, str(_pg)) or []
                except Exception:
                    _pv = []
                for _x in _pv:
                    _xid = _dump(_x.get("vod_id"))
                    _xn = _nd_key(_x.get("vod_name"))
                    if not _xid or _xid in _tried or _xid in set(_dump(y.get("vod_id")) for y in _extra):
                        continue
                    if not _xn or not (key in _xn or _xn in key):
                        continue
                    _m2 = re.search(r"(\d{1,4})\s*集", _dump(_x.get("vod_name")))
                    if _m2 and int(_m2.group(1)) == _eps0:
                        _extra.append(_x)
            _dl2 = time.time() + 5.0
            for _x in _extra[:24]:
                if time.time() > _dl2:
                    break
                _gs = _one(_x)
                if not _gs:
                    continue
                _cnt = max(g[1] for g in _gs)
                if _cnt == _eps0:
                    best = ((0, max(g[0] for g in _gs), _cnt), _gs)
                    break
        if not best:
            return
        # 觅盘只挂集数基本对齐的那一条：差 1 集可接受，35/39、4/6 这种缺集线仍然不出现
        if _eps0 and abs(max(g[1] for g in best[1]) - _eps0) > 1:
            MIPAN_SKIP_CACHE[key] = time.time() + 300
            return
        gs = best[1]
        _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
        _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
        _best_cnt = max(g[1] for g in gs)
        if _old_mp and _best_cnt > _old_mp:
            # 新找到集数更全的同站线路，替换掉旧的 35 集版本，别两条并存
            _kp = [(f, u) for f, u in zip(_ff, _uu) if "网盘·觅盘" not in f]
            _ff = [f for f, _ in _kp]
            _uu = [u for _, u in _kp]
        # 同一部片只保留一条觅盘线（夸克优先），不再把夸克/UC 同时铺出来
        _one_group = max(gs, key=lambda g: (1 if "夸克" in _dump(g[2]) else 0, g[0], g[1]))
        _eps = [e for e in _one_group[3].split("#") if e]
        if _eps:
            _lab = "网盘·觅盘·%s" % _one_group[2]
            _ff.append(_lab)
            _uu.append(_one_group[3])
            MIPAN_LINE_CACHE[key] = (time.time() + 1800, _lab, _one_group[3], _one_group[1])
        v["vod_play_from"] = "$$$".join(_ff)
        v["vod_play_url"] = "$$$".join(_uu)
        while len(MIPAN_LINE_CACHE) > 60:
            MIPAN_LINE_CACHE.pop(next(iter(MIPAN_LINE_CACHE)), None)
    except Exception:
        pass


def _muppet_append(v):
    """木偶站定向兜底：聚合搜索预算被慢站吃掉时，直接查木偶并补一条集数对齐的夸克/UC。"""
    try:
        if "网盘·木偶" in _dump(v.get("vod_play_from")):
            return
        name = _dump(v.get("vod_name"))
        key = _nd_key(name)
        if not key:
            return
        _eps0 = _nd_target_eps(v) or max([len([e for e in _dump(x).split("#") if e])
                     for x in _dump(v.get("vod_play_url")).split("$$$")] or [0])
        ob = _agg_client()
        if not ob:
            return
        site = next((x for x in ob.sites.values() if _dump(x.get("id")) == "木偶"), None)
        if not site:
            return
        _ensure_url(site)
        try:
            vods = ob._site_search(site, key, "1") or []
        except Exception:
            vods = []
        cand = [x for x in vods
                if (lambda xn: xn and (key in xn or xn in key))(_nd_key(x.get("vod_name")))]
        if not cand:
            return
        def _cand_eps(x):
            _m = re.search(r"(\d{1,4})\s*集", _dump(x.get("vod_name")))
            return int(_m.group(1)) if _m else 0
        cand.sort(key=lambda x: (0 if (_eps0 and _cand_eps(x) == _eps0) else 1,))
        best = {}
        _dl = time.time() + 7.0
        for x in cand[:4]:
            if time.time() > _dl:
                break
            try:
                d = _agg_detail("木偶@" + _dump(x.get("vod_id")))
                gs = _nd_groups(d) if d else []
            except Exception:
                gs = []
            for g in gs:
                # 木偶不再按主集数硬卡，按最接近的集数挂
                pass
                pan = _nd_pan(g[2])
                sc = (-abs(g[1] - _eps0) if _eps0 else 0, 1 if "夸克" in _dump(g[2]) else 0, g[1])
                if pan not in best or sc > best[pan][0]:
                    best[pan] = (sc, g)
        if not best:
            return
        _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
        _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
        for g in [best[p][1] for p in sorted(best)]:
            _lab, _u2 = _nd_norm_line("网盘·木偶·%s" % g[2], g[3])
            _ff.append(_lab)
            _uu.append(_u2)
        v["vod_play_from"] = "$$$".join(_ff)
        v["vod_play_url"] = "$$$".join(_uu)
    except Exception:
        pass


def _site_pan_append(v, sid, deadline=4.0):
    """指定网盘站定向补一条：聚合搜索被慢响应拖没时，单独查该站。
    木偶只留夸克/UC；玩偶/剧透允许百度等免登分享，按集数贴近度择优。"""
    try:
        lab = "网盘·" + sid
        _have = {_nd_pan(x) for x in _dump(v.get("vod_play_from")).split("$$$") if x.startswith(lab)}
        if len(_have) >= 2:
            return
        name = _dump(v.get("vod_name"))
        key = _nd_key(name)
        if not key:
            return
        _eps0 = _main_eps(v) or max([len([e for e in _dump(x).split("#") if e])
                     for x in _dump(v.get("vod_play_url")).split("$$$")] or [0])
        ob = _agg_client()
        if not ob:
            return
        site = next((x for x in ob.sites.values() if _dump(x.get("id")) == sid), None)
        if not site:
            return
        _ensure_url(site)
        vods = []
        for _try in range(2):
            try:
                vods = ob._site_search(site, key, "1") or []
            except Exception:
                vods = []
            if vods:
                break
            time.sleep(0.4)
        cand = [x for x in vods
                if (lambda xn: xn and (key in xn or xn in key))(_nd_key(x.get("vod_name")))]
        if not cand:
            return

        def _cand_eps(x):
            _m = re.search(r"(\d{1,4})\s*集", _dump(x.get("vod_name")))
            return int(_m.group(1)) if _m else 0
        cand.sort(key=lambda x: (0 if (_eps0 and _cand_eps(x) == _eps0) else 1,))
        best = {}
        _dl = time.time() + deadline
        for x in cand[:4]:
            if time.time() > _dl:
                break
            try:
                d = _agg_detail("%s@%s" % (sid, _dump(x.get("vod_id"))))
                gs = _nd_groups(d) if d else []
            except Exception:
                gs = []
            for g in gs:
                # 玩偶经常只有 10 个视频，而豆瓣备注写“更新至26集”；
                # 再按全集数硬卡就会把玩偶整条线丢掉，按最接近的集数挂
                # 少集也保留，线名里会标真实集数；不再因为集数不够整条消失
                pan = _nd_pan(g[2])
                sc = (-abs(g[1] - _eps0) if _eps0 else 0, 1 if "夸克" in _dump(g[2]) else 0, g[1])
                if pan not in best or sc > best[pan][0]:
                    best[pan] = (sc, g)
        if not best:
            return
        _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
        _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
        for g in [best[p][1] for p in sorted(best)]:
            _lab0 = "%s·%s" % (lab, g[2])
            if sid == "玩偶" and g[1] and not re.search(r"\d+\s*集", _lab0):
                _lab0 = "%s·%d集" % (_lab0, g[1])
            _lab, _u2 = _nd_norm_line(_lab0, g[3])
            _ff.append(_lab)
            _uu.append(_u2)
        v["vod_play_from"] = "$$$".join(_ff)
        v["vod_play_url"] = "$$$".join(_uu)
    except Exception:
        pass


def _bl80_playable(ob, f, u):
    """快映线路落详情前先试第一集：出不了流就不显示这条，避免挂一条点开必失败的线。"""
    try:
        e0 = [x for x in _dump(u).split("#") if x][0]
        tok = e0.split("$", 1)[1] if "$" in e0 else ""
        if not tok:
            return False
        if tok.startswith("Q~"):
            rest = tok[2:]
            head, part2, ft = rest.rsplit("+", 2)
            part1 = head.split("__", 1)[-1] if "__" in head else head
            if len(part1) <= 20 and len(part2) > 20:
                pwd_id, fid = part1, part2
            elif len(part2) <= 20 and len(part1) > 20:
                pwd_id, fid = part2, part1
            else:
                pwd_id, fid = part2, part1
            rst = ob._quark_play(pwd_id, fid, ft, getattr(ob, "quark80", None) , head.split("__",1)[0] if "__" in head else "")
        elif "UC" in _dump(f) or tok.startswith("UC"):
            parts = tok.rsplit("+", 4)
            if len(parts) < 3:
                return False
            head, pwd_id, ft = parts[0], parts[1], parts[2]
            fid = head.split("__", 1)[-1] if "__" in head else head
            rst = ob.uc.play_anonymous(pwd_id, fid, ft)
        else:
            return False
        _u = (rst or {}).get("url") or ""
        if not _u:
            return False
        return _stream_ok(_u, (rst or {}).get("header") or {"User-Agent": PC_UA}, timeout=8)
    except Exception:
        return False


def _bl80_append(v, _from_warm=False):
    """详情兜底追加快映网盘线路：只查快映，只保留夸克/UC，选集数最接近的一条。"""
    try:
        name = _dump(v.get("vod_name"))
        key = _nd_key(name)
        if not key or "网盘·快映" in _dump(v.get("vod_play_from")):
            return
        _eps0 = _main_eps(v) or max([len([e for e in _dump(x).split("#") if e])
                     for x in _dump(v.get("vod_play_url")).split("$$$")] or [0])
        # 快映在自己的线程里跑，必须用线程内独立会话；共享全局会话会和网盘补全互相踩
        ob = _agg_client_local()
        if not ob:
            return
        site = next((x for x in ob.sites.values() if _dump(x.get("id")) == "快映"), None)
        if not site:
            return
        _ensure_url(site)
        _hit80 = BL80_LINE_CACHE.get(key)
        if _hit80 and _hit80[0] > time.time() and (not _eps0 or abs(_hit80[3] - _eps0) <= 1):
            _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
            _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
            _ff.append(_hit80[1]); _uu.append(_hit80[2])
            v["vod_play_from"] = "$$$".join(_ff)
            v["vod_play_url"] = "$$$".join(_uu)
            return
        # 详情页已经预热了快映：这里只等预热结果，不重复发一遍搜索/详情
        if (not _from_warm) and key in BL80_WARMING:
            _dlw = time.time() + 13.0
            while time.time() < _dlw:
                _w = BL80_LINE_CACHE.get(key)
                if _w and _w[0] > time.time() and (not _eps0 or abs(_w[3] - _eps0) <= 1):
                    _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
                    _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
                    _ff.append(_w[1]); _uu.append(_w[2])
                    v["vod_play_from"] = "$$$".join(_ff)
                    v["vod_play_url"] = "$$$".join(_uu)
                    return
                if key not in BL80_WARMING:
                    break
                time.sleep(0.4)
            # 预热还没完：本次详情先不放快映，让预热线程继续跑，缓存好了下次直接命中
            return
        # 快映偶尔 20 秒才响应，详情不能被它拖死；搜索最多等 8 秒
        import threading as _th
        _box = {}
        def _search():
            # 快映搜索偶发第一次空响应，同一个关键词再试一次，别一次空就判无源
            for _try80 in range(2):
                try:
                    _box["v"] = ob._site_search(site, key, "1") or []
                except Exception:
                    _box["v"] = []
                if _box["v"]:
                    break
                time.sleep(0.5)
        _t = _th.Thread(target=_search)
        _t.daemon = True
        _t.start()
        _t.join(34.0)
        vods = _box.get("v") or []
        cand = [x for x in vods
                if (lambda xn: xn and (key in xn or xn in key))(_nd_key(x.get("vod_name")))]
        if not cand:
            return
        def _one(x, wait=26.0):
            _b = {}
            def _work():
                try:
                    d = _agg_detail("快映@" + _dump(x.get("vod_id")))
                    _b["gs"] = _nd_groups(d) if d else []
                except Exception:
                    _b["gs"] = []
            _th2 = _th.Thread(target=_work)
            _th2.daemon = True
            _th2.start()
            _th2.join(wait)
            return _b.get("gs") or []
        best = {}
        _dl = time.time() + 35.0
        for x in cand[:12]:
            if time.time() > _dl:
                break
            gs = _one(x, max(8.0, min(28.0, _dl - time.time())))
            if not gs:
                continue
            # 完整集数全出：夸克、百度、UC 都保留，不再只挑夸克/UC
            for g in gs:
                # 少集也保留：夸克/百度/UC 各留一条，不再因集数不足被整条剔掉
                pan = _nd_pan(g[2])
                sc = (-abs(g[1] - _eps0) if _eps0 else 0, 1 if "夸克" in _dump(g[2]) else 0, g[1])
                if pan not in best or sc > best[pan][0]:
                    best[pan] = (sc, g)
        if not best:
            return
        gs = [best[p][1] for p in sorted(best)]
        _ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
        _uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
        _have = set()
        for _g in _uu:
            _eps = [e for e in _g.split("#") if e]
            _have.add((_eps[0].split("$")[-1][:60] if _eps else "",
                       _eps[-1].split("$")[-1][:60] if _eps else ""))
        _used = set(_ff)
        for _s, _n, f, u in gs:
            _eps = [e for e in u.split("#") if e]
            if not _eps:
                continue
            _sig = (_eps[0].split("$")[-1][:60], _eps[-1].split("$")[-1][:60])
            if _sig in _have:
                continue
            _have.add(_sig)
            _label, _u2 = _nd_norm_line("网盘·快映·%s" % f, u)
            _n2 = 2
            while _label in _used:
                _label = "%s·%d" % (_label.split("·%d" % _n2)[0], _n2)
                _n2 += 1
            _used.add(_label)
            _ff.append(_label)
            _uu.append(_u2)
            BL80_LINE_CACHE[key] = (time.time() + 1800, _label, _u2, _n)
        v["vod_play_from"] = "$$$".join(_ff)
        v["vod_play_url"] = "$$$".join(_uu)
    except Exception:
        pass


def _iq_warm_next(title, idx):
    """后台只预热爱奇艺官方集页；解析直链寿命极短，不能跨播放缓存。"""
    try:
        key = (_dump(title), int(idx) + 1)
        if key in IQ_PLAY_WARMING:
            return
        IQ_PLAY_WARMING.add(key)
        _platform_4k_page("爱奇艺", key[0], key[1])
    except Exception:
        pass
    finally:
        try:
            IQ_PLAY_WARMING.discard((_dump(title), int(idx) + 1))
        except Exception:
            pass


def _merge_vod_lines(dst, src):
    """把 src 里新增的线路合并到 dst，按首尾播放值去重。"""
    try:
        _ff = [x for x in _dump(dst.get("vod_play_from")).split("$$$") if x]
        _uu = [x for x in _dump(dst.get("vod_play_url")).split("$$$") if x]
        _have = set()
        for _g in _uu:
            _eps = [e for e in _g.split("#") if e]
            _have.add((_eps[0].split("$")[-1][:60] if _eps else "",
                       _eps[-1].split("$")[-1][:60] if _eps else ""))
        _labels = set(_ff)
        for _f, _g in zip(_dump(src.get("vod_play_from")).split("$$$"),
                          _dump(src.get("vod_play_url")).split("$$$")):
            if not _f or not _g or _f in _labels or _f.startswith("调试"):
                continue
            _labels.add(_f)
            _eps = [e for e in _g.split("#") if e]
            _sig = (_eps[0].split("$")[-1][:60] if _eps else "",
                    _eps[-1].split("$")[-1][:60] if _eps else "")
            if _sig in _have:
                continue
            _have.add(_sig)
            _ff.append(_f)
            _uu.append(_g)
        dst["vod_play_from"] = "$$$".join(_ff)
        dst["vod_play_url"] = "$$$".join(_uu)
    except Exception:
        pass


def _prune_mismatch(v):
    """官方平台线集数明显小于其它线时，砍掉那些多季/动画混进来的超长线路。"""
    try:
        ff = [x for x in _dump(v.get("vod_play_from")).split("$$$") if x]
        uu = [x for x in _dump(v.get("vod_play_url")).split("$$$") if x]
        oi, oc = None, 0
        for i, f in enumerate(ff):
            if any(k in f for k in ("优酷", "腾讯", "爱奇艺", "芒果", "哔哩")) and "其他版本" not in f:
                n = len([e for e in uu[i].split("#") if e])
                if 6 <= n <= 80:
                    oi, oc = i, n
                    break
        if oi is None:
            return
        keep = []
        for i, (f, u) in enumerate(zip(ff, uu)):
            n = len([e for e in u.split("#") if e])
            # 网盘线已经按“完整集数”筛过，不再被官方集数上限砍掉（UC 82 集这类合集要保留）
            if (i == oi or n <= oc * 1.5 or f.startswith("网盘·")
                    or "BL线路" in f or f.startswith("哔哩")):

                keep.append((f, u))
        v["vod_play_from"] = "$$$".join(f for f, _ in keep)
        v["vod_play_url"] = "$$$".join(u for _, u in keep)
    except Exception:
        pass


class DoubanSpider(BaseSpider):
    def __init__(self):
        try:
            super().__init__()
        except Exception:
            pass
        self.agg_on = True

    def getName(self):
        return "豆瓣"

    def init(self, extend=""):
        try:
            _bind_net(getattr(self, "net", None))
        except Exception:
            pass
        global AGG_ON, BD_COOKIE, BD_CLEAN_TEMP
        AGG_ON = True
        self.agg_on = True
        # 只用配置中心/本地包登录写出的百度 Cookie，不再使用内置 Cookie
        _bd_cfg = _bd_cookie_norm(_cfg_cookie("baidu.txt"))
        if _bd_cfg:
            BD_COOKIE = _bd_cfg.strip()
            # 换 Cookie 必须清掉旧账号的 bdstoken 和转存缓存，否则删除会拿错 token
            _BD_BDS_TOKEN["v"] = ""
            BD_TRANSFER_CACHE.clear()
            BD_TRANSFER_FID.clear()
        if isinstance(extend, str) and extend.strip():
            try:
                options = json.loads(extend)
            except ValueError:
                options = None
            if isinstance(options, dict):
                flag = _dump(options.get("agg4k") or options.get("agg") or "1").lower()
                self.agg_on = flag not in ("0", "off", "false", "no")
                AGG_ON = self.agg_on
                # 腾讯会员 Cookie（填了才会给 1080P/4K，官方免登录只到 720P 档）
                cookie = _dump(options.get("tx_cookie") or options.get("txcookie") or "")
                if cookie:
                    global TX_COOKIE
                    TX_COOKIE = cookie
                _bd = _bd_cookie_norm(options.get("bd_cookie") or options.get("bduss") or options.get("BDUSS") or "")
                if _bd:
                    BD_COOKIE = _bd.strip()
                    _BD_BDS_TOKEN["v"] = ""
                    BD_TRANSFER_CACHE.clear()
                    BD_TRANSFER_FID.clear()
                _clean = _dump(options.get("bd_clean_temp") or options.get("bd_clean") or "1").lower()
                BD_CLEAN_TEMP = _clean in ("1", "on", "true", "yes")
        if BD_CLEAN_TEMP and BD_COOKIE:
            try:
                _bd_obj = BaiduDrive(BD_COOKIE)
                threading.Thread(target=_bd_obj.clean_temp, daemon=True).start()
            except Exception:
                pass
        return None

